	"SEQ_NO" NUMBER, 
	"IS_ACTIVE" VARCHAR2(1) DEFAULT 'Y' NOT NULL ENABLE, 
	"REMARKS" VARCHAR2(200), 
	 CONSTRAINT "CORE_YEARS_CK1" CHECK (is_active in ('Y','N')) ENABLE,
	 CONSTRAINT "CORE_YEARS_UK1" UNIQUE ("YEAR_NO")
  USING INDEX  ENABLE,
	 CONSTRAINT "CORE_YEARS_PK" PRIMARY KEY ("YEAR_ID")
  USING INDEX  ENABLE
   ) ;

