  USING INDEX  ENABLE
   ) ;

CREATE TABLE "HR_APPROVAL_MODULES" 
   (	"MODULE_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"MODULE_CODE" VARCHAR2(50), 
	"MODULE_NAME" VARCHAR2(150) NOT NULL ENABLE, 
	"IS_ACTIVE" CHAR(1) DEFAULT 'Y' NOT NULL ENABLE, 
	"SEQ_NO" NUMBER, 
	 CHECK (is_active in ('Y','N')) ENABLE,
	 CONSTRAINT "HR_APPROVAL_MODULES_UK1" UNIQUE ("MODULE_CODE")
  USING INDEX  ENABLE,
	 CONSTRAINT "HR_APPROVAL_MODULES_PK" PRIMARY KEY ("MODULE_ID")
  USING INDEX  ENABLE
   ) ;

CREATE TABLE "HR_APPROVAL_REQUEST_STEPS" 
   (	"APPROVAL_STEP_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"APPROVAL_ID" NUMBER NOT NULL ENABLE, 
	"STEP_SEQ" NUMBER NOT NULL ENABLE, 
	"STEP_NAME" VARCHAR2(150), 
	"APPROVER_TYPE" VARCHAR2(30) NOT NULL ENABLE, 
	"APPROVER_USER_NAME" VARCHAR2(100), 
	"APPROVER_ROLE_CODE" VARCHAR2(100), 
	"APPROVER_USERS" VARCHAR2(4000), 
	"STEP_STATUS" VARCHAR2(30) DEFAULT 'PENDING' NOT NULL ENABLE, 
	"ACTION_BY" VARCHAR2(100), 
	"ACTION_DT" TIMESTAMP (0), 
	"COMMENTS" VARCHAR2(4000), 
	"CREATED_BY" VARCHAR2(100), 
	"CREATED_DT" TIMESTAMP (0), 
	"UPDATED_BY" VARCHAR2(100), 
