	 CONSTRAINT "CHK_DOC_TYPE_EXPIRY" CHECK (is_expiry_required in ('Y','N')) ENABLE, 
	 CONSTRAINT "CHK_DOC_TYPE_NUMBER" CHECK (is_number_required in ('Y','N')) ENABLE,
	 CONSTRAINT "HR_DOC_TYPE_MASTER_UK1" UNIQUE ("DOC_TYPE_CODE")
  USING INDEX  ENABLE, 
	 CONSTRAINT "CHK_DOC_TYPE_MANDATORY" CHECK (is_mandatory in ('Y','N')) ENABLE,
	 CONSTRAINT "HR_DOC_TYPE_MASTER_PK" PRIMARY KEY ("DOC_TYPE_ID")
  USING INDEX  ENABLE
   ) ;

CREATE TABLE "HR_EMP_ACTIONS" 
   (	"ACTION_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"EMP_ID" NUMBER NOT NULL ENABLE, 
	"ACTION_TYPE" VARCHAR2(30) NOT NULL ENABLE, 
	"TARGET_STATUS" VARCHAR2(30) NOT NULL ENABLE, 
	"ACTION_DT" DATE DEFAULT trunc(sysdate) NOT NULL ENABLE, 
	"AMOUNT" NUMBER, 
	"REMARKS" VARCHAR2(4000), 
	"ATTACHMENT_REF" VARCHAR2(4000), 
	"STATUS" VARCHAR2(20) DEFAULT 'DONE' NOT NULL ENABLE, 
	"CREATED_BY" VARCHAR2(100) DEFAULT coalesce(sys_context('APEX$SESSION','APP_USER'), user) NOT NULL ENABLE, 
	"CREATED_DT" TIMESTAMP (0) DEFAULT systimestamp NOT NULL ENABLE, 
	 CHECK (status in ('DRAFT','DONE','CANCELLED')) ENABLE, 
	 PRIMARY KEY ("ACTION_ID")
  USING INDEX  ENABLE
   ) ;

CREATE TABLE "HR_EMP_CHARGE_INSTALLMENTS" 
   (	"INSTALLMENT_ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"EMP_CHARGE_ID" NUMBER NOT NULL ENABLE, 
	"INSTALLMENT_NO" NUMBER NOT NULL ENABLE, 
	"DUE_DT" DATE NOT NULL ENABLE, 
	"AMOUNT" NUMBER(12,2) NOT NULL ENABLE, 
	"STATUS_CODE" VARCHAR2(20) DEFAULT 'PENDING' NOT NULL ENABLE, 
	"HOLD_FROM_DT" DATE, 
	"HOLD_TO_DT" DATE, 
	"PAYROLL_RUN_REF" VARCHAR2(100), 
	"PROCESSED_TS" TIMESTAMP (6), 
	"REMARKS" VARCHAR2(500), 
	"CREATED_BY" VARCHAR2(100), 
	"CREATED_DT" DATE, 
	"UPDATED_BY" VARCHAR2(100), 
	"UPDATED_DT" DATE, 
	 CONSTRAINT "HR_EMP_CHARGE_INSTALLMENTS_CK2" CHECK (
        amount > 0
    ) ENABLE, 
	 CONSTRAINT "HR_EMP_CHARGE_INSTALLMENTS_CK3" CHECK (
        hold_to_dt is null
        or hold_from_dt is null
        or hold_to_dt >= hold_from_dt
    ) ENABLE, 
	 CONSTRAINT "HR_EMP_CHARGE_INSTALLMENTS_PK" PRIMARY KEY ("INSTALLMENT_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "HR_EMP_CHARGE_INSTALLMENTS_UK1" UNIQUE ("EMP_CHARGE_ID", "INSTALLMENT_NO")
  USING INDEX  ENABLE
   ) ;

CREATE TABLE "HR_EMP_CHARGES" 
   (	"EMP_CHARGE_ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"EMP_ID" NUMBER NOT NULL ENABLE, 
	"CHARGE_TYPE" VARCHAR2(240) NOT NULL ENABLE, 
	"RECURRENCE_TYPE" VARCHAR2(20) DEFAULT 'ONE_TIME' NOT NULL ENABLE, 
	"CHARGE_TS" DATE NOT NULL ENABLE, 
	"AMOUNT" NUMBER NOT NULL ENABLE, 
	"SOURCE_START_DT" DATE, 
	"SOURCE_END_DT" DATE, 
	"SOURCE_TABLE_NAME" VARCHAR2(50), 
	"SOURCE_ROW_ID" NUMBER, 
	"BIKE_ID" NUMBER, 
	"CHARGE_TO_EMPLOYEE_YN" VARCHAR2(1) DEFAULT 'Y' NOT NULL ENABLE, 
	"EXCLUDED_FROM_CHARGE_YN" VARCHAR2(1) DEFAULT 'N' NOT NULL ENABLE, 
	"APPROVAL_STATUS" VARCHAR2(20) DEFAULT 'APPROVED' NOT NULL ENABLE, 
	"PAYROLL_DEDUCTION_CODE" VARCHAR2(50), 
	"PAYROLL_PROCESSED_YN" VARCHAR2(1) DEFAULT 'N' NOT NULL ENABLE, 
	"REMARKS" VARCHAR2(500), 
	"CREATED_BY" VARCHAR2(100), 
	"CREATED_DT" DATE, 
	"UPDATED_BY" VARCHAR2(100), 
	"UPDATED_DT" DATE, 
	 CONSTRAINT "HR_EMP_CHARGES_CK3" CHECK (
        charge_to_employee_yn in ('Y','N')
    ) ENABLE, 
	 CONSTRAINT "HR_EMP_CHARGES_CK4" CHECK (
        excluded_from_charge_yn in ('Y','N')
    ) ENABLE, 
	 CONSTRAINT "HR_EMP_CHARGES_CK5" CHECK (
        payroll_processed_yn in ('Y','N')
    ) ENABLE, 
	 CONSTRAINT "HR_EMP_CHARGES_CK7" CHECK (
        amount > 0
    ) ENABLE, 
	 CONSTRAINT "HR_EMP_CHARGES_CK8" CHECK (
        source_end_dt is null
        or source_start_dt is null
        or source_end_dt >= source_start_dt
    ) ENABLE, 
	 CONSTRAINT "HR_EMP_CHARGES_PK" PRIMARY KEY ("EMP_CHARGE_ID")
  USING INDEX  ENABLE
   ) ;

CREATE TABLE "HR_EMP_DOCS" 
   (	"DOC_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
