  USING INDEX  ENABLE
   ) ;

CREATE TABLE "HR_EMP_LEGAL_PROFILE" 
   (	"LEGAL_PROFILE_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"EMP_ID" NUMBER NOT NULL ENABLE, 
	"LEGAL_WORKER_TYPE" VARCHAR2(30) DEFAULT 'OWN_VISA' NOT NULL ENABLE, 
	"LEGAL_ORG_ID" NUMBER, 
	"EXTERNAL_SPONSOR_NAME" VARCHAR2(300), 
	"EXTERNAL_SPONSOR_REF" VARCHAR2(100), 
	"LEGAL_STATUS" VARCHAR2(30) DEFAULT 'IN_PROCESS' NOT NULL ENABLE, 
	"LEGAL_STATUS_REASON" VARCHAR2(1000), 
	"LEGAL_STATUS_DT" DATE, 
	"LEGAL_CASE_REF" VARCHAR2(100), 
	"LEGAL_CASE_REMARKS" VARCHAR2(2000), 
	"WPS_REQUIRED_YN" VARCHAR2(1) DEFAULT 'Y' NOT NULL ENABLE, 
	"WPS_STATUS" VARCHAR2(30) DEFAULT 'SETUP_PENDING' NOT NULL ENABLE, 
	"DEFAULT_WPS_CLEARING_MODE" VARCHAR2(40) DEFAULT 'INTERNAL_WPS' NOT NULL ENABLE, 
	"WPS_CONTRACT_SALARY" NUMBER(12,2), 
	"WPS_SALARY_AMOUNT" NUMBER(12,2), 
	"WPS_EFFECTIVE_FROM_DT" DATE, 
	"WPS_REMARKS" VARCHAR2(4000), 
	"REMARKS" VARCHAR2(4000), 
	"CREATED_BY" VARCHAR2(100), 
	"CREATED_DT" TIMESTAMP (6), 
	"UPDATED_BY" VARCHAR2(100), 
	"UPDATED_DT" TIMESTAMP (6), 
	 CONSTRAINT "CHK_EMP_WPS_REQUIRED" CHECK (wps_required_yn in ('Y','N')) ENABLE, 
	 CONSTRAINT "CHK_EMP_WPS_STATUS" CHECK (wps_status in (
            'SETUP_PENDING',
            'ACTIVE',
            'BLOCKED',
            'NOT_REQUIRED',
            'EXCEPTION'
        )) ENABLE, 
	 CONSTRAINT "CHK_EMP_DEFAULT_WPS_MODE" CHECK (default_wps_clearing_mode in (
            'INTERNAL_WPS',
            'OUTSIDE_CLEARING',
            'SUPPLIER_WPS',
            'NOT_REQUIRED',
            'BLOCKED',
            'MANAGEMENT_EXCEPTION'
        )) ENABLE, 
	 CONSTRAINT "PK_EMP_LEGAL_PROFILE" PRIMARY KEY ("LEGAL_PROFILE_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UK_EMP_LEGAL_PROFILE_EMP" UNIQUE ("EMP_ID")
  USING INDEX  ENABLE, 
	 CONSTRAINT "CHK_EMP_LEGAL_WORKER_TYPE" CHECK (
    legal_worker_type IN (
        'OWN_VISA',
        'GROUP_COMPANY',
        'SUBCONTRACT',
        'FREELANCE',
        'FAMILY_SPONSORED',
        'GOLDEN_VISA',
        'LABOUR_CARD',
