-- ---------- VIEWS (20) ----------

CREATE OR REPLACE FORCE EDITIONABLE VIEW "HR_EMP_DOCS_V" ("DOC_ID", "EMP_ID", "EMP_CODE", "EMPLOYEE_NAME", "DOC_TYPE", "DOC_TYPE_NAME", "DOC_GROUP", "IS_MANDATORY", "DOC_NO", "ISSUE_DT", "EXPIRY_DT", "IS_CURRENT_RECORD", "RELATED_ID_REC_ID", "FILE_REF", "FILE_NAME", "MIME_TYPE", "FILE_SIZE", "REMARKS", "EXPIRY_IN_DAYS", "EXPIRY_STATUS", "CREATED_BY", "CREATED_DT", "UPDATED_BY", "UPDATED_DT") AS 
  select d.doc_id,
       d.emp_id,
       e.emp_code,
       trim(e.first_name || ' ' || e.last_name) employee_name,

       d.doc_type,
       t.doc_type_name,
       t.doc_group,
       nvl(t.is_mandatory,'N') is_mandatory,

       d.doc_no,
       d.issue_dt,
       d.expiry_dt,
       d.is_current_record,
       d.related_id_rec_id,
       d.file_ref,
       d.file_name,
       d.mime_type,
       d.file_size,
       d.remarks,

       case
           when d.expiry_dt is null then null
           else trunc(d.expiry_dt) - trunc(cast(systimestamp at time zone 'Asia/Dubai' as date))
       end expiry_in_days,

       case
           when d.expiry_dt is null then 'NO_EXPIRY'
           when trunc(d.expiry_dt) < trunc(cast(systimestamp at time zone 'Asia/Dubai' as date)) then 'EXPIRED'
           when trunc(d.expiry_dt) <= trunc(cast(systimestamp at time zone 'Asia/Dubai' as date)) + 30 then 'EXPIRING_SOON'
           else 'VALID'
       end expiry_status,

       d.created_by,
       d.created_dt,
       d.updated_by,
       d.updated_dt
from hr_emp_docs d
join hr_employees e
  on e.emp_id = d.emp_id
left join hr_doc_type_master t
  on t.doc_type_code = d.doc_type;

CREATE OR REPLACE FORCE EDITIONABLE VIEW "HR_EMP_LEGAL_PROFILE_V" ("LEGAL_PROFILE_ID", "EMP_ID", "EMP_CODE", "EMPLOYEE_NAME", "EMPLOYEE_WORKER_TYPE", "EMPLOYEE_SUPPLIER_ID", "SUPPLIER_NAME", "LEGAL_WORKER_TYPE", "LEGAL_ORG_ID", "LEGAL_ORG_NAME", "EXTERNAL_SPONSOR_NAME", "EXTERNAL_SPONSOR_REF", "LEGAL_PARTY_NAME", "LEGAL_STATUS", "LEGAL_STATUS_NAME", "LEGAL_STATUS_NATURE", "LEGAL_STATUS_BADGE_CLASS", "LEGAL_STATUS_SEQ_NO", "LEGAL_STATUS_REASON", "LEGAL_STATUS_DT", "LEGAL_CASE_REF", "LEGAL_CASE_REMARKS", "PASSPORT_NO", "PASSPORT_ISSUE_DT", "PASSPORT_EXPIRY_DT", "EMIRATES_ID_NO", "EMIRATES_ID_ISSUE_DT", "EMIRATES_ID_EXPIRY_DT", "VISA_NO", "VISA_ISSUE_DT", "VISA_EXPIRY_DT", "LABOUR_CARD_NO", "LABOUR_CARD_ISSUE_DT", "LABOUR_CARD_EXPIRY_DT", "LABOUR_CONTRACT_NO", "LABOUR_CONTRACT_DT", "WORK_PERMIT_NO", "WORK_PERMIT_ISSUE_DT", "WORK_PERMIT_EXPIRY_DT", "PASSPORT_EXPIRY_DAYS", "EID_EXPIRY_DAYS", "VISA_EXPIRY_DAYS", "LABOUR_CARD_EXPIRY_DAYS", "WPS_REQUIRED_YN", "WPS_STATUS", "DEFAULT_WPS_CLEARING_MODE", "WPS_CONTRACT_SALARY", "WPS_SALARY_AMOUNT", "WPS_EFFECTIVE_FROM_DT", "WPS_REMARKS", "WPS_CLEARING_DISPLAY", "REMARKS", "CREATED_BY", "CREATED_DT", "UPDATED_BY", "UPDATED_DT") AS 
  with docs as (
    select emp_id,

           max(case when doc_type = 'PASSPORT' then doc_no end) passport_no,
           max(case when doc_type = 'PASSPORT' then issue_dt end) passport_issue_dt,
           max(case when doc_type = 'PASSPORT' then expiry_dt end) passport_expiry_dt,

           max(case when doc_type = 'EMIRATES_ID' then doc_no end) emirates_id_no,
           max(case when doc_type = 'EMIRATES_ID' then issue_dt end) emirates_id_issue_dt,
           max(case when doc_type = 'EMIRATES_ID' then expiry_dt end) emirates_id_expiry_dt,

           max(case when doc_type = 'VISA_PAGE' then doc_no end) visa_no,
           max(case when doc_type = 'VISA_PAGE' then issue_dt end) visa_issue_dt,
           max(case when doc_type = 'VISA_PAGE' then expiry_dt end) visa_expiry_dt,

           max(case when doc_type = 'LABOUR_CARD' then doc_no end) labour_card_no,
           max(case when doc_type = 'LABOUR_CARD' then issue_dt end) labour_card_issue_dt,
           max(case when doc_type = 'LABOUR_CARD' then expiry_dt end) labour_card_expiry_dt,

           max(case when doc_type = 'LABOUR_CONTRACT' then doc_no end) labour_contract_no,
           max(case when doc_type = 'LABOUR_CONTRACT' then issue_dt end) labour_contract_dt,

           max(case when doc_type = 'WORK_PERMIT' then doc_no end) work_permit_no,
           max(case when doc_type = 'WORK_PERMIT' then issue_dt end) work_permit_issue_dt,
           max(case when doc_type = 'WORK_PERMIT' then expiry_dt end) work_permit_expiry_dt
      from hr_emp_docs
     where is_current_record = 'Y'
     group by emp_id
)
select lp.legal_profile_id,
       lp.emp_id,
       e.emp_code,
       trim(e.first_name || ' ' || e.last_name) employee_name,

       e.worker_type employee_worker_type,
       e.supplier_id employee_supplier_id,
       fs.supplier_name,

       lp.legal_worker_type,
       lp.legal_org_id,
       lo.org_name legal_org_name,

       lp.external_sponsor_name,
       lp.external_sponsor_ref,

       case
           when lp.legal_worker_type in ('OWN_VISA','GROUP_COMPANY') then lo.org_name
           when lp.legal_worker_type = 'SUBCONTRACT' then fs.supplier_name
           when lp.legal_worker_type in ('FREELANCE','FAMILY_SPONSORED','GOLDEN_VISA','OTHER') then lp.external_sponsor_name
           else null
       end legal_party_name,

       lp.legal_status,

       nvl(
           sm.status_name,
           replace(
               initcap(
                   lower(
                       replace(lp.legal_status, 'LEGAL_', '')
                   )
               ),
               '_',
               ' '
           )
       ) legal_status_name,

       sm.status_nature legal_status_nature,
       sm.badge_class legal_status_badge_class,
       sm.seq_no legal_status_seq_no,

       lp.legal_status_reason,
       lp.legal_status_dt,
       lp.legal_case_ref,
       lp.legal_case_remarks,

       d.passport_no,
       d.passport_issue_dt,
       d.passport_expiry_dt,

       d.emirates_id_no,
       d.emirates_id_issue_dt,
       d.emirates_id_expiry_dt,

       d.visa_no,
       d.visa_issue_dt,
       d.visa_expiry_dt,

       d.labour_card_no,
       d.labour_card_issue_dt,
       d.labour_card_expiry_dt,

       d.labour_contract_no,
       d.labour_contract_dt,

       d.work_permit_no,
       d.work_permit_issue_dt,
       d.work_permit_expiry_dt,

       case
           when d.passport_expiry_dt is null then null
           else trunc(d.passport_expiry_dt) - trunc(cast(systimestamp at time zone 'Asia/Dubai' as date))
       end passport_expiry_days,

       case
           when d.emirates_id_expiry_dt is null then null
           else trunc(d.emirates_id_expiry_dt) - trunc(cast(systimestamp at time zone 'Asia/Dubai' as date))
       end eid_expiry_days,

       case
           when d.visa_expiry_dt is null then null
           else trunc(d.visa_expiry_dt) - trunc(cast(systimestamp at time zone 'Asia/Dubai' as date))
       end visa_expiry_days,

       case
           when d.labour_card_expiry_dt is null then null
           else trunc(d.labour_card_expiry_dt) - trunc(cast(systimestamp at time zone 'Asia/Dubai' as date))
       end labour_card_expiry_days,

       lp.wps_required_yn,
       lp.wps_status,
       lp.default_wps_clearing_mode,
       lp.wps_contract_salary,
       lp.wps_salary_amount,
       lp.wps_effective_from_dt,
       lp.wps_remarks,

       case
           when lp.default_wps_clearing_mode = 'INTERNAL_WPS' then 'WPS inside company'
           when lp.default_wps_clearing_mode = 'OUTSIDE_CLEARING' then 'WPS outside clearing'
           when lp.default_wps_clearing_mode = 'SUPPLIER_WPS' then 'Supplier WPS'
           when lp.default_wps_clearing_mode = 'NOT_REQUIRED' then 'WPS not required'
           when lp.default_wps_clearing_mode = 'BLOCKED' then 'WPS blocked'
           when lp.default_wps_clearing_mode = 'MANAGEMENT_EXCEPTION' then 'Management exception'
           else lp.default_wps_clearing_mode
       end wps_clearing_display,

       lp.remarks,
       lp.created_by,
       lp.created_dt,
       lp.updated_by,
       lp.updated_dt
from hr_emp_legal_profile lp
join hr_employees e
  on e.emp_id = lp.emp_id
left join docs d
  on d.emp_id = lp.emp_id
left join hr_orgs lo
  on lo.org_id = lp.legal_org_id
left join fin_suppliers fs
  on fs.supplier_id = e.supplier_id
left join hr_status_master sm
  on sm.status_code =
        case
            when lp.legal_status like 'LEGAL_%' then lp.legal_status
            else 'LEGAL_' || lp.legal_status
        end
 and sm.status_nature = 'LEGAL';

CREATE OR REPLACE FORCE EDITIONABLE VIEW "HR_EMP_LEGAL_STATUS_HIST_V" ("LEGAL_STATUS_HIST_ID", "LEGAL_PROFILE_ID", "EMP_ID", "EMP_CODE", "EMPLOYEE_NAME", "OLD_LEGAL_STATUS", "NEW_LEGAL_STATUS", "LEGAL_STATUS_REASON", "LEGAL_STATUS_DT", "EFFECTIVE_FROM_DT", "EFFECTIVE_TO_DT", "IS_CURRENT_RECORD", "LEGAL_CASE_REF", "REMARKS", "CREATED_BY", "CREATED_DT") AS 
  select h.legal_status_hist_id,
       h.legal_profile_id,
       h.emp_id,
       e.emp_code,
       trim(e.first_name || ' ' || e.last_name) employee_name,

       h.old_legal_status,
       h.new_legal_status,

       h.legal_status_reason,
       h.legal_status_dt,

       h.effective_from_dt,
       h.effective_to_dt,
       h.is_current_record,

       h.legal_case_ref,
       h.remarks,
       h.created_by,
       h.created_dt
from hr_emp_legal_status_hist h
join hr_employees e
  on e.emp_id = h.emp_id;

CREATE OR REPLACE FORCE EDITIONABLE VIEW "HR_EMP_LOAN_V" ("LOAN_ID", "LOAN_NO", "EMP_ID", "EMP_CODE", "EMPLOYEE_NAME", "LOAN_TYPE", "LOAN_AMOUNT", "EMI_AMOUNT", "ISSUE_DT", "START_MONTH", "SOURCE_TYPE", "SOURCE_ID", "APPROVAL_STATUS", "STATUS", "REMARKS", "PAID_AMOUNT", "WAIVED_AMOUNT", "ADJUSTMENT_AMOUNT", "REVERSED_AMOUNT", "BAD_DEBT_AMOUNT", "BALANCE_AMOUNT", "CREATED_BY", "CREATED_DT", "UPDATED_BY", "UPDATED_DT", "AGREED_ADVANCE_AMOUNT") AS 
  select l.loan_id,
       l.loan_no,
       l.emp_id,
       e.emp_code,
       trim(e.first_name || ' ' || e.last_name) employee_name,

       l.loan_type,
       l.loan_amount,
       l.emi_amount,
       l.issue_dt,
       l.start_month,
       l.source_type,
       l.source_id,
       l.approval_status,
       l.status,
       l.remarks,

       nvl((
           select sum(t.amount)
           from hr_emp_loan_txns t
           where t.loan_id = l.loan_id
             and t.approval_status = 'APPROVED'
             and t.txn_type in ('PAYROLL_DEDUCTION','MANUAL_PAYMENT')
       ), 0) paid_amount,

       nvl((
           select sum(t.amount)
           from hr_emp_loan_txns t
           where t.loan_id = l.loan_id
             and t.approval_status = 'APPROVED'
             and t.txn_type = 'WAIVER'
       ), 0) waived_amount,

       nvl((
           select sum(t.amount)
           from hr_emp_loan_txns t
           where t.loan_id = l.loan_id
             and t.approval_status = 'APPROVED'
             and t.txn_type = 'ADJUSTMENT'
       ), 0) adjustment_amount,

       nvl((
           select sum(t.amount)
           from hr_emp_loan_txns t
           where t.loan_id = l.loan_id
             and t.approval_status = 'APPROVED'
             and t.txn_type = 'REVERSAL'
       ), 0) reversed_amount,

       nvl((
           select sum(t.amount)
           from hr_emp_loan_txns t
           where t.loan_id = l.loan_id
             and t.approval_status = 'APPROVED'
             and t.txn_type = 'BAD_DEBT_WRITE_OFF'
       ), 0) bad_debt_amount,

       l.loan_amount
       - nvl((
           select sum(t.amount)
           from hr_emp_loan_txns t
           where t.loan_id = l.loan_id
             and t.approval_status = 'APPROVED'
             and t.txn_type in (
                 'PAYROLL_DEDUCTION',
                 'MANUAL_PAYMENT',
                 'WAIVER',
                 'ADJUSTMENT',
                 'BAD_DEBT_WRITE_OFF'
             )
       ), 0)
       + nvl((
           select sum(t.amount)
           from hr_emp_loan_txns t
           where t.loan_id = l.loan_id
             and t.approval_status = 'APPROVED'
             and t.txn_type = 'REVERSAL'
       ), 0) balance_amount,

       l.created_by,
       l.created_dt,
       l.updated_by,
       l.updated_dt,
nvl(l.agreed_advance_amount,0) agreed_advance_amount
from hr_emp_loans l
join hr_employees e
  on e.emp_id = l.emp_id;

CREATE OR REPLACE FORCE EDITIONABLE VIEW "VW_FLEET_BIKE_CURRENT" ("BIKE_ID", "BIKE_CODE", "PLATE_NO", "PLATE_EMIRATE", "CHASSIS_NO", "ENGINE_NO", "MODEL_ID", "MODEL_NAME", "MODEL_YEAR", "MODEL_YEAR_LABEL", "COLOR_ID", "COLOR_NAME", "OWNERSHIP_TYPE", "VENDOR_ID", "VENDOR_NAME", "VENDOR_SHORT_NAME", "PURCHASE_DT", "PURCHASE_AMOUNT", "CURRENT_MONTHLY_RENT", "CONTRACT_START_DT", "CONTRACT_END_DT", "REMARKS", "IS_ACTIVE", "STATUS_TXN_ID", "BIKE_STATUS_CODE", "BIKE_STATUS_NAME", "STATUS_FROM_DT", "STATUS_TO_DT", "STATUS_REASON_CODE", "STATUS_REMARKS", "CUSTODY_TXN_ID", "CUSTODY_TYPE_CODE", "CUSTODY_TYPE_NAME", "LOCATION_ID", "CUSTODY_LOCATION_NAME", "CUSTODY_FROM_DT", "CUSTODY_TO_DT", "CUSTODY_REASON_CODE", "CUSTODY_REMARKS", "CURRENT_BIKE_ASSIGN_ID", "CURRENT_EMP_ID", "EMPLOYEE_NAME", "EMP_CODE", "CURRENT_PROJECT", "NATIONALITY", "CURRENT_ASSIGN_DT", "CURRENT_EXPECTED_RETURN_DT", "CURRENT_ISSUE_CONDITION", "CURRENT_ASSIGN_REMARKS", "MULKIYA_DOC_ID", "MULKIYA_NO", "MULKIYA_ISSUE_DT", "MULKIYA_EXPIRY_DT", "INSURANCE_DOC_ID", "INSURANCE_NO", "INSURANCE_ISSUE_DT", "INSURANCE_EXPIRY_DT", "MULKIYA_BUCKET", "INSURANCE_BUCKET", "UTILIZATION_BUCKET") AS 
  with curr_assign as (
    select a.*
      from (
            select a.*,
                   row_number() over (
                       partition by a.bike_id
                       order by a.assign_dt desc, a.bike_assign_id desc
                   ) rn
              from fleet_bike_assignments a
             where a.status_code = 'ACTIVE'
               and a.return_dt is null
           ) a
     where a.rn = 1
),
curr_status as (
    select s.*
      from (
            select s.*,
                   row_number() over (
                       partition by s.bike_id
                       order by s.from_dt desc, s.status_txn_id desc
                   ) rn
              from fleet_bike_status_txns s
             where s.to_dt is null
           ) s
     where s.rn = 1
),
curr_custody as (
    select c.*
      from (
            select c.*,
                   row_number() over (
                       partition by c.bike_id
                       order by c.from_dt desc, c.custody_txn_id desc
                   ) rn
              from fleet_bike_custody_txns c
             where c.to_dt is null
           ) c
     where c.rn = 1
)
select b.bike_id,
       b.bike_code,
       b.plate_no,
       b.plate_emirate,
       b.chassis_no,
       b.engine_no,
       b.model_id,
       m.model_name,
       b.model_year,
       y.year_label as model_year_label,
       b.color_id,
       c.color_name,
       b.ownership_type,
       b.vendor_id,
       fs.supplier_name as vendor_name,
       fs.short_name as vendor_short_name,
       b.purchase_dt,
       b.purchase_amount,
       b.current_monthly_rent,
       b.contract_start_dt,
       b.contract_end_dt,
       b.remarks,
       b.is_active,

       st.status_txn_id,
       st.bike_status_code,
       rs.status_name as bike_status_name,
       st.from_dt as status_from_dt,
       st.to_dt as status_to_dt,
       st.reason_code as status_reason_code,
       st.remarks as status_remarks,

       ct.custody_txn_id,
       ct.custody_type_code,
       rct.custody_type_name,
       ct.location_id,
       rcl.location_name as custody_location_name,
       ct.from_dt as custody_from_dt,
       ct.to_dt as custody_to_dt,
       ct.reason_code as custody_reason_code,
       ct.remarks as custody_remarks,

       ca.bike_assign_id as current_bike_assign_id,

       ca.emp_id as current_emp_id,
       emp.FULL_EMPLOYEE_NAME as employee_name,
       emp.EMP_CODE,
       emp.CURRENT_PROJECT,
       emp.nationality,
       
       ca.assign_dt as current_assign_dt,
       ca.expected_return_dt as current_expected_return_dt,
       ca.issue_condition as current_issue_condition,
       ca.remarks as current_assign_remarks,

        d.mulkiya_doc_id,
       d.mulkiya_no,
       d.mulkiya_issue_dt,
       d.mulkiya_expiry_dt,

       d.insurance_doc_id,
       d.insurance_no,
       d.insurance_issue_dt,
       d.insurance_expiry_dt,

       case
         when d.mulkiya_expiry_dt is null then 'NO_DATE'
         when d.mulkiya_expiry_dt < trunc(sysdate) then 'EXPIRED'
         when d.mulkiya_expiry_dt <= trunc(sysdate) + 30 then 'DUE_SOON'
         else 'VALID'
       end as mulkiya_bucket,

       case
         when d.insurance_expiry_dt is null then 'NO_DATE'
         when d.insurance_expiry_dt < trunc(sysdate) then 'EXPIRED'
         when d.insurance_expiry_dt <= trunc(sysdate) + 30 then 'DUE_SOON'
         else 'VALID'
       end as insurance_bucket,

       case
         when st.bike_status_code = 'ASSIGNED' then 'PRODUCTIVE'
         when st.bike_status_code = 'AVAILABLE' then 'IDLE_READY'
         when st.bike_status_code in ('ACCIDENT','MAINTENANCE') then 'IDLE_REPAIR'
         when st.bike_status_code in ('IMPOUND','POLICE_CUSTODY') then 'IDLE_LEGAL'
         else 'OTHER'
       end as utilization_bucket

  from fleet_bikes b
  left join curr_assign ca
    on ca.bike_id = b.bike_id
  left join curr_status st
    on st.bike_id = b.bike_id
  left join fleet_ref_bike_statuses rs
    on rs.status_code = st.bike_status_code
  left join curr_custody ct
    on ct.bike_id = b.bike_id
  left join fleet_ref_custody_types rct
    on rct.custody_type_code = ct.custody_type_code
  left join fleet_ref_custody_locations rcl
    on rcl.location_id = ct.location_id
  left join fleet_ref_models m
    on m.model_id = b.model_id
  left join core_years y
    on y.year_no = b.model_year
  left join fleet_ref_colors c
    on c.color_id = b.color_id
  left join fin_suppliers fs
    on fs.supplier_id = b.vendor_id
  left join vw_fleet_bike_doc_summary d
    on d.bike_id = b.bike_id
    left join VW_HR_EMPLOYEE_LIST emp
    on emp.emp_id = ca.emp_id;

CREATE OR REPLACE FORCE EDITIONABLE VIEW "VW_FLEET_BIKE_DOC_LATEST" ("BIKE_ID", "DOC_TYPE", "BIKE_DOC_ID", "DOC_NO", "ISSUE_DT", "EXPIRY_DT", "FILE_NAME", "IS_CURRENT") AS 
  with x as (
    select d.bike_id,
           upper(trim(d.doc_type)) as doc_type,
           d.bike_doc_id,
           d.doc_no,
           d.issue_dt,
           d.expiry_dt,
           d.file_name,
           d.is_current,
           row_number() over (
               partition by d.bike_id, upper(trim(d.doc_type))
               order by case when nvl(d.is_current,'N') = 'Y' then 1 else 2 end,
                        nvl(d.expiry_dt, date '1900-01-01') desc,
                        d.bike_doc_id desc
           ) rn
      from fleet_bike_docs d
)
select bike_id,
       doc_type,
       bike_doc_id,
       doc_no,
       issue_dt,
       expiry_dt,
       file_name,
       is_current
  from x
 where rn = 1;

CREATE OR REPLACE FORCE EDITIONABLE VIEW "VW_FLEET_BIKE_DOC_SUMMARY" ("BIKE_ID", "MULKIYA_DOC_ID", "MULKIYA_NO", "MULKIYA_ISSUE_DT", "MULKIYA_EXPIRY_DT", "MULKIYA_FILE_NAME", "INSURANCE_DOC_ID", "INSURANCE_NO", "INSURANCE_ISSUE_DT", "INSURANCE_EXPIRY_DT", "INSURANCE_FILE_NAME") AS 
  select bike_id,
max(mulkiya_doc_id) as mulkiya_doc_id,
max(mulkiya_no) as mulkiya_no,
max(mulkiya_issue_dt) as mulkiya_issue_dt,
max(mulkiya_expiry_dt) as mulkiya_expiry_dt,
max(mulkiya_file_name) as mulkiya_file_name,
max(insurance_doc_id) as insurance_doc_id,
max(insurance_no) as insurance_no,
max(insurance_issue_dt) as insurance_issue_dt,
max(insurance_expiry_dt) as insurance_expiry_dt,
max(insurance_file_name) as insurance_file_name
from (
select bike_id,
case when doc_type = 'MULKIYA'   then bike_doc_id end as mulkiya_doc_id,
case when doc_type = 'MULKIYA'   then doc_no end      as mulkiya_no,
 case when doc_type = 'MULKIYA'   then issue_dt end   as mulkiya_issue_dt,
     case when doc_type = 'MULKIYA'   then expiry_dt end   as mulkiya_expiry_dt,
      case when doc_type = 'MULKIYA'   then file_name end  as mulkiya_file_name,

       case when doc_type = 'INSURANCE' then bike_doc_id end as insurance_doc_id,
      case when doc_type = 'INSURANCE' then doc_no end      as insurance_no,
       case when doc_type = 'INSURANCE' then issue_dt end    as insurance_issue_dt,
      case when doc_type = 'INSURANCE' then expiry_dt end  as insurance_expiry_dt,
    case when doc_type = 'INSURANCE' then file_name end   as insurance_file_name
  from vw_fleet_bike_doc_latest
) group by bike_id;

CREATE OR REPLACE FORCE EDITIONABLE VIEW "VW_FLEET_SIM_INVENTORY" ("SIM_ID", "MOBILE_NO", "ICCID_NO", "OPERATOR_CODE", "OPERATOR_NAME", "SIM_STATUS_CODE", "SIM_STATUS_NAME", "SIM_STATUS_BADGE", "OWNERSHIP_TYPE", "OWNER_NAME", "OWNER_SUPPLIER_ID", "EXTERNAL_OWNER_NAME", "EXTERNAL_OWNER_MOBILE", "EXTERNAL_OWNER_REF", "PLAN_NAME", "DATA_PACKAGE", "MONTHLY_COST", "BILL_ACCOUNT_NO", "CONTRACT_NO", "BILLING_REMARKS", "ACTIVATION_DT", "CANCELLATION_DT", "REMARKS", "CURRENT_EMP_ID", "CURRENT_EMP_CODE", "CURRENT_EMPLOYEE_NAME", "CURRENT_ASSIGN_DT", "CURRENT_HOLDER_BADGE") AS 
  select s.sim_id,
       s.mobile_no,
       s.iccid_no,

       s.operator_code,
       op.operator_name,

       s.sim_status_code,
       sm.sim_status_name,

       '<span class="t-Badge ' || sm.badge_class || '">' ||
       apex_escape.html(sm.sim_status_name) ||
       '</span>' as sim_status_badge,

       s.ownership_type,

       case
           when s.ownership_type = 'SUPPLIER' then
               fs.supplier_name
           when s.ownership_type in ('CLIENT','THIRD_PARTY','OTHER','RENTAL') then
               s.external_owner_name
           when s.ownership_type = 'EMPLOYEE' then
               'Employee Own'
           else
               'Company'
       end as owner_name,

       s.owner_supplier_id,
       s.external_owner_name,
       s.external_owner_mobile,
       s.external_owner_ref,

       s.plan_name,
       s.data_package,
       s.monthly_cost,
       s.bill_account_no,
       s.contract_no,
       s.billing_remarks,

       s.activation_dt,
       s.cancellation_dt,
       s.remarks,

       cs.emp_id as current_emp_id,
       cs.emp_code as current_emp_code,
       cs.full_employee_name as current_employee_name,
       cs.assign_dt as current_assign_dt,

       case
           when cs.emp_id is not null then
               '<span class="t-Badge t-Badge--warning">' ||
               apex_escape.html(cs.emp_code || ' - ' || cs.full_employee_name) ||
               '</span>'
           else
               '<span class="t-Badge t-Badge--success">Available</span>'
       end as current_holder_badge

  from fleet_sims s
  join fleet_sim_operators op
    on op.operator_code = s.operator_code
  join fleet_sim_status_master sm
    on sm.sim_status_code = s.sim_status_code
  left join fin_suppliers fs
    on fs.supplier_id = s.owner_supplier_id
  left join vw_hr_emp_current_sims cs
    on cs.sim_id = s.sim_id;

CREATE OR REPLACE FORCE EDITIONABLE VIEW "VW_HR_DOC_CUSTODY_CURRENT" ("EMP_ID", "EMP_CODE", "EMPLOYEE_NAME", "LOG_ID", "DOC_TYPE", "TXN_TYPE", "TXN_DT", "EXTERNAL_STATUS", "HOLDER_TYPE", "HOLDER_USER", "HOLDER_DEPT", "RECEIVED_FROM", "ISSUED_TO", "PURPOSE", "EXPECTED_RETURN_DT", "REMARKS", "HANDLED_BY", "CURRENT_STATUS") AS 
  with latest_log as (
    select l.*,
           row_number() over (
               partition by l.emp_id, l.doc_type
               order by l.txn_dt desc, l.log_id desc
           ) rn
    from hr_doc_custody_log l
    where l.doc_type = 'PASSPORT'
)
select e.emp_id,
       e.emp_code,
       trim(e.first_name || ' ' || nvl(e.last_name,'')) as employee_name,
       ll.log_id,
       ll.doc_type,
       ll.txn_type,
       ll.txn_dt,
       ll.external_status,
       ll.holder_type,
       ll.holder_user,
       ll.holder_dept,
       ll.received_from,
       ll.issued_to,
       ll.purpose,
       ll.expected_return_dt,
       ll.remarks,
       ll.handled_by,
       case
           when ll.emp_id is null then 'PENDING'
           else ll.external_status
       end as current_status
from hr_employees e
left join latest_log ll
       on ll.emp_id = e.emp_id
      and ll.rn = 1;

CREATE OR REPLACE FORCE EDITIONABLE VIEW "VW_HR_EMP_ASSET_CONTROL" ("EMP_ID", "EMP_CODE", "FULL_EMPLOYEE_NAME", "CURRENT_STATUS_CODE", "CURRENT_STATUS_NAME", "CURRENT_LEGAL_CODE", "CURRENT_LEGAL_NAME", "JOB_ID", "JOB_NAME", "WORKER_TYPE", "SUPPLIER_NAME", "BIKE_REQUIRED_YN", "CURRENT_BIKE_ID", "CURRENT_BIKE_DISPLAY", "CURRENT_BIKE_ASSIGN_DT", "OPEN_BIKE_REQUEST_ID", "OPEN_BIKE_REQUEST_TYPE", "OPEN_BIKE_REQUEST_STATUS", "HAS_BIKE_YN", "ACTIVE_ASSIGNMENT_YN", "ACTUALLY_WORKING_YN", "CURRENT_BIKE_BADGE", "ASSET_RISK_CODE", "ASSET_RISK_BADGE", "CAN_PENDING_ACTIVE_YN", "CAN_MARK_ACTIVE_YN", "CAN_BACK_PIPELINE_YN") AS 
  select e.emp_id,
       e.emp_code,
       e.full_employee_name,
       e.current_status_code,
       e.current_status_name,
       e.current_legal_code,
       e.current_legal_name,
       e.job_id,
       e.job_name,
       e.worker_type,
       e.supplier_name,

       nvl(j.bike_required_yn, 'N') as bike_required_yn,

       cb.bike_id      as current_bike_id,
       cb.bike_display as current_bike_display,
       cb.assign_dt    as current_bike_assign_dt,

       br.request_id     as open_bike_request_id,
       br.request_type   as open_bike_request_type,
       br.request_status as open_bike_request_status,

       case
           when cb.bike_id is not null then 'Y'
           else 'N'
       end as has_bike_yn,

       case
           when exists (
                select 1
                  from hr_assignments a
                 where a.emp_id = e.emp_id
                   and a.end_dt is null
           ) then 'Y'
           else 'N'
       end as active_assignment_yn,

       case
           when upper(nvl(e.current_status_code, 'X')) = 'ACTIVE'
            and exists (
                select 1
                  from hr_assignments a
                 where a.emp_id = e.emp_id
                   and a.end_dt is null
           ) then 'Y'
           else 'N'
       end as actually_working_yn,

       ------------------------------------------------------------------
       -- Bike badge for all pages
       ------------------------------------------------------------------
       case
           when cb.bike_id is not null then
               '<span class="t-Badge t-Badge--success">' ||
               apex_escape.html(cb.bike_display) ||
               '</span>'
           else
               '<span class="t-Badge t-Badge--normal">No Bike</span>'
       end as current_bike_badge,

       ------------------------------------------------------------------
       -- Asset risk code
       ------------------------------------------------------------------
       case
           when cb.bike_id is null then
               'NO_BIKE'

           when upper(nvl(e.current_status_code, 'X')) = 'ACTIVE'
            and exists (
                select 1
                  from hr_assignments a
                 where a.emp_id = e.emp_id
                   and a.end_dt is null
           ) then
               'BIKE_OK'

           when replace(upper(nvl(e.current_legal_code, 'NOT_SET')), 'LEGAL_', '') in (
                'ABSCONDING',
                'ABSCONDER'
           ) then
               'BIKE_RECOVERY_PENDING'

           when upper(nvl(e.current_status_code, 'X')) = 'PENDING_ACTIVE' then
               'BIKE_WITH_PENDING_ACTIVE'

           when upper(nvl(e.current_status_code, 'X')) in (
                'READY_TO_ONBOARD',
                'ONBOARDING'
           ) then
               'BIKE_ASSIGNED_BEFORE_ACTIVE'

           when upper(nvl(e.current_status_code, 'X')) = 'VACATION' then
               'BIKE_RETURN_REQUIRED'

           when upper(nvl(e.current_status_code, 'X')) in (
                'OFFBOARD',
                'OFFBOARD_QUEUE'
           ) then
               'BIKE_CLEARANCE_PENDING'

           when upper(nvl(e.current_status_code, 'X')) = 'ACCIDENT' then
               'BIKE_RECOVERY_REQUIRED'

           when upper(nvl(e.current_status_code, 'X')) = 'ABSCONDER' then
               'BIKE_RECOVERY_PENDING'

           else
               'BIKE_WITH_NON_WORKING_EMPLOYEE'
       end as asset_risk_code,

       ------------------------------------------------------------------
       -- Asset risk badge for APEX
       ------------------------------------------------------------------
       case
           when cb.bike_id is null then
               '<span class="t-Badge t-Badge--normal">No Asset Risk</span>'

           when upper(nvl(e.current_status_code, 'X')) = 'ACTIVE'
            and exists (
                select 1
                  from hr_assignments a
                 where a.emp_id = e.emp_id
                   and a.end_dt is null
           ) then
               '<span class="t-Badge t-Badge--success">Bike OK</span>'

           when replace(upper(nvl(e.current_legal_code, 'NOT_SET')), 'LEGAL_', '') in (
                'ABSCONDING',
                'ABSCONDER'
           ) then
               '<span class="t-Badge t-Badge--danger">Bike Recovery Pending</span>'

           when upper(nvl(e.current_status_code, 'X')) = 'PENDING_ACTIVE' then
               '<span class="t-Badge t-Badge--warning">Bike With Pending Active</span>'

           when upper(nvl(e.current_status_code, 'X')) in (
                'READY_TO_ONBOARD',
                'ONBOARDING'
           ) then
               '<span class="t-Badge t-Badge--warning">Bike Assigned Before Active</span>'

           when upper(nvl(e.current_status_code, 'X')) = 'VACATION' then
               '<span class="t-Badge t-Badge--danger">Bike Return Required</span>'

           when upper(nvl(e.current_status_code, 'X')) in (
                'OFFBOARD',
                'OFFBOARD_QUEUE'
           ) then
               '<span class="t-Badge t-Badge--danger">Bike Clearance Pending</span>'

           when upper(nvl(e.current_status_code, 'X')) = 'ACCIDENT' then
               '<span class="t-Badge t-Badge--danger">Bike Recovery Required</span>'

           when upper(nvl(e.current_status_code, 'X')) = 'ABSCONDER' then
               '<span class="t-Badge t-Badge--danger">Bike Recovery Pending</span>'

           else
               '<span class="t-Badge t-Badge--danger">Bike With Non-Working Employee</span>'
       end as asset_risk_badge,

       ------------------------------------------------------------------
       -- Can move Ready To Onboard -> Pending Active?
       ------------------------------------------------------------------
       case
           when upper(nvl(e.current_status_code, 'X')) in (
                    'READY_TO_ONBOARD',
                    'ONBOARDING'
                )
            and replace(upper(nvl(e.current_legal_code, 'NOT_SET')), 'LEGAL_', '') not in (
                    'ABSCONDING',
                    'ABSCONDER',
                    'CANCELLED',
                    'CANCELLED_MOHRE',
                    'CANCELLED_ICP'
                )
            and (
                    nvl(j.bike_required_yn, 'N') = 'N'
                    or cb.bike_id is not null
                )
           then 'Y'
           else 'N'
       end as can_pending_active_yn,

       ------------------------------------------------------------------
       -- Can move Pending Active -> Active?
       ------------------------------------------------------------------
       case
           when upper(nvl(e.current_status_code, 'X')) = 'PENDING_ACTIVE'
            and replace(upper(nvl(e.current_legal_code, 'NOT_SET')), 'LEGAL_', '') not in (
                    'ABSCONDING',
                    'ABSCONDER',
                    'CANCELLED',
                    'CANCELLED_MOHRE',
                    'CANCELLED_ICP'
                )
            and exists (
                    select 1
                      from hr_assignments a
                     where a.emp_id = e.emp_id
                       and a.end_dt is null
                )
            and (
                    nvl(j.bike_required_yn, 'N') = 'N'
                    or cb.bike_id is not null
                )
           then 'Y'
           else 'N'
       end as can_mark_active_yn,

       ------------------------------------------------------------------
       -- Can move wrongly marked Ready To Onboard back to Pipeline?
       ------------------------------------------------------------------
       case
           when upper(nvl(e.current_status_code, 'X')) in (
                    'READY_TO_ONBOARD',
                    'ONBOARDING'
                )
            and cb.bike_id is null
            and br.request_id is null
            and not exists (
                    select 1
                      from hr_assignments a
                     where a.emp_id = e.emp_id
                       and a.end_dt is null
                )
           then 'Y'
           else 'N'
       end as can_back_pipeline_yn

from vw_hr_employee_list e

left join ref_jobs j
       on j.job_id = e.job_id

left join vw_hr_emp_current_bike cb
       on cb.emp_id = e.emp_id

left join vw_hr_emp_open_bike_req br
       on br.emp_id = e.emp_id;

CREATE OR REPLACE FORCE EDITIONABLE VIEW "VW_HR_EMP_BIKE_READINESS" ("EMP_ID", "EMP_CODE", "FULL_EMPLOYEE_NAME", "JOB_ID", "JOB_NAME", "BIKE_REQUIRED_YN", "CURRENT_BIKE_ID", "CURRENT_BIKE_DISPLAY", "CURRENT_BIKE_ASSIGN_DT", "OPEN_REQUEST_ID", "OPEN_REQUEST_TYPE", "OPEN_REQUEST_STATUS", "OPEN_REQUEST_PRIORITY", "BIKE_READINESS_CODE") AS 
  select e.emp_id,
       e.emp_code,
       e.full_employee_name,
       e.job_id,
       e.job_name,

       nvl(j.bike_required_yn, 'N') as bike_required_yn,

       cb.bike_id        as current_bike_id,
      cb.bike_display   as current_bike_display,
       cb.assign_dt      as current_bike_assign_dt,

       br.request_id     as open_request_id,
       br.request_type   as open_request_type,
       br.request_status as open_request_status,
       br.priority       as open_request_priority,

       case
           when nvl(j.bike_required_yn, 'N') = 'N' then
               'NOT_REQUIRED'

           when cb.bike_id is not null
            and br.request_id is not null then
               'REPLACEMENT_REQUESTED'

           when cb.bike_id is not null then
               'ASSIGNED'

           when br.request_id is not null then
               'REQUEST_OPEN'

           else
               'NEEDED'
       end as bike_readiness_code

from vw_hr_employee_list e

left join ref_jobs j
       on j.job_id = e.job_id

left join VW_HR_EMP_CURRENT_BIKE cb
       on cb.emp_id = e.emp_id

left join vw_hr_emp_open_bike_req br
       on br.emp_id = e.emp_id;

CREATE OR REPLACE FORCE EDITIONABLE VIEW "VW_HR_EMP_CURRENT_BIKE" ("EMP_ID", "BIKE_ID", "BIKE_CODE", "PLATE_NO", "ASSIGN_DT", "BIKE_DISPLAY") AS 
  with x as (
    select ba.emp_id,
           ba.bike_id,
           ba.assign_dt,
           ba.BIKE_ASSIGN_ID,
           row_number() over (
               partition by ba.emp_id
               order by ba.assign_dt desc, ba.BIKE_ASSIGN_ID desc
           ) rn
      from fleet_bike_assignments ba
     where ba.return_dt is null
)
select x.emp_id,
       x.bike_id,
       b.bike_code,
       b.plate_no,
       x.assign_dt,
       nvl(b.plate_no,b.bike_code) as bike_display
  from x
  join fleet_bikes b
    on b.bike_id = x.bike_id
 where x.rn = 1;

CREATE OR REPLACE FORCE EDITIONABLE VIEW "VW_HR_EMP_CURRENT_SIMS" ("SIM_ASSIGN_ID", "EMP_ID", "EMP_CODE", "FULL_EMPLOYEE_NAME", "SIM_ID", "MOBILE_NO", "ICCID_NO", "OPERATOR_CODE", "OPERATOR_NAME", "OWNERSHIP_TYPE", "OWNER_SUPPLIER_ID", "OWNER_SUPPLIER_NAME", "EXTERNAL_OWNER_NAME", "EXTERNAL_OWNER_MOBILE", "PLAN_NAME", "DATA_PACKAGE", "MONTHLY_COST", "ASSIGN_DT", "ASSIGN_REASON", "ASSIGNED_BY", "ASSIGN_REMARKS", "SIM_DISPLAY", "SIM_BADGE") AS 
  select sa.sim_assign_id,
       sa.emp_id,
       e.emp_code,
       e.full_employee_name,

       sa.sim_id,
       s.mobile_no,
       s.iccid_no,
       s.operator_code,
       op.operator_name,

       s.ownership_type,
       s.owner_supplier_id,
       fs.supplier_name as owner_supplier_name,
       s.external_owner_name,
       s.external_owner_mobile,

       s.plan_name,
       s.data_package,
       s.monthly_cost,

       sa.assign_dt,
       sa.assign_reason,
       sa.assigned_by,
       sa.assign_remarks,

       s.mobile_no as sim_display,

       '<span class="t-Badge t-Badge--warning">' ||
       apex_escape.html(s.mobile_no) ||
       '</span>' as sim_badge

  from hr_sim_assignments sa
  join fleet_sims s
    on s.sim_id = sa.sim_id
  join fleet_sim_operators op
    on op.operator_code = s.operator_code
  join vw_hr_employee_list e
    on e.emp_id = sa.emp_id
  left join fin_suppliers fs
    on fs.supplier_id = s.owner_supplier_id
 where sa.return_dt is null;

CREATE OR REPLACE FORCE EDITIONABLE VIEW "VW_HR_EMP_INSURANCE_STATUS" ("EMP_ID", "EMP_CODE", "EMPLOYEE_NAME", "INSURANCE_TYPE", "INSURANCE_ID", "PROVIDER_NAME", "POLICY_NO", "MEMBER_CARD_NO", "PLAN_NAME", "CLASS_NAME", "ISSUE_DT", "START_DT", "EXPIRY_DT", "NEAR_EXPIRY_DAYS", "STATUS_CODE", "IS_CURRENT", "CANCEL_DT", "CANCEL_REASON", "CANCELLED_BY", "REMARKS", "INSURANCE_BUCKET", "DAYS_LEFT", "STATUS_BADGE_TEXT", "CURRENT_PROJECT") AS 
  with types as (
    select 'HEALTH' insurance_type from dual
    union all
    select 'WC' insurance_type from dual
),
picked as (
    select i.*,
           row_number() over (
               partition by i.emp_id, i.insurance_type
               order by case when i.is_current = 'Y' then 1 else 2 end,
                        nvl(i.start_dt, date '1900-01-01') desc,
                        i.insurance_id desc
           ) rn
    from hr_emp_insurance i
)
select e.emp_id,
       e.emp_code,
       e.full_employee_name as employee_name,
       t.insurance_type,
       p.insurance_id,
       p.provider_name,
       p.policy_no,
       p.member_card_no,
       p.plan_name,
       p.class_name,
       p.issue_dt,
       p.start_dt,
       p.expiry_dt,
       p.near_expiry_days,
       p.status_code,
       p.is_current,
       p.cancel_dt,
       p.cancel_reason,
       p.cancelled_by,
       p.remarks,
       case
           when p.insurance_id is null then 'PENDING'
           when p.status_code = 'CANCELLED' then 'CANCELLED'
           when p.expiry_dt is not null and p.expiry_dt < trunc(sysdate) then 'EXPIRED'
           when p.expiry_dt is not null
                and p.expiry_dt between trunc(sysdate) and trunc(sysdate) + nvl(p.near_expiry_days,30)
                then 'NEAR_EXPIRY'
           else 'VALID'
       end as insurance_bucket,
       case
           when p.expiry_dt is not null then p.expiry_dt - trunc(sysdate)
       end as days_left,
       e.STATUS_BADGE_TEXT,
       e.current_project
from VW_HR_EMPLOYEE_LIST e
cross join types t
left join picked p
       on p.emp_id = e.emp_id
      and p.insurance_type = t.insurance_type
      and p.rn = 1;

CREATE OR REPLACE FORCE EDITIONABLE VIEW "VW_HR_EMP_OPEN_BIKE_REQ" ("REQUEST_ID", "EMP_ID", "REQUEST_TYPE", "REQUEST_STATUS", "PRIORITY", "REQUESTED_DT", "REQUESTED_BY", "REQUIRED_BY_DT", "CURRENT_BIKE_ID", "ASSIGNED_BIKE_ID", "BIKE_ASSIGNMENT_ID", "REQUESTED_PROJECT_ID", "REQUESTED_CITY_ID", "REASON_CODE", "REQUEST_REMARKS", "REJECTION_REASON", "CLOSED_BY", "CLOSED_DT", "CREATED_BY", "CREATED_DT", "UPDATED_BY", "UPDATED_DT", "RN") AS 
  with r as (
    select br.*,
           row_number() over (
               partition by br.emp_id
               order by br.requested_dt desc, br.request_id desc
           ) rn
      from hr_bike_requests br
     where br.request_status in ('OPEN','IN_PROGRESS')
)
select "REQUEST_ID","EMP_ID","REQUEST_TYPE","REQUEST_STATUS","PRIORITY","REQUESTED_DT","REQUESTED_BY","REQUIRED_BY_DT","CURRENT_BIKE_ID","ASSIGNED_BIKE_ID","BIKE_ASSIGNMENT_ID","REQUESTED_PROJECT_ID","REQUESTED_CITY_ID","REASON_CODE","REQUEST_REMARKS","REJECTION_REASON","CLOSED_BY","CLOSED_DT","CREATED_BY","CREATED_DT","UPDATED_BY","UPDATED_DT","RN"
  from r
 where rn = 1;

CREATE OR REPLACE FORCE EDITIONABLE VIEW "VW_HR_EMP_OPEN_SIM_REQ" ("REQUEST_ID", "EMP_ID", "REQUEST_TYPE", "REQUEST_STATUS", "PRIORITY", "REQUESTED_DT", "REQUESTED_BY", "REQUIRED_BY_DT", "REQUESTED_PROJECT_ID", "REQUESTED_CITY_ID", "CURRENT_SIM_ID", "ASSIGNED_SIM_ID", "SIM_ASSIGN_ID", "REASON_CODE", "REQUEST_REMARKS", "REJECTION_REASON", "CANCELLATION_REASON", "CLOSED_BY", "CLOSED_DT", "CREATED_BY", "CREATED_DT", "UPDATED_BY", "UPDATED_DT", "RN") AS 
  with r as (
    select sr.*,
           row_number() over (
               partition by sr.emp_id
               order by sr.requested_dt desc, sr.request_id desc
           ) rn
      from hr_sim_requests sr
     where sr.request_status in ('OPEN','IN_PROGRESS')
)
select "REQUEST_ID","EMP_ID","REQUEST_TYPE","REQUEST_STATUS","PRIORITY","REQUESTED_DT","REQUESTED_BY","REQUIRED_BY_DT","REQUESTED_PROJECT_ID","REQUESTED_CITY_ID","CURRENT_SIM_ID","ASSIGNED_SIM_ID","SIM_ASSIGN_ID","REASON_CODE","REQUEST_REMARKS","REJECTION_REASON","CANCELLATION_REASON","CLOSED_BY","CLOSED_DT","CREATED_BY","CREATED_DT","UPDATED_BY","UPDATED_DT","RN"
  from r
 where rn = 1;

CREATE OR REPLACE FORCE EDITIONABLE VIEW "VW_HR_EMP_SIM_SUMMARY" ("EMP_ID", "ACTIVE_SIM_COUNT", "ACTIVE_SIM_NUMBERS", "FIRST_SIM_ASSIGN_DT", "LAST_SIM_ASSIGN_DT", "TOTAL_MONTHLY_SIM_COST", "SIM_SUMMARY_BADGE") AS 
  select emp_id,
       count(*) as active_sim_count,
       listagg(mobile_no, ', ') within group (order by assign_dt, sim_id) as active_sim_numbers,
       min(assign_dt) as first_sim_assign_dt,
       max(assign_dt) as last_sim_assign_dt,
       sum(nvl(monthly_cost,0)) as total_monthly_sim_cost,

       case
           when count(*) = 0 then
               '<span class="t-Badge t-Badge--normal">No SIM</span>'
           when count(*) = 1 then
               '<span class="t-Badge t-Badge--warning">' ||
               apex_escape.html(max(mobile_no)) ||
               '</span>'
           else
               '<span class="t-Badge t-Badge--danger">' ||
               count(*) || ' SIMs: ' ||
               apex_escape.html(listagg(mobile_no, ', ') within group (order by assign_dt, sim_id)) ||
               '</span>'
       end as sim_summary_badge

  from vw_hr_emp_current_sims
 group by emp_id;

CREATE OR REPLACE FORCE EDITIONABLE VIEW "VW_HR_EMPLOYEE_LIST" ("EMP_ID", "EMP_CODE", "FIRST_NAME", "LAST_NAME", "FATHER_NAME", "DOB", "FULL_EMPLOYEE_NAME", "EMP_INITIALS", "AGE", "NATIONALITY_COUNTRY_ID", "NATIONALITY", "MOBILE", "EMAIL", "JOIN_DATE", "AGREED_PROJECT_ID", "AGREED_PROJECT", "AGREED_CITY_ID", "AGREED_CITY", "JOB_ID", "JOB_NAME", "REFERENCE_SOURCE", "REFERRED_BY_TEXT", "DEAL_BY_USER", "DEAL_BY_USER_NAME", "HIRE_NOTES", "WORKER_TYPE", "SUPPLIER_ID", "SUPPLIER_NAME", "CONTRACT_REF", "HAS_PHOTO", "CURRENT_PROJECT_ID", "CURRENT_PROJECT", "CURRENT_CITY_ID", "CURRENT_CITY", "LAST_PROJECT_ID", "LAST_PROJECT", "LAST_CITY_ID", "LAST_CITY", "DISPLAY_CURRENT_PROJECT", "DISPLAY_CURRENT_CITY", "DISPLAY_LAST_PROJECT", "DISPLAY_LAST_CITY", "CURRENT_STATUS_CODE", "CURRENT_STATUS_NAME", "STATUS_DISPLAY_TEXT", "STATUS_BADGE_TEXT", "CUSTODY_BADGE", "PAY_MODE_NAME", "INSURANCE_BUCKET_BADGE", "INSURRANCE_BUCKET_TEXT", "WC_INS_BUCKET_BADGE", "WC_INS_BUCKET_TEXT", "PHOTO_BLOB", "CURRENT_LEGAL_CODE", "CURRENT_LEGAL_NAME", "STATUS_PROJECT_ID", "STATUS_PROJECT_NAME", "STATUS_CITY_ID", "STATUS_CITY_NAME") AS 
  with cur_asg as (
    select emp_id,
           project_id,
           city_id,
           job_id,
           start_dt,
           asg_id,
           row_number() over (
               partition by emp_id
               order by start_dt desc, asg_id desc
           ) as rn
      from hr_assignments
     where end_dt is null
),

last_asg as (
    select emp_id,
           project_id,
           city_id,
           job_id,
           start_dt,
           end_dt,
           asg_id,
           row_number() over (
               partition by emp_id
               order by end_dt desc, asg_id desc
           ) as rn
      from hr_assignments
     where end_dt is not null
),

cur_status as (
    select emp_id,
           status_code,
           effective_from,
           status_id,
           project_id,
           city_id,
           row_number() over (
               partition by emp_id
               order by effective_from desc, status_id desc
           ) as rn
      from hr_emp_status_hist
     where effective_to is null
),

curr_pp_status as (
    select emp_id,
           case current_status
               when 'WITH_COMPANY' then
                   '<span class="t-Badge t-Badge--success">With Company</span>'
               when 'WITH_EMPLOYEE' then
                   '<span class="t-Badge t-Badge--warning">With Rider</span>'
               else
                   '<span class="t-Badge t-Badge--danger">Pending</span>'
           end as custody_badge
      from vw_hr_doc_custody_current
),

curr_pay_method as (
    select a.emp_id,
           pm.pay_mode_name
      from hr_emp_pay_modes a
      join hr_pay_mode_master pm
        on pm.pay_mode_code = a.pay_mode_code
     where a.is_active = 'Y'
),

curr_health_ins as (
    select i.*,
           row_number() over (
               partition by i.emp_id, i.insurance_type
               order by case when i.is_current = 'Y' then 1 else 2 end,
                        nvl(i.start_dt, date '1900-01-01') desc,
                        i.insurance_id desc
           ) rn
      from hr_emp_insurance i
     where i.insurance_type = 'HEALTH'
),

curr_wc_ins as (
    select i.*,
           row_number() over (
               partition by i.emp_id, i.insurance_type
               order by case when i.is_current = 'Y' then 1 else 2 end,
                        nvl(i.start_dt, date '1900-01-01') desc,
                        i.insurance_id desc
           ) rn
      from hr_emp_insurance i
     where i.insurance_type = 'WC'
)

select e.emp_id,
       e.emp_code,
       e.first_name,
       e.last_name,
       e.father_name,
       e.dob,

       trim(
           nvl(e.first_name, '') ||
           case
               when e.last_name is not null then ' ' || e.last_name
           end
       ) as full_employee_name,

       upper(
           substr(nvl(e.first_name, 'X'), 1, 1) ||
           substr(nvl(e.last_name,  'X'), 1, 1)
       ) as emp_initials,

       case
           when e.dob is not null then
               trunc(months_between(trunc(sysdate), trunc(e.dob)) / 12)
       end as age,

       e.nationality_country_id,
       nc.country_name as nationality,

       e.mobile,
       e.email,
       e.join_date,

       e.agreed_project_id,
       ap.project_name as agreed_project,

       e.agreed_city_id,
       ac.city_name as agreed_city,

       e.job_id,
       j.job_name,

       e.reference_source,
       e.referred_by_text,
       e.deal_by_user,
       su.username as deal_by_user_name,
       e.hire_notes,

       e.worker_type,
       e.supplier_id,
       fs.supplier_name,
       e.contract_ref,

       case
           when e.photo_blob is not null then 'Y'
           else 'N'
       end as has_photo,

       ca.project_id as current_project_id,
       cp.project_name as current_project,

       ca.city_id as current_city_id,
       cc.city_name as current_city,

       la.project_id as last_project_id,
       lp.project_name as last_project,

       la.city_id as last_city_id,
       lc.city_name as last_city,

       nvl(cp.project_name, ap.project_name) as display_current_project,
       nvl(cc.city_name, ac.city_name)       as display_current_city,

       nvl(lp.project_name, nvl(cp.project_name, ap.project_name)) as display_last_project,
       nvl(lc.city_name,   nvl(cc.city_name, ac.city_name))        as display_last_city,

       ------------------------------------------------------------------
       -- Current Operational Status
       ------------------------------------------------------------------
       cs.status_code as current_status_code,

       nvl(sm.status_name, 'No Status') as current_status_name,

       nvl(sm.status_name, 'No Status') as status_display_text,

       case upper(cs.status_code)
           when 'ACTIVE' then
               '<span class="t-Badge t-Badge--success t-Badge--subtle">Active</span>'

           when 'READY_TO_ONBOARD' then
               '<span class="t-Badge t-Badge--warning t-Badge--subtle">Ready To Onboard</span>'

           when 'PIPELINE' then
               '<span class="t-Badge t-Badge--info t-Badge--subtle">Pipeline</span>'

           when 'IN_PROCESS' then
               '<span class="t-Badge t-Badge--warning t-Badge--subtle">In Process</span>'

           when 'ONBOARDING' then
               '<span class="t-Badge t-Badge--warning t-Badge--subtle">Onboarding</span>'

           when 'ON_HOLD' then
               '<span class="t-Badge t-Badge--danger t-Badge--subtle">On Hold</span>'

           when 'OFFBOARD' then
               '<span class="t-Badge t-Badge--warning">Offboard</span>'

           when 'OFFBOARD_QUEUE' then
               '<span class="t-Badge t-Badge--warning">Offboard Queue</span>'

           when 'VACATION' then
               '<span class="t-Badge t-Badge--info">Vacation</span>'

           when 'ACCIDENT' then
               '<span class="t-Badge t-Badge--danger">Accident</span>'

           when 'ABSCONDER' then
               '<span class="t-Badge t-Badge--danger">Absconder</span>'

           when 'ABS' then
               '<span class="t-Badge t-Badge--danger">Absconder</span>'

           when 'TERMINATED' then
               '<span class="t-Badge t-Badge--danger">Terminated</span>'

           when 'EXITED' then
               '<span class="t-Badge t-Badge--neutral t-Badge--subtle">Exited</span>'

           when 'INACTIVE' then
               '<span class="t-Badge t-Badge--neutral t-Badge--subtle">Inactive</span>'

           else
               '<span class="t-Badge t-Badge--info t-Badge--subtle">' ||
               apex_escape.html(nvl(sm.status_name, 'No Status')) ||
               '</span>'
       end as status_badge_text,

       cus_pp.custody_badge,
       pm.pay_mode_name,

       ------------------------------------------------------------------
       -- Health Insurance
       ------------------------------------------------------------------
       case
           when hins.insurance_id is null then
               '<span class="t-Badge t-Badge--info">PENDING</span>'
           when hins.status_code = 'CANCELLED' then
               '<span class="t-Badge t-Badge--danger t-Badge--outline"><span class="fa fa-ban"></span> CANCELLED</span>'
           when hins.expiry_dt is not null
                and hins.expiry_dt < trunc(sysdate) then
               '<span class="t-Badge t-Badge--danger">EXPIRED</span>'
           when hins.expiry_dt is not null
                and hins.expiry_dt between trunc(sysdate)
                                    and trunc(sysdate) + nvl(hins.near_expiry_days, 30) then
               '<span class="t-Badge t-Badge--warning">NEAR EXPIRY</span>'
           else
               '<span class="t-Badge t-Badge--success">VALID</span>'
       end as insurance_bucket_badge,

       case
           when hins.insurance_id is null then
               'PENDING'
           when hins.status_code = 'CANCELLED' then
               'CANCELLED'
           when hins.expiry_dt is not null
                and hins.expiry_dt < trunc(sysdate) then
               'EXPIRED'
           when hins.expiry_dt is not null
                and hins.expiry_dt between trunc(sysdate)
                                    and trunc(sysdate) + nvl(hins.near_expiry_days, 30) then
               'NEAR EXPIRY'
           else
               'VALID'
       end as insurrance_bucket_text,

       ------------------------------------------------------------------
       -- WC Insurance
       ------------------------------------------------------------------
       case
           when wins.insurance_id is null then
               '<span class="t-Badge t-Badge--info">PENDING</span>'
           when wins.status_code = 'CANCELLED' then
               '<span class="t-Badge t-Badge--danger t-Badge--outline"><span class="fa fa-ban"></span> CANCELLED</span>'
           when wins.expiry_dt is not null
                and wins.expiry_dt < trunc(sysdate) then
               '<span class="t-Badge t-Badge--danger">EXPIRED</span>'
           when wins.expiry_dt is not null
                and wins.expiry_dt between trunc(sysdate)
                                    and trunc(sysdate) + nvl(wins.near_expiry_days, 30) then
               '<span class="t-Badge t-Badge--warning">NEAR EXPIRY</span>'
           else
               '<span class="t-Badge t-Badge--success">VALID</span>'
       end as wc_ins_bucket_badge,

       case
           when wins.insurance_id is null then
               'PENDING'
           when wins.status_code = 'CANCELLED' then
               'CANCELLED'
           when wins.expiry_dt is not null
                and wins.expiry_dt < trunc(sysdate) then
               'EXPIRED'
           when wins.expiry_dt is not null
                and wins.expiry_dt between trunc(sysdate)
                                    and trunc(sysdate) + nvl(wins.near_expiry_days, 30) then
               'NEAR EXPIRY'
           else
               'VALID'
       end as wc_ins_bucket_text,

       e.photo_blob,

       ------------------------------------------------------------------
       -- Legal Status
       ------------------------------------------------------------------
       nvl(lg.legal_status, 'NOT_SET') as current_legal_code,

       nvl(lg.legal_status_name, 'Not Set') as current_legal_name,

       ------------------------------------------------------------------
       -- Status Project / City from HR_EMP_STATUS_HIST
       ------------------------------------------------------------------
       cs.project_id as status_project_id,
       sap.project_name as status_project_name,

       cs.city_id as status_city_id,
       sac.city_name as status_city_name

  from hr_employees e

  left join ref_countries nc
    on nc.country_id = e.nationality_country_id

  left join hr_projects ap
    on ap.project_id = e.agreed_project_id

  left join ref_cities ac
    on ac.city_id = e.agreed_city_id

  left join ref_jobs j
    on j.job_id = e.job_id

  left join fin_suppliers fs
    on fs.supplier_id = e.supplier_id

  left join cur_asg ca
    on ca.emp_id = e.emp_id
   and ca.rn = 1

  left join hr_projects cp
    on cp.project_id = ca.project_id

  left join ref_cities cc
    on cc.city_id = ca.city_id

  left join last_asg la
    on la.emp_id = e.emp_id
   and la.rn = 1

  left join hr_projects lp
    on lp.project_id = la.project_id

  left join ref_cities lc
    on lc.city_id = la.city_id

  left join cur_status cs
    on cs.emp_id = e.emp_id
   and cs.rn = 1

  left join hr_status_master sm
    on sm.status_code = cs.status_code
   and sm.status_nature = 'EMPLOYEE'

  left join hr_projects sap
    on sap.project_id = cs.project_id

  left join ref_cities sac
    on sac.city_id = cs.city_id

  left join hr_emp_legal_profile_v lg
    on lg.emp_id = e.emp_id

  left join curr_pp_status cus_pp
    on cus_pp.emp_id = e.emp_id

  left join curr_pay_method pm
    on pm.emp_id = e.emp_id

  left join curr_health_ins hins
    on hins.emp_id = e.emp_id
   and hins.rn = 1

  left join curr_wc_ins wins
    on wins.emp_id = e.emp_id
   and wins.rn = 1

  left join sec_users su
    on su.user_id = e.deal_by_user;

CREATE OR REPLACE FORCE EDITIONABLE VIEW "VW_SEC_APEX_USERS" ("USER_ID", "USER_NAME") AS 
  select u.user_id,
       upper(u.username) as user_name
from sec_users u
where nvl(u.is_active,'Y') = 'Y';

CREATE OR REPLACE FORCE EDITIONABLE VIEW "VW_SEC_ROLE_USERS" ("ROLE_CODE", "USER_NAME") AS 
  select r.role_code,
       upper(u.username) as user_name
from sec_user_roles ur
join sec_users u
  on u.user_id = ur.user_id
join sec_roles r
  on r.role_id = ur.role_id
where nvl(u.is_active,'Y') = 'Y'
  and nvl(r.is_active,'Y') = 'Y';


-- ---------- PACKAGE SPECS (21) ----------

create or replace package fleet_pkg as

    procedure validate_bike_master (
        p_bike_id                in fleet_bikes.bike_id%type default null,
        p_plate_no               in fleet_bikes.plate_no%type default null,
        p_ownership_type         in fleet_bikes.ownership_type%type,
        p_vendor_id              in fleet_bikes.vendor_id%type default null,
        p_purchase_amount        in fleet_bikes.purchase_amount%type default null,
        p_current_monthly_rent   in fleet_bikes.current_monthly_rent%type default null,
        p_contract_start_dt      in fleet_bikes.contract_start_dt%type default null,
        p_contract_end_dt        in fleet_bikes.contract_end_dt%type default null,
         p_purchase_dt        in fleet_bikes.purchase_dt%type default null
    );

    function generate_bike_code (
        p_ownership_type         in fleet_bikes.ownership_type%type,
        p_vendor_id              in fleet_bikes.vendor_id%type default null
    ) return varchar2;

    function get_open_status_txn_id (
        p_bike_id in fleet_bikes.bike_id%type
    ) return number;

    function get_open_custody_txn_id (
        p_bike_id in fleet_bikes.bike_id%type
    ) return number;

    function get_active_bike_assign_id (
        p_bike_id in fleet_bikes.bike_id%type
    ) return number;

    function get_active_emp_bike_assign_id (
        p_emp_id in number
    ) return number;

    function get_current_bike_status (
        p_bike_id in fleet_bikes.bike_id%type
    ) return varchar2;

    function is_bike_assignable (
        p_bike_id in fleet_bikes.bike_id%type
    ) return varchar2;

    procedure change_bike_status (
        p_bike_id                in fleet_bikes.bike_id%type,
        p_new_status             in fleet_bike_status_txns.bike_status_code%type,
        p_effective_ts           in timestamp,
        p_reason_code            in fleet_bike_status_txns.reason_code%type default null,
        p_remarks                in fleet_bike_status_txns.remarks%type default null
    );

    procedure change_bike_custody (
        p_bike_id                in fleet_bikes.bike_id%type,
        p_new_custody            in fleet_bike_custody_txns.custody_type_code%type,
        p_location_id            in fleet_bike_custody_txns.location_id%type default null,
        p_effective_ts           in timestamp,
        p_reason_code            in fleet_bike_custody_txns.reason_code%type default null,
        p_remarks                in fleet_bike_custody_txns.remarks%type default null
    );

    procedure create_bike (
        p_plate_no               in fleet_bikes.plate_no%type default null,
        p_plate_emirate          in fleet_bikes.plate_emirate%type default null,
        p_chassis_no             in fleet_bikes.chassis_no%type default null,
        p_engine_no              in fleet_bikes.engine_no%type default null,
        p_model_id               in fleet_bikes.model_id%type default null,
        p_model_year             in fleet_bikes.model_year%type default null,
        p_color_id               in fleet_bikes.color_id%type default null,
        p_ownership_type         in fleet_bikes.ownership_type%type,
        p_vendor_id              in fleet_bikes.vendor_id%type default null,
        p_purchase_dt            in fleet_bikes.purchase_dt%type default null,
        p_purchase_amount        in fleet_bikes.purchase_amount%type default null,
        p_current_monthly_rent   in fleet_bikes.current_monthly_rent%type default null,
        p_contract_start_dt      in fleet_bikes.contract_start_dt%type default null,
        p_contract_end_dt        in fleet_bikes.contract_end_dt%type default null,
        p_remarks                in fleet_bikes.remarks%type default null,
        p_initial_status         in fleet_bike_status_txns.bike_status_code%type default 'AVAILABLE',
        p_initial_custody        in fleet_bike_custody_txns.custody_type_code%type default 'UNKNOWN',
        p_initial_location_id    in fleet_bike_custody_txns.location_id%type default null,
        p_effective_ts           in timestamp default systimestamp,
        p_bike_id                out fleet_bikes.bike_id%type,
        p_bike_code              out fleet_bikes.bike_code%type
    );

    procedure assign_bike (
        p_bike_id                in fleet_bikes.bike_id%type,
        p_emp_id                 in number,
        p_assign_ts              in timestamp,
        p_expected_return_ts     in timestamp default null,
        p_issue_condition        in fleet_bike_assignments.issue_condition%type default null,
        p_remarks                in fleet_bike_assignments.remarks%type default null,
        p_location_id            in fleet_bike_custody_txns.location_id%type default null,
        p_request_id             in fleet_bike_assignments.REF_REQUEST_ID%type default null
    );

    procedure return_bike (
        p_bike_assign_id         in fleet_bike_assignments.bike_assign_id%type,
        p_return_ts              in timestamp,
        p_return_condition       in fleet_bike_assignments.return_condition%type default null,
        p_next_status            in fleet_bike_status_txns.bike_status_code%type,
        p_next_custody           in fleet_bike_custody_txns.custody_type_code%type,
        p_next_location_id       in fleet_bike_custody_txns.location_id%type default null,
        p_remarks                in varchar2 default null
    );

    function get_open_impound_id (
    p_bike_id in fleet_bikes.bike_id%type
) return number;

procedure open_bike_impound (
    p_bike_id                  in fleet_bike_impounds.bike_id%type,
    p_emp_id                   in fleet_bike_impounds.emp_id%type default null,
    p_impound_start_ts         in fleet_bike_impounds.impound_start_ts%type,
    p_expected_release_ts      in fleet_bike_impounds.expected_release_ts%type default null,
    p_impound_custody_code     in fleet_bike_impounds.impound_custody_code%type,
    p_impound_location_id      in fleet_bike_impounds.impound_location_id%type default null,
    p_impound_location_text    in fleet_bike_impounds.impound_location_text%type default null,
