create or replace package body fleet_pkg as

    procedure raise_err(p_msg in varchar2) is
    begin
        raise_application_error(-20001, p_msg);
    end;

    procedure validate_bike_master (
        p_bike_id                in fleet_bikes.bike_id%type default null,
        p_plate_no               in fleet_bikes.plate_no%type default null,
        p_ownership_type         in fleet_bikes.ownership_type%type,
        p_vendor_id              in fleet_bikes.vendor_id%type default null,
        p_purchase_amount        in fleet_bikes.purchase_amount%type default null,
        p_current_monthly_rent   in fleet_bikes.current_monthly_rent%type default null,
        p_contract_start_dt      in fleet_bikes.contract_start_dt%type default null,
        p_contract_end_dt        in fleet_bikes.contract_end_dt%type default null,
         p_purchase_dt        in fleet_bikes.purchase_dt%type default null
    ) is
        l_cnt number;
    begin
        if p_ownership_type not in ('COMPANY','RENTAL') then
            raise_err('Ownership Type must be COMPANY or RENTAL.');
        end if;

        if p_ownership_type = 'COMPANY' then
            if nvl(p_purchase_amount,0) < 1 then
                raise_err('Purchase Amount cannot be negative.');
            end if;

             if p_purchase_dt is null then
                raise_err('Purchase date is required for OWN bikes');
            end if;
        end if;

        if p_ownership_type = 'RENTAL' then
            if p_vendor_id is null then
                raise_err('Vendor is required for rental bikes.');
            end if;

            if nvl(p_current_monthly_rent,0) < 1 then
                raise_err('Current Monthly Rent must be greater than zero for rental bikes.');
            end if;
if p_contract_start_dt is  null or 
            p_contract_end_dt is  null then
            raise_err('Contract start and end date is required for rental bikes.');
        end if;


        if p_contract_start_dt is not null
           and p_contract_end_dt is not null
           and p_contract_end_dt < p_contract_start_dt then
            raise_err('Contract End Date cannot be earlier than Contract Start Date.');
        end if;

        end if;

          

        if p_plate_no is not null then
            select count(*)
              into l_cnt
              from fleet_bikes
             where upper(plate_no) = upper(p_plate_no)
               and nvl(bike_id,-1) <> nvl(p_bike_id,-1);

            if l_cnt > 0 then
                raise_err('Plate No already exists.');
            end if;
        end if;
    end validate_bike_master;


    function generate_bike_code (
        p_ownership_type         in fleet_bikes.ownership_type%type,
        p_vendor_id              in fleet_bikes.vendor_id%type default null
    ) return varchar2 is
        l_prefix      varchar2(30);
        l_next_num    number;
        l_code        varchar2(30);
    begin
        if p_ownership_type = 'RENTAL' then
            if p_vendor_id is null then
                raise_err('Vendor is required to generate bike code for rental bike.');
            end if;

            select nvl(short_name,'UNK')
              into l_prefix
              from fin_suppliers
             where supplier_id = p_vendor_id;
        else
            l_prefix := 'OWN';
        end if;

        select nvl(max(to_number(regexp_substr(bike_code, '[0-9]+$'))),0) + 1
          into l_next_num
          from fleet_bikes
         where upper(bike_code) like upper(l_prefix) || '-%';

        l_code := upper(l_prefix) || '-' || lpad(l_next_num, 5, '0');
        return l_code;

    exception
        when no_data_found then
            raise_err('Vendor short name not found in FIN_SUPPLIERS.');
    end generate_bike_code;


    function get_open_status_txn_id (
        p_bike_id in fleet_bikes.bike_id%type
    ) return number is
        l_id number;
    begin
        select max(status_txn_id)
          into l_id
          from fleet_bike_status_txns
         where bike_id = p_bike_id
           and to_dt is null;
        return l_id;
    exception
        when no_data_found then
            return null;
    end get_open_status_txn_id;


    function get_open_custody_txn_id (
        p_bike_id in fleet_bikes.bike_id%type
    ) return number is
        l_id number;
    begin
        select max(custody_txn_id)
          into l_id
          from fleet_bike_custody_txns
         where bike_id = p_bike_id
           and to_dt is null;
        return l_id;
    exception
        when no_data_found then
            return null;
    end get_open_custody_txn_id;


    function get_active_bike_assign_id (
        p_bike_id in fleet_bikes.bike_id%type
    ) return number is
        l_id number;
    begin
        select max(bike_assign_id)
          into l_id
          from fleet_bike_assignments
         where bike_id = p_bike_id
           and status_code = 'ACTIVE'
           and return_dt is null;
        return l_id;
    exception
        when no_data_found then
            return null;
    end get_active_bike_assign_id;


    function get_active_emp_bike_assign_id (
        p_emp_id in number
    ) return number is
        l_id number;
    begin
        select max(bike_assign_id)
          into l_id
          from fleet_bike_assignments
         where emp_id = p_emp_id
           and status_code = 'ACTIVE'
           and return_dt is null;
        return l_id;
    exception
        when no_data_found then
            return null;
    end get_active_emp_bike_assign_id;


    function get_current_bike_status (
        p_bike_id in fleet_bikes.bike_id%type
    ) return varchar2 is
        l_status fleet_bike_status_txns.bike_status_code%type;
    begin
        select bike_status_code
          into l_status
          from fleet_bike_status_txns
         where bike_id = p_bike_id
           and to_dt is null;
        return l_status;
    exception
        when no_data_found then
            return null;
    end get_current_bike_status;


    function is_bike_assignable (
        p_bike_id in fleet_bikes.bike_id%type
    ) return varchar2 is
        l_status        varchar2(30);
        l_assign_id     number;
        l_assignable_yn varchar2(1);
    begin
        l_status := get_current_bike_status(p_bike_id);
        l_assign_id := get_active_bike_assign_id(p_bike_id);

        if l_status is null then
            return 'N';
        end if;

        begin
            select is_assignable_yn
              into l_assignable_yn
              from fleet_ref_bike_statuses
             where status_code = l_status
               and is_active = 'Y';
        exception
            when no_data_found then
                return 'N';
        end;

        if l_assignable_yn <> 'Y' then
            return 'N';
        end if;

        if l_assign_id is not null then
            return 'N';
        end if;

        return 'Y';
    end is_bike_assignable;


    procedure change_bike_status (
        p_bike_id                in fleet_bikes.bike_id%type,
        p_new_status             in fleet_bike_status_txns.bike_status_code%type,
        p_effective_ts           in timestamp,
        p_reason_code            in fleet_bike_status_txns.reason_code%type default null,
        p_remarks                in fleet_bike_status_txns.remarks%type default null
    ) is
        l_open_id       number;
        l_prev_from_ts  timestamp;
        l_exists        number;
    begin
        if p_bike_id is null then
            raise_err('Bike is required.');
        end if;

        if p_effective_ts is null then
            raise_err('Effective timestamp is required.');
        end if;

        select count(*)
          into l_exists
          from fleet_ref_bike_statuses
         where status_code = p_new_status
           and is_active = 'Y';

        if l_exists = 0 then
            raise_err('Invalid or inactive bike status.');
        end if;

        l_open_id := get_open_status_txn_id(p_bike_id);

        if l_open_id is not null then
            select from_dt
              into l_prev_from_ts
              from fleet_bike_status_txns
             where status_txn_id = l_open_id;

            if p_effective_ts < l_prev_from_ts then
                raise_err('New status timestamp cannot be earlier than current open status start timestamp.');
            end if;

            update fleet_bike_status_txns
               set to_dt = p_effective_ts
             where status_txn_id = l_open_id;
        end if;

        insert into fleet_bike_status_txns (
            bike_id, bike_status_code, from_dt, to_dt, reason_code, remarks
        ) values (
            p_bike_id, p_new_status, p_effective_ts, null, p_reason_code, p_remarks
        );
    end change_bike_status;


    procedure change_bike_custody (
        p_bike_id                in fleet_bikes.bike_id%type,
        p_new_custody            in fleet_bike_custody_txns.custody_type_code%type,
        p_location_id            in fleet_bike_custody_txns.location_id%type default null,
        p_effective_ts           in timestamp,
        p_reason_code            in fleet_bike_custody_txns.reason_code%type default null,
        p_remarks                in fleet_bike_custody_txns.remarks%type default null
    ) is
        l_open_id       number;
        l_prev_from_ts  timestamp;
        l_exists        number;
        l_loc_exists    number;
    begin
        if p_bike_id is null then
            raise_err('Bike is required.');
        end if;

        if p_effective_ts is null then
            raise_err('Effective timestamp is required.');
        end if;

        select count(*)
          into l_exists
          from fleet_ref_custody_types
         where custody_type_code = p_new_custody
           and is_active = 'Y';

        if l_exists = 0 then
            raise_err('Invalid or inactive custody type.');
        end if;

        if p_location_id is not null then
            select count(*)
              into l_loc_exists
              from fleet_ref_custody_locations
             where location_id = p_location_id
               and custody_type_code = p_new_custody
               and is_active = 'Y';

            if l_loc_exists = 0 then
                raise_err('Selected custody location does not belong to selected custody type or is inactive.');
            end if;
        end if;

        l_open_id := get_open_custody_txn_id(p_bike_id);

        if l_open_id is not null then
            select from_dt
              into l_prev_from_ts
              from fleet_bike_custody_txns
             where custody_txn_id = l_open_id;

            if p_effective_ts < l_prev_from_ts then
                raise_err('New custody timestamp cannot be earlier than current open custody start timestamp.');
            end if;

            update fleet_bike_custody_txns
               set to_dt = p_effective_ts
             where custody_txn_id = l_open_id;
        end if;

        insert into fleet_bike_custody_txns (
            bike_id, custody_type_code, location_id, from_dt, to_dt, reason_code, remarks
        ) values (
            p_bike_id, p_new_custody, p_location_id, p_effective_ts, null, p_reason_code, p_remarks
        );
    end change_bike_custody;


    procedure create_bike (
        p_plate_no               in fleet_bikes.plate_no%type default null,
        p_plate_emirate          in fleet_bikes.plate_emirate%type default null,
        p_chassis_no             in fleet_bikes.chassis_no%type default null,
        p_engine_no              in fleet_bikes.engine_no%type default null,
        p_model_id               in fleet_bikes.model_id%type default null,
        p_model_year             in fleet_bikes.model_year%type default null,
        p_color_id               in fleet_bikes.color_id%type default null,
        p_ownership_type         in fleet_bikes.ownership_type%type,
        p_vendor_id              in fleet_bikes.vendor_id%type default null,
        p_purchase_dt            in fleet_bikes.purchase_dt%type default null,
        p_purchase_amount        in fleet_bikes.purchase_amount%type default null,
        p_current_monthly_rent   in fleet_bikes.current_monthly_rent%type default null,
        p_contract_start_dt      in fleet_bikes.contract_start_dt%type default null,
        p_contract_end_dt        in fleet_bikes.contract_end_dt%type default null,
        p_remarks                in fleet_bikes.remarks%type default null,
        p_initial_status         in fleet_bike_status_txns.bike_status_code%type default 'AVAILABLE',
        p_initial_custody        in fleet_bike_custody_txns.custody_type_code%type default 'UNKNOWN',
        p_initial_location_id    in fleet_bike_custody_txns.location_id%type default null,
        p_effective_ts           in timestamp default systimestamp,
        p_bike_id                out fleet_bikes.bike_id%type,
        p_bike_code              out fleet_bikes.bike_code%type
    ) is
    begin
        validate_bike_master(
            p_bike_id              => null,
            p_plate_no             => p_plate_no,
            p_ownership_type       => p_ownership_type,
            p_vendor_id            => p_vendor_id,
            p_purchase_amount      => p_purchase_amount,
            p_current_monthly_rent => p_current_monthly_rent,
            p_contract_start_dt    => p_contract_start_dt,
            p_contract_end_dt      => p_contract_end_dt,
            p_purchase_dt => p_purchase_dt
        );

        p_bike_code := generate_bike_code(
            p_ownership_type => p_ownership_type,
            p_vendor_id      => p_vendor_id
        );

        insert into fleet_bikes (
            bike_code,
            plate_no,
            plate_emirate,
            chassis_no,
            engine_no,
            model_id,
            model_year,
            color_id,
            ownership_type,
            vendor_id,
            purchase_dt,
            purchase_amount,
            current_monthly_rent,
            contract_start_dt,
            contract_end_dt,
            remarks,
            is_active
        ) values (
            p_bike_code,
            p_plate_no,
            p_plate_emirate,
            p_chassis_no,
            p_engine_no,
            p_model_id,
            p_model_year,
            p_color_id,
            p_ownership_type,
            p_vendor_id,
            p_purchase_dt,
            p_purchase_amount,
            p_current_monthly_rent,
            p_contract_start_dt,
            p_contract_end_dt,
            p_remarks,
            'Y'
        )
        returning bike_id into p_bike_id;

        change_bike_status(
            p_bike_id      => p_bike_id,
            p_new_status   => p_initial_status,
            p_effective_ts => p_effective_ts,
            p_reason_code  => 'CREATE',
            p_remarks      => 'Initial bike creation'
        );

        change_bike_custody(
            p_bike_id      => p_bike_id,
            p_new_custody  => p_initial_custody,
            p_location_id  => p_initial_location_id,
            p_effective_ts => p_effective_ts,
            p_reason_code  => 'CREATE',
            p_remarks      => 'Initial bike creation'
        );
    end create_bike;


    procedure assign_bike (
        p_bike_id                in fleet_bikes.bike_id%type,
        p_emp_id                 in number,
        p_assign_ts              in timestamp,
        p_expected_return_ts     in timestamp default null,
        p_issue_condition        in fleet_bike_assignments.issue_condition%type default null,
        p_remarks                in fleet_bike_assignments.remarks%type default null,
        p_location_id            in fleet_bike_custody_txns.location_id%type default null,
        p_request_id             in fleet_bike_assignments.REF_REQUEST_ID%type default null
    ) is
        l_assignable varchar2(1);
        l_existing_id number;
    begin
        if p_bike_id is null then
            raise_err('Bike is required.');
        end if;

        if p_emp_id is null then
            raise_err('Employee is required.');
        end if;

        if p_assign_ts is null then
            raise_err('Assign timestamp is required.');
        end if;

        if p_expected_return_ts is not null and p_expected_return_ts < p_assign_ts then
            raise_err('Expected return timestamp cannot be earlier than assign timestamp.');
        end if;

        l_assignable := is_bike_assignable(p_bike_id);
        if l_assignable <> 'Y' then
            raise_err('Bike is not assignable.');
        end if;

        l_existing_id := get_active_emp_bike_assign_id(p_emp_id);
        if l_existing_id is not null then
            raise_err('Employee already has an active bike assignment.');
        end if;

        insert into fleet_bike_assignments (
            bike_id,
            emp_id,
            assign_dt,
            expected_return_dt,
            issue_condition,
            remarks,
            status_code,
            ref_request_id
        ) values (
            p_bike_id,
            p_emp_id,
            p_assign_ts,
            p_expected_return_ts,
            p_issue_condition,
            p_remarks,
            'ACTIVE',
            p_request_id
        );

        change_bike_status(
            p_bike_id      => p_bike_id,
            p_new_status   => 'ASSIGNED',
            p_effective_ts => p_assign_ts,
            p_reason_code  => 'ASSIGNMENT',
            p_remarks      => p_remarks
        );

        change_bike_custody(
            p_bike_id      => p_bike_id,
            p_new_custody  => 'EMPLOYEE',
            p_location_id  => p_location_id,
            p_effective_ts => p_assign_ts,
            p_reason_code  => 'ASSIGNMENT',
            p_remarks      => p_remarks
        );


    end assign_bike;


    procedure return_bike (
        p_bike_assign_id         in fleet_bike_assignments.bike_assign_id%type,
        p_return_ts              in timestamp,
        p_return_condition       in fleet_bike_assignments.return_condition%type default null,
        p_next_status            in fleet_bike_status_txns.bike_status_code%type,
        p_next_custody           in fleet_bike_custody_txns.custody_type_code%type,
        p_next_location_id       in fleet_bike_custody_txns.location_id%type default null,
        p_remarks                in varchar2 default null
    ) is
        l_bike_id    fleet_bike_assignments.bike_id%type;
        l_assign_ts  fleet_bike_assignments.assign_dt%type;
        l_status     fleet_bike_assignments.status_code%type;
    begin
        if p_bike_assign_id is null then
            raise_err('Bike Assignment is required.');
        end if;

        if p_return_ts is null then
            raise_err('Return timestamp is required.');
        end if;

        select bike_id, assign_dt, status_code
          into l_bike_id, l_assign_ts, l_status
          from fleet_bike_assignments
         where bike_assign_id = p_bike_assign_id;

        if l_status <> 'ACTIVE' then
            raise_err('Only active assignments can be returned.');
        end if;

        if p_return_ts < l_assign_ts then
            raise_err('Return timestamp cannot be earlier than assign timestamp.');
        end if;

        update fleet_bike_assignments
           set return_dt        = p_return_ts,
               return_condition = p_return_condition,
               remarks          = case
                                    when remarks is null then p_remarks
                                    when p_remarks is null then remarks
                                    else remarks || ' | ' || p_remarks
                                  end,
               status_code      = 'RETURNED'
         where bike_assign_id = p_bike_assign_id;

        change_bike_status(
            p_bike_id      => l_bike_id,
            p_new_status   => p_next_status,
            p_effective_ts => p_return_ts,
            p_reason_code  => 'RETURN',
            p_remarks      => p_remarks
        );

        change_bike_custody(
            p_bike_id      => l_bike_id,
            p_new_custody  => p_next_custody,
            p_location_id  => p_next_location_id,
            p_effective_ts => p_return_ts,
            p_reason_code  => 'RETURN',
            p_remarks      => p_remarks
        );
    end return_bike;


   function get_open_impound_id (
    p_bike_id in fleet_bikes.bike_id%type
) return number is
    l_impound_id number;
begin
    select max(impound_id)
      into l_impound_id
      from fleet_bike_impounds
     where bike_id = p_bike_id
       and status_code = 'ACTIVE'
       and release_ts is null;

    return l_impound_id;
end get_open_impound_id;

procedure open_bike_impound (
    p_bike_id                  in fleet_bike_impounds.bike_id%type,
    p_emp_id                   in fleet_bike_impounds.emp_id%type default null,
    p_impound_start_ts         in fleet_bike_impounds.impound_start_ts%type,
    p_expected_release_ts      in fleet_bike_impounds.expected_release_ts%type default null,
    p_impound_custody_code     in fleet_bike_impounds.impound_custody_code%type,
    p_impound_location_id      in fleet_bike_impounds.impound_location_id%type default null,
    p_impound_location_text    in fleet_bike_impounds.impound_location_text%type default null,
    p_impound_reason           in fleet_bike_impounds.impound_reason%type default null,
    p_impound_cost             in fleet_bike_impounds.impound_cost%type default null,
    p_charge_to_employee_yn    in fleet_bike_impounds.charge_to_employee_yn%type default 'N',
    p_excluded_from_charge_yn  in fleet_bike_impounds.excluded_from_charge_yn%type default 'N',
    p_create_charge_yn         in varchar2 default 'N',
    p_charge_due_dt            in date default null,
    p_remarks                  in fleet_bike_impounds.remarks%type default null,
    p_impound_id               out fleet_bike_impounds.impound_id%type
) is
    l_open_impound_id number;
    l_loc_cnt         number;
    l_emp_charge_id   number;
begin
    if p_bike_id is null then
        raise_err('Bike is required.');
    end if;

    if p_impound_start_ts is null then
        raise_err('Impound start date is required.');
    end if;

    if p_expected_release_ts is not null
       and p_expected_release_ts < p_impound_start_ts then
        raise_err('Expected release date cannot be earlier than impound start date.');
    end if;

    if p_impound_custody_code is null then
        raise_err('Impound custody is required.');
    end if;

    l_open_impound_id := get_open_impound_id(p_bike_id);

    if l_open_impound_id is not null then
        raise_err('An active impound case already exists for this bike.');
    end if;

    if p_impound_location_id is not null then
        select count(*)
          into l_loc_cnt
          from fleet_ref_custody_locations
         where location_id = p_impound_location_id
           and custody_type_code = p_impound_custody_code
           and is_active = 'Y';

        if l_loc_cnt = 0 then
            raise_err('Selected location does not belong to selected custody type.');
        end if;
    end if;

    if p_create_charge_yn = 'Y' then
        if p_emp_id is null then
            raise_err('Employee is required to create charge.');
        end if;

        if nvl(p_impound_cost,0) <= 0 then
            raise_err('Impound cost must be greater than zero to create charge.');
        end if;

        hr_charges_pkg.create_charge(
            p_emp_id                  => p_emp_id,
            p_charge_type             => 'IMPOUND',
            p_recurrence_type         => 'ONE_TIME',
            p_charge_ts               => p_impound_start_ts,
            p_amount                  => p_impound_cost,
            p_source_start_dt         => null,
            p_source_end_dt           => null,
            p_source_table_name       => null,
            p_source_row_id           => null,
            p_bike_id                 => p_bike_id,
            p_charge_to_employee_yn   => p_charge_to_employee_yn,
            p_excluded_from_charge_yn => p_excluded_from_charge_yn,
            p_approval_status         => 'APPROVED',
            p_payroll_deduction_code  => 'IMPOUND',
            p_remarks                 => 'Impound charge. ' || p_remarks,
            p_emp_charge_id           => l_emp_charge_id
        );

        if p_charge_due_dt is not null then
            hr_charges_pkg.create_single_installment(
                p_emp_charge_id => l_emp_charge_id,
                p_due_dt        => p_charge_due_dt,
                p_amount        => p_impound_cost,
                p_remarks       => 'Auto-created from impound case'
            );
        end if;
    end if;

    insert into fleet_bike_impounds (
        bike_id,
        emp_id,
        impound_start_ts,
        expected_release_ts,
        impound_custody_code,
        impound_location_id,
        impound_location_text,
        impound_reason,
        impound_cost,
        charge_to_employee_yn,
        excluded_from_charge_yn,
        emp_charge_id,
        status_code,
        remarks
    ) values (
        p_bike_id,
        p_emp_id,
        p_impound_start_ts,
        p_expected_release_ts,
        p_impound_custody_code,
        p_impound_location_id,
        p_impound_location_text,
        p_impound_reason,
        p_impound_cost,
        p_charge_to_employee_yn,
        p_excluded_from_charge_yn,
        l_emp_charge_id,
        'ACTIVE',
        p_remarks
    )
    returning impound_id into p_impound_id;

    if l_emp_charge_id is not null then
        update hr_emp_charges
           set source_table_name = 'FLEET_BIKE_IMPOUNDS',
               source_row_id     = p_impound_id
         where emp_charge_id = l_emp_charge_id;
    end if;

/* Close active assignment automatically due to impound */
update fleet_bike_assignments
   set return_dt          = p_impound_start_ts,
       return_condition   = 'Closed automatically due to impound case #' || p_impound_id,
       return_reason_code = 'IMPOUND_REPLACEMENT',
       status_code        = 'RETURNED',
       returned_by        = nvl(v('APP_USER'), user),
       remarks            = case
                               when remarks is null then 'Auto-closed due to impound. ' || p_remarks
                               else remarks || ' | Auto-closed due to impound. ' || p_remarks
                             end
 where bike_id = p_bike_id
   and status_code = 'ACTIVE'
   and return_dt is null;

    change_bike_status(
        p_bike_id      => p_bike_id,
        p_new_status   => 'IMPOUND',
        p_effective_ts => p_impound_start_ts,
        p_reason_code  => 'IMPOUND',
        p_remarks      => p_remarks
    );

    change_bike_custody(
        p_bike_id      => p_bike_id,
        p_new_custody  => p_impound_custody_code,
        p_location_id  => p_impound_location_id,
        p_effective_ts => p_impound_start_ts,
        p_reason_code  => 'IMPOUND',
        p_remarks      => p_remarks
    );
end open_bike_impound;

procedure release_bike_impound (
    p_impound_id         in fleet_bike_impounds.impound_id%type,
    p_release_ts         in fleet_bike_impounds.release_ts%type,
    p_next_status        in fleet_bike_status_txns.bike_status_code%type,
    p_next_custody       in fleet_bike_custody_txns.custody_type_code%type,
    p_next_location_id   in fleet_bike_custody_txns.location_id%type default null,
    p_remarks            in varchar2 default null
) is
    l_bike_id  fleet_bike_impounds.bike_id%type;
    l_start_ts fleet_bike_impounds.impound_start_ts%type;
    l_status   fleet_bike_impounds.status_code%type;
begin
    if p_impound_id is null then
        raise_err('Impound case is required.');
    end if;

    if p_release_ts is null then
        raise_err('Actual release date is required.');
    end if;

    if p_next_status is null then
        raise_err('Next status is required.');
    end if;

    if p_next_custody is null then
        raise_err('Next custody is required.');
    end if;

    select bike_id, impound_start_ts, status_code
      into l_bike_id, l_start_ts, l_status
      from fleet_bike_impounds
     where impound_id = p_impound_id;

    if l_status <> 'ACTIVE' then
        raise_err('Only active impound cases can be released.');
    end if;

    if p_release_ts < l_start_ts then
        raise_err('Actual release date cannot be earlier than impound start date.');
    end if;

    update fleet_bike_impounds
       set release_ts  = p_release_ts,
           status_code = 'RELEASED',
           remarks     = case
                            when remarks is null then p_remarks
                            when p_remarks is null then remarks
                            else remarks || ' | ' || p_remarks
                          end
     where impound_id = p_impound_id;

    change_bike_status(
        p_bike_id      => l_bike_id,
        p_new_status   => p_next_status,
        p_effective_ts => p_release_ts,
        p_reason_code  => 'IMPOUND_RELEASE',
        p_remarks      => p_remarks
    );

    change_bike_custody(
        p_bike_id      => l_bike_id,
        p_new_custody  => p_next_custody,
        p_location_id  => p_next_location_id,
        p_effective_ts => p_release_ts,
        p_reason_code  => 'IMPOUND_RELEASE',
        p_remarks      => p_remarks
    );
end release_bike_impound;


procedure open_bike_accident (
    p_bike_id                  in fleet_bike_accidents.bike_id%type,
    p_emp_id                   in fleet_bike_accidents.emp_id%type default null,
    p_accident_dt              in fleet_bike_accidents.accident_dt%type,
    p_accident_location        in fleet_bike_accidents.accident_location%type default null,
    p_police_report_no         in fleet_bike_accidents.police_report_no%type default null,
    p_fault_type               in fleet_bike_accidents.fault_type%type default null,
    p_accident_severity        in fleet_bike_accidents.accident_severity%type default null,
    p_accident_custody_code    in fleet_bike_custody_txns.custody_type_code%type,
    p_accident_location_id     in fleet_bike_custody_txns.location_id%type default null,
    p_estimated_cost           in fleet_bike_accidents.estimated_cost%type default null,
    p_charge_to_employee_yn    in fleet_bike_accidents.charge_to_employee_yn%type default 'N',
    p_excluded_from_charge_yn  in fleet_bike_accidents.excluded_from_charge_yn%type default 'N',
    p_create_charge_yn         in varchar2 default 'N',
    p_charge_due_dt            in date default null,
    p_remarks                  in fleet_bike_accidents.remarks%type default null,
    p_accident_id              out fleet_bike_accidents.accident_id%type
) is
    l_loc_cnt        number;
    l_emp_charge_id  number;
begin
    if p_bike_id is null then
        raise_err('Bike is required.');
    end if;

    if p_accident_dt is null then
        raise_err('Accident date is required.');
    end if;

    if p_accident_custody_code is null then
        raise_err('Accident custody is required.');
    end if;

    if p_fault_type is not null
       and p_fault_type not in ('EMPLOYEE','COMPANY','THIRD_PARTY') then
        raise_err('Invalid fault type.');
    end if;

    if p_accident_severity is not null
       and p_accident_severity not in ('MINOR','MAJOR','TOTAL_LOSS') then
        raise_err('Invalid accident severity.');
    end if;

    if p_charge_to_employee_yn not in ('Y','N') then
        raise_err('Charge to employee must be Y or N.');
    end if;

    if p_excluded_from_charge_yn not in ('Y','N') then
        raise_err('Excluded from charge must be Y or N.');
    end if;

    if p_create_charge_yn not in ('Y','N') then
        raise_err('Create charge must be Y or N.');
    end if;

    if p_accident_location_id is not null then
        select count(*)
          into l_loc_cnt
          from fleet_ref_custody_locations
         where location_id = p_accident_location_id
           and custody_type_code = p_accident_custody_code
           and is_active = 'Y';

        if l_loc_cnt = 0 then
            raise_err('Selected accident location does not belong to selected custody type or is inactive.');
        end if;
    end if;

    if p_create_charge_yn = 'Y' then
        if p_emp_id is null then
            raise_err('Employee is required when creating employee charge.');
        end if;

        if p_fault_type <> 'EMPLOYEE' then
            raise_err('Charge can be created only when fault type is EMPLOYEE.');
        end if;

        if nvl(p_estimated_cost,0) <= 0 then
            raise_err('Estimated cost must be greater than zero when creating charge.');
        end if;

        hr_charges_pkg.create_charge(
            p_emp_id                  => p_emp_id,
            p_charge_type             => 'ACCIDENT_RECOVERY',
            p_recurrence_type         => 'ONE_TIME',
            p_charge_ts               => cast(p_accident_dt as timestamp),
            p_amount                  => p_estimated_cost,
            p_source_start_dt         => null,
            p_source_end_dt           => null,
            p_source_table_name       => null,
            p_source_row_id           => null,
            p_bike_id                 => p_bike_id,
            p_charge_to_employee_yn   => p_charge_to_employee_yn,
            p_excluded_from_charge_yn => p_excluded_from_charge_yn,
            p_approval_status         => 'APPROVED',
            p_payroll_deduction_code  => 'ACCIDENT',
            p_remarks                 => 'Accident recovery. ' || p_remarks,
            p_emp_charge_id           => l_emp_charge_id
        );

        if p_charge_due_dt is not null then
            hr_charges_pkg.create_single_installment(
                p_emp_charge_id => l_emp_charge_id,
                p_due_dt        => p_charge_due_dt,
                p_amount        => p_estimated_cost,
                p_remarks       => 'Auto-created from accident case'
            );
        end if;
    end if;

    insert into fleet_bike_accidents (
        bike_id,
        emp_id,
        accident_dt,
        accident_location,
        police_report_no,
        fault_type,
        accident_severity,
        estimated_cost,
        charge_to_employee_yn,
        excluded_from_charge_yn,
        emp_charge_id,
        status_code,
        remarks
    ) values (
        p_bike_id,
        p_emp_id,
        p_accident_dt,
        p_accident_location,
        p_police_report_no,
        p_fault_type,
        p_accident_severity,
        p_estimated_cost,
        p_charge_to_employee_yn,
        p_excluded_from_charge_yn,
        l_emp_charge_id,
        'OPEN',
        p_remarks
    )
    returning accident_id into p_accident_id;

    if l_emp_charge_id is not null then
        update hr_emp_charges
           set source_table_name = 'FLEET_BIKE_ACCIDENTS',
               source_row_id     = p_accident_id
         where emp_charge_id = l_emp_charge_id;
    end if;

    update fleet_bike_assignments
       set return_dt          = cast(p_accident_dt as timestamp),
           return_condition   = 'Closed automatically due to accident case #' || p_accident_id,
           return_reason_code = 'ACCIDENT_REPLACEMENT',
           status_code        = 'RETURNED',
           returned_by        = nvl(v('APP_USER'), user),
           remarks            = case
                                   when remarks is null then 'Auto-closed due to accident. ' || p_remarks
                                   else remarks || ' | Auto-closed due to accident. ' || p_remarks
                                 end
     where bike_id = p_bike_id
       and status_code = 'ACTIVE'
       and return_dt is null;

    change_bike_status(
        p_bike_id      => p_bike_id,
        p_new_status   => 'ACCIDENT',
        p_effective_ts => cast(p_accident_dt as timestamp),
        p_reason_code  => 'ACCIDENT',
        p_remarks      => p_remarks
    );

    change_bike_custody(
        p_bike_id      => p_bike_id,
        p_new_custody  => p_accident_custody_code,
        p_location_id  => p_accident_location_id,
        p_effective_ts => cast(p_accident_dt as timestamp),
        p_reason_code  => 'ACCIDENT',
        p_remarks      => p_remarks
    );
end open_bike_accident;


procedure start_bike_repair (
    p_accident_id        in fleet_bike_accidents.accident_id%type,
    p_repair_start_dt    in fleet_bike_accidents.repair_start_dt%type,
    p_repair_custody     in fleet_bike_custody_txns.custody_type_code%type,
    p_repair_location_id in fleet_bike_custody_txns.location_id%type default null,
    p_remarks            in varchar2 default null
) is
    l_bike_id     fleet_bike_accidents.bike_id%type;
    l_accident_dt fleet_bike_accidents.accident_dt%type;
    l_status      fleet_bike_accidents.status_code%type;
begin
    if p_accident_id is null then
        raise_err('Accident case is required.');
    end if;

    if p_repair_start_dt is null then
        raise_err('Repair start date is required.');
    end if;

    if p_repair_custody is null then
        raise_err('Repair custody is required.');
    end if;

    select bike_id, accident_dt, status_code
      into l_bike_id, l_accident_dt, l_status
      from fleet_bike_accidents
     where accident_id = p_accident_id;

    if l_status <> 'OPEN' then
        raise_err('Only OPEN accident cases can be moved to repair.');
    end if;

    if p_repair_start_dt < l_accident_dt then
        raise_err('Repair start date cannot be earlier than accident date.');
    end if;

    update fleet_bike_accidents
       set repair_start_dt = p_repair_start_dt,
           status_code     = 'UNDER_REPAIR',
           remarks         = case
                               when remarks is null then p_remarks
                               when p_remarks is null then remarks
                               else remarks || ' | ' || p_remarks
                             end
     where accident_id = p_accident_id;

    change_bike_status(
        p_bike_id      => l_bike_id,
        p_new_status   => 'MAINTENANCE',
        p_effective_ts => cast(p_repair_start_dt as timestamp),
        p_reason_code  => 'REPAIR_START',
        p_remarks      => p_remarks
    );

    change_bike_custody(
        p_bike_id      => l_bike_id,
        p_new_custody  => p_repair_custody,
        p_location_id  => p_repair_location_id,
        p_effective_ts => cast(p_repair_start_dt as timestamp),
        p_reason_code  => 'REPAIR_START',
        p_remarks      => p_remarks
    );
end start_bike_repair;


procedure close_bike_accident (
    p_accident_id        in fleet_bike_accidents.accident_id%type,
    p_repair_end_dt      in fleet_bike_accidents.repair_end_dt%type,
    p_actual_cost        in fleet_bike_accidents.actual_cost%type default null,
    p_next_status        in fleet_bike_status_txns.bike_status_code%type,
    p_next_custody       in fleet_bike_custody_txns.custody_type_code%type,
    p_next_location_id   in fleet_bike_custody_txns.location_id%type default null,
    p_remarks            in varchar2 default null
) is
    l_bike_id         fleet_bike_accidents.bike_id%type;
    l_repair_start_dt fleet_bike_accidents.repair_start_dt%type;
    l_accident_dt     fleet_bike_accidents.accident_dt%type;
    l_status          fleet_bike_accidents.status_code%type;
begin
    if p_accident_id is null then
        raise_err('Accident case is required.');
    end if;

    if p_repair_end_dt is null then
        raise_err('Repair end date is required.');
    end if;

    if p_next_status is null then
        raise_err('Next status is required.');
    end if;

    if p_next_custody is null then
        raise_err('Next custody is required.');
    end if;

    if nvl(p_actual_cost,0) < 0 then
        raise_err('Actual cost cannot be negative.');
    end if;

    select bike_id, accident_dt, repair_start_dt, status_code
      into l_bike_id, l_accident_dt, l_repair_start_dt, l_status
      from fleet_bike_accidents
     where accident_id = p_accident_id;

    if l_status not in ('OPEN','UNDER_REPAIR') then
        raise_err('Only OPEN or UNDER_REPAIR accident cases can be closed.');
    end if;

    if p_repair_end_dt < l_accident_dt then
        raise_err('Repair end date cannot be earlier than accident date.');
    end if;

    if l_repair_start_dt is not null
       and p_repair_end_dt < l_repair_start_dt then
        raise_err('Repair end date cannot be earlier than repair start date.');
    end if;

    update fleet_bike_accidents
       set repair_end_dt = p_repair_end_dt,
           actual_cost   = p_actual_cost,
           status_code   = 'CLOSED',
           remarks       = case
                             when remarks is null then p_remarks
                             when p_remarks is null then remarks
                             else remarks || ' | ' || p_remarks
                           end
     where accident_id = p_accident_id;

    change_bike_status(
        p_bike_id      => l_bike_id,
        p_new_status   => p_next_status,
        p_effective_ts => cast(p_repair_end_dt as timestamp),
        p_reason_code  => 'ACCIDENT_CLOSE',
        p_remarks      => p_remarks
    );

    change_bike_custody(
        p_bike_id      => l_bike_id,
        p_new_custody  => p_next_custody,
        p_location_id  => p_next_location_id,
        p_effective_ts => cast(p_repair_end_dt as timestamp),
        p_reason_code  => 'ACCIDENT_CLOSE',
        p_remarks      => p_remarks
    );
end close_bike_accident;

end fleet_pkg;
/

create or replace package body hr_approval_ui_pkg as

    ----------------------------------------------------------------------
    -- Common helpers only
    ----------------------------------------------------------------------

    function esc (
        p_text in varchar2
    ) return varchar2
    is
    begin
        return apex_escape.html(nvl(p_text, '-'));
    end esc;


    function amount_text (
        p_amount in number
    ) return varchar2
    is
    begin
        return 'AED ' || trim(to_char(nvl(p_amount,0), '999G999G999G990D00'));
    end amount_text;


    function field_html (
        p_label in varchar2,
        p_value in varchar2,
        p_class in varchar2 default null
    ) return clob
    is
    begin
        return
            '<div class="appr-field ' || apex_escape.html_attribute(p_class) || '">' ||
            '  <div class="appr-label">' || esc(p_label) || '</div>' ||
            '  <div class="appr-value">' || esc(p_value) || '</div>' ||
            '</div>';
    end field_html;


    function status_email_badge (
        p_status in varchar2
    ) return varchar2
    is
    begin
        if p_status = 'APPROVED' then
            return '<span style="background:#dcfce7;color:#166534;padding:3px 8px;border-radius:999px;font-size:11px;font-weight:bold;">Approved</span>';

        elsif p_status = 'REJECTED' then
            return '<span style="background:#fee2e2;color:#991b1b;padding:3px 8px;border-radius:999px;font-size:11px;font-weight:bold;">Rejected</span>';

        elsif p_status = 'TASK_CREATED' then
            return '<span style="background:#fef3c7;color:#92400e;padding:3px 8px;border-radius:999px;font-size:11px;font-weight:bold;">Current / Pending</span>';

        elsif p_status = 'PENDING' then
            return '<span style="background:#dbeafe;color:#1d4ed8;padding:3px 8px;border-radius:999px;font-size:11px;font-weight:bold;">Waiting</span>';

        elsif p_status = 'CANCELLED' then
            return '<span style="background:#f1f5f9;color:#475569;padding:3px 8px;border-radius:999px;font-size:11px;font-weight:bold;">Cancelled</span>';

        else
            return '<span style="background:#f1f5f9;color:#475569;padding:3px 8px;border-radius:999px;font-size:11px;font-weight:bold;">' ||
                   apex_escape.html(nvl(p_status, '-')) ||
                   '</span>';
        end if;
    end status_email_badge;


    ----------------------------------------------------------------------
    -- Generic fallback summary
    ----------------------------------------------------------------------

    function render_generic_summary (
        p_approval_id in number
    ) return clob
    is
        l_html clob;
    begin
        for r in (
            select approval_subject,
                   module_code,
                   record_pk,
                   approval_amount,
                   request_status,
                   requested_by,
                   requested_dt
              from hr_approval_requests
             where approval_id = p_approval_id
        )
        loop
            l_html :=
                '<div class="appr-card">' ||
                '  <div class="appr-card-header">' ||
                '    <div>' ||
                '      <div class="appr-card-title">' || esc(r.approval_subject) || '</div>' ||
                '      <div class="appr-card-subtitle">' || esc(r.module_code) || '</div>' ||
                '    </div>' ||
                '    <div class="appr-status">' || esc(r.request_status) || '</div>' ||
                '  </div>' ||

                '  <div class="appr-grid">' ||
                     field_html('Module', r.module_code) ||
                     field_html('Record ID', to_char(r.record_pk)) ||
                     field_html('Amount', amount_text(r.approval_amount), 'amount') ||
                     field_html('Requested By', r.requested_by) ||
                     field_html('Requested Date', to_char(r.requested_dt, 'DD-MON-YYYY HH24:MI')) ||
                '  </div>' ||
                '</div>';
        end loop;

        if l_html is null then
            l_html :=
                '<div class="t-Alert t-Alert--warning">' ||
                'Approval request details not found.' ||
                '</div>';
        end if;

        return l_html;
    end render_generic_summary;


    ----------------------------------------------------------------------
    -- Dispatcher: full detail URL
    ----------------------------------------------------------------------

    function get_full_detail_url (
        p_module_code in varchar2,
        p_record_pk   in number
    ) return varchar2
    is
    begin
        if p_module_code = 'PRO_DEAL' then

            return hr_pro_deal_app_pkg.get_full_detail_url(p_record_pk);

        /*
        Later, after HR_LOAN_APP_PKG is created:

        elsif p_module_code = 'LOAN_TXN' then
            return hr_loan_app_pkg.get_full_detail_url(p_record_pk);
        */

        
        elsif p_module_code = 'LOAN_TXN' then
    return hr_loan_app_pkg.get_full_detail_url(p_record_pk);
            elsif p_module_code = 'LOAN_MASTER' then

    return apex_page.get_url(
        p_page        => 171,
        p_items       => 'P171_LOAN_ID',
        p_values      => p_record_pk,
        p_clear_cache => '171'
    );
           else
            return null;
        end if;
    end get_full_detail_url;


    ----------------------------------------------------------------------
    -- Dispatcher: P25 transaction summary
    ----------------------------------------------------------------------

    function render_summary (
        p_module_code in varchar2,
        p_record_pk   in number,
        p_approval_id in number
    ) return clob
    is
    begin
        if p_module_code = 'PRO_DEAL' then

            return hr_pro_deal_app_pkg.render_summary(
                p_record_pk   => p_record_pk,
                p_approval_id => p_approval_id
            );

        /*
        Later:

        elsif p_module_code = 'LOAN_TXN' then
            return hr_loan_app_pkg.render_summary(
                p_record_pk   => p_record_pk,
                p_approval_id => p_approval_id
            );
        */
        elsif p_module_code = 'LOAN_TXN' then
       return hr_loan_app_pkg.render_summary(
                p_record_pk   => p_record_pk,
                p_approval_id => p_approval_id
            );
        elsif p_module_code = 'LOAN_MASTER' then
    return hr_loan_app_pkg.render_loan_summary(p_record_pk);
        else
            return render_generic_summary(p_approval_id);
        end if;
    end render_summary;


    ----------------------------------------------------------------------
    -- Dispatcher: P25 extra transaction details
    ----------------------------------------------------------------------

    function render_extra_details (
        p_module_code in varchar2,
        p_record_pk   in number,
        p_approval_id in number
    ) return clob
    is
    begin
        if p_module_code = 'PRO_DEAL' then

            return hr_pro_deal_app_pkg.render_extra_details(
                p_record_pk   => p_record_pk,
                p_approval_id => p_approval_id
            );

        /*
        Later:

        elsif p_module_code = 'LOAN_TXN' then
            return hr_loan_app_pkg.render_extra_details(
                p_record_pk   => p_record_pk,
                p_approval_id => p_approval_id
            );
        */
        elsif p_module_code = 'LOAN_TXN' then
    return hr_loan_app_pkg.render_extra_details(
        p_record_pk   => p_record_pk,
        p_approval_id => p_approval_id
    );
    elsif p_module_code = 'LOAN_MASTER' then
    return null;

        else
            return null;
        end if;
    end render_extra_details;


    ----------------------------------------------------------------------
    -- Dispatcher: email summary
    ----------------------------------------------------------------------

    function render_module_email_summary (
        p_module_code in varchar2,
        p_record_pk   in number,
        p_approval_id in number
    ) return clob
    is
    begin
        if p_module_code = 'PRO_DEAL' then

            return hr_pro_deal_app_pkg.render_email_summary(
                p_record_pk   => p_record_pk,
                p_approval_id => p_approval_id
            );

elsif p_module_code = 'LOAN_TXN' then
    return hr_loan_app_pkg.render_email_summary(
        p_record_pk   => p_record_pk,
        p_approval_id => p_approval_id
    );
        /*
        Later:

        elsif p_module_code = 'LOAN_TXN' then
            return hr_loan_app_pkg.render_email_summary(
                p_record_pk   => p_record_pk,
                p_approval_id => p_approval_id
            );
        */

        else
            return null;
        end if;
    end render_module_email_summary;


    ----------------------------------------------------------------------
    -- Dispatcher: email details
    ----------------------------------------------------------------------

    function render_module_email_details (
        p_module_code in varchar2,
        p_record_pk   in number,
        p_approval_id in number
    ) return clob
    is
    begin
        if p_module_code = 'PRO_DEAL' then

            return hr_pro_deal_app_pkg.render_email_details(
                p_record_pk   => p_record_pk,
                p_approval_id => p_approval_id
            );
elsif p_module_code = 'LOAN_TXN' then
    return hr_loan_app_pkg.render_email_details(
        p_record_pk   => p_record_pk,
        p_approval_id => p_approval_id
    );
        /*
        Later:

        elsif p_module_code = 'LOAN_TXN' then
            return hr_loan_app_pkg.render_email_details(
                p_record_pk   => p_record_pk,
                p_approval_id => p_approval_id
            );
        */

        else
            return null;
        end if;
    end render_module_email_details;


    ----------------------------------------------------------------------
    -- Common email wrapper
    -- Module packages provide summary/details only.
    ----------------------------------------------------------------------

    function render_approval_email (
        p_approval_step_id in number,
        p_task_id          in number
    ) return clob
    is
        l_html              clob;
        l_task_url          varchar2(4000);
        l_full_detail_url   varchar2(4000);
        l_email_summary     clob;
        l_email_details     clob;
        l_path_rows         clob;
        l_path_html         clob;
        l_base_url          varchar2(4000);
    begin
        begin
            l_base_url := apex_mail.get_instance_url;
        exception
            when others then
                l_base_url := null;
        end;

        l_task_url :=
            l_base_url ||
            'f?p=' || v('APP_ID') || ':25:0::NO::P25_TASK_ID:' || p_task_id;

        for r in (
            select s.approval_step_id,
                   s.approval_id,
                   s.step_name,
                   s.approver_users,
                   ar.approval_subject,
                   ar.approval_amount,
                   ar.requested_by,
                   to_char(ar.requested_dt, 'DD-MON-YYYY HH24:MI') requested_dt,
                   ar.module_code,
                   ar.record_pk,
                   ar.request_status
              from hr_approval_request_steps s
              join hr_approval_requests ar
                on ar.approval_id = s.approval_id
             where s.approval_step_id = p_approval_step_id
        )
        loop
            l_path_rows       := null;
            l_path_html       := null;
            l_email_summary   := null;
            l_email_details   := null;
            l_full_detail_url := null;

            l_full_detail_url := get_full_detail_url(
                                     p_module_code => r.module_code,
                                     p_record_pk   => r.record_pk
                                 );

            l_email_summary := render_module_email_summary(
                                   p_module_code => r.module_code,
                                   p_record_pk   => r.record_pk,
                                   p_approval_id => r.approval_id
                               );

            l_email_details := render_module_email_details(
                                   p_module_code => r.module_code,
                                   p_record_pk   => r.record_pk,
                                   p_approval_id => r.approval_id
                               );

            ------------------------------------------------------------------
            -- Approval path
            ------------------------------------------------------------------
            for p in (
                select step_seq,
                       nvl(step_name, 'Level ' || step_seq) step_name,
                       approver_users,
                       step_status,
                       action_by,
                       to_char(action_dt, 'DD-MON-YYYY HH24:MI') action_date,
                       comments
                  from hr_approval_request_steps
                 where approval_id = r.approval_id
                 order by step_seq
            )
            loop
                l_path_rows := l_path_rows ||
                    '<tr>' ||
                    '<td style="padding:8px;border-bottom:1px solid #eef2f7;">' || esc(to_char(p.step_seq)) || '</td>' ||
                    '<td style="padding:8px;border-bottom:1px solid #eef2f7;">' || esc(p.step_name) || '</td>' ||
                    '<td style="padding:8px;border-bottom:1px solid #eef2f7;">' || esc(p.approver_users) || '</td>' ||
                    '<td style="padding:8px;border-bottom:1px solid #eef2f7;">' || status_email_badge(p.step_status) || '</td>' ||
                    '<td style="padding:8px;border-bottom:1px solid #eef2f7;">' || esc(p.action_by) || '</td>' ||
                    '<td style="padding:8px;border-bottom:1px solid #eef2f7;">' || esc(p.action_date) || '</td>' ||
                    '</tr>';
            end loop;

            if l_path_rows is not null then
                l_path_html :=
                    '<div style="font-size:15px;font-weight:bold;color:#0f172a;margin:18px 0 8px 0;">Approval Path</div>' ||
                    '<table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;border:1px solid #e5e7eb;">' ||
                    '<tr>' ||
                    '<th align="left" style="padding:8px;background:#f8fafc;border-bottom:1px solid #e5e7eb;font-size:12px;color:#334155;">Seq</th>' ||
                    '<th align="left" style="padding:8px;background:#f8fafc;border-bottom:1px solid #e5e7eb;font-size:12px;color:#334155;">Step</th>' ||
                    '<th align="left" style="padding:8px;background:#f8fafc;border-bottom:1px solid #e5e7eb;font-size:12px;color:#334155;">Approver</th>' ||
                    '<th align="left" style="padding:8px;background:#f8fafc;border-bottom:1px solid #e5e7eb;font-size:12px;color:#334155;">Status</th>' ||
                    '<th align="left" style="padding:8px;background:#f8fafc;border-bottom:1px solid #e5e7eb;font-size:12px;color:#334155;">Action By</th>' ||
                    '<th align="left" style="padding:8px;background:#f8fafc;border-bottom:1px solid #e5e7eb;font-size:12px;color:#334155;">Action Date</th>' ||
                    '</tr>' ||
                    l_path_rows ||
                    '</table>';
            end if;

            ------------------------------------------------------------------
            -- Email body
            ------------------------------------------------------------------
            l_html :=
'<!DOCTYPE html>
<html>
<body style="margin:0;padding:0;background:#f1f5f9;font-family:Arial,Helvetica,sans-serif;">

<table width="100%" cellpadding="0" cellspacing="0" style="background:#f1f5f9;padding:20px;">
<tr>
<td align="center">

<table width="760" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:10px;border:1px solid #e5e7eb;overflow:hidden;">
<tr>
<td style="padding:18px 22px;background:#0f172a;color:#ffffff;">
  <div style="font-size:18px;font-weight:bold;">Approval Required</div>
  <div style="font-size:13px;color:#cbd5e1;margin-top:4px;">' || esc(r.approval_subject) || '</div>
</td>
</tr>

<tr>
<td style="padding:18px 22px;">

  <table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;border:1px solid #e5e7eb;">
    <tr>
      <td style="padding:9px;border-bottom:1px solid #eef2f7;background:#ffffff;">
        <div style="font-size:10px;text-transform:uppercase;color:#64748b;font-weight:bold;">Module</div>
        <div style="font-size:12.5px;font-weight:bold;margin-top:4px;">' || esc(r.module_code) || '</div>
      </td>
      <td style="padding:9px;border-bottom:1px solid #eef2f7;background:#ffffff;">
        <div style="font-size:10px;text-transform:uppercase;color:#64748b;font-weight:bold;">Record ID</div>
        <div style="font-size:12.5px;font-weight:bold;margin-top:4px;">' || esc(to_char(r.record_pk)) || '</div>
      </td>
      <td style="padding:9px;border-bottom:1px solid #eef2f7;background:#ffffff;">
        <div style="font-size:10px;text-transform:uppercase;color:#64748b;font-weight:bold;">Amount</div>
        <div style="font-size:12.5px;font-weight:bold;margin-top:4px;color:#9a3412;">' || amount_text(r.approval_amount) || '</div>
      </td>
      <td style="padding:9px;border-bottom:1px solid #eef2f7;background:#ffffff;">
        <div style="font-size:10px;text-transform:uppercase;color:#64748b;font-weight:bold;">Status</div>
        <div style="font-size:12.5px;font-weight:bold;margin-top:4px;">' || status_email_badge(r.request_status) || '</div>
      </td>
    </tr>

    <tr>
      <td style="padding:9px;background:#ffffff;">
        <div style="font-size:10px;text-transform:uppercase;color:#64748b;font-weight:bold;">Current Step</div>
        <div style="font-size:12.5px;font-weight:bold;margin-top:4px;">' || esc(r.step_name) || '</div>
      </td>
      <td style="padding:9px;background:#ffffff;">
        <div style="font-size:10px;text-transform:uppercase;color:#64748b;font-weight:bold;">Approver Users</div>
        <div style="font-size:12.5px;font-weight:bold;margin-top:4px;">' || esc(r.approver_users) || '</div>
      </td>
      <td style="padding:9px;background:#ffffff;">
        <div style="font-size:10px;text-transform:uppercase;color:#64748b;font-weight:bold;">Requested By</div>
        <div style="font-size:12.5px;font-weight:bold;margin-top:4px;">' || esc(r.requested_by) || '</div>
      </td>
      <td style="padding:9px;background:#ffffff;">
        <div style="font-size:10px;text-transform:uppercase;color:#64748b;font-weight:bold;">Requested Date</div>
        <div style="font-size:12.5px;font-weight:bold;margin-top:4px;">' || esc(r.requested_dt) || '</div>
      </td>
    </tr>
  </table>' ||

  nvl(l_email_summary, '') ||
  nvl(l_email_details, '') ||
  nvl(l_path_html, '') ||

  '<div style="text-align:center;margin-top:20px;">' ||

    case
      when l_task_url is not null then
        '<a href="' || apex_escape.html_attribute(l_task_url) || '"
           style="display:inline-block;background:#2563eb;color:#ffffff;padding:11px 18px;text-decoration:none;border-radius:7px;font-size:14px;font-weight:bold;margin-right:8px;">
           Open Approval Task
         </a>'
      else
        null
    end ||

    case
      when l_full_detail_url is not null then
        '<a href="' || apex_escape.html_attribute(l_full_detail_url) || '"
           style="display:inline-block;background:#475569;color:#ffffff;padding:11px 18px;text-decoration:none;border-radius:7px;font-size:14px;font-weight:bold;">
           View Full Detail
         </a>'
      else
        null
    end ||

  '</div>

  <p style="font-size:12px;color:#64748b;margin-top:14px;text-align:center;">
    Please login to HRMS to approve, reject, or request information.
  </p>

</td>
</tr>
</table>

</td>
</tr>
</table>

</body>
</html>';

            return l_html;
        end loop;

        return
            '<html><body>' ||
            '<p>Approval required. Please open HRMS to review and take action.</p>' ||
            '</body></html>';

    end render_approval_email;


    ----------------------------------------------------------------------
    -- Final approval module dispatcher
    ----------------------------------------------------------------------

    procedure final_approve_module (
        p_module_code in varchar2,
        p_record_pk   in number,
        p_approval_id in number,
        p_comments    in varchar2 default null
    )
    is
    begin
        if p_module_code = 'PRO_DEAL' then

            hr_pro_deal_app_pkg.approval_approved(
                p_record_pk   => p_record_pk,
                p_approval_id => p_approval_id,
                p_comments    => p_comments
            );
            elsif p_module_code = 'LOAN_TXN' then
    hr_loan_app_pkg.approval_approved(
        p_record_pk   => p_record_pk,
        p_approval_id => p_approval_id,
        p_comments    => p_comments
    );
    elsif p_module_code = 'LOAN_MASTER' then
    hr_loan_app_pkg.loan_approval_approved(p_record_pk);

        /*
        Later:

        elsif p_module_code = 'LOAN_TXN' then
            hr_loan_app_pkg.approval_approved(
                p_record_pk   => p_record_pk,
                p_approval_id => p_approval_id,
                p_comments    => p_comments
            );
        */

        else
            raise_application_error(
                -20901,
                'No final approval handler defined for module: ' || p_module_code
            );
        end if;
    end final_approve_module;


    ----------------------------------------------------------------------
    -- Final rejection module dispatcher
    ----------------------------------------------------------------------

    procedure final_reject_module (
        p_module_code in varchar2,
        p_record_pk   in number,
        p_approval_id in number,
        p_comments    in varchar2 default null
    )
    is
    begin
        if p_module_code = 'PRO_DEAL' then

            hr_pro_deal_app_pkg.approval_rejected(
                p_record_pk   => p_record_pk,
                p_approval_id => p_approval_id,
                p_reason      => p_comments
            );

        /*
        Later:

        elsif p_module_code = 'LOAN_TXN' then
            hr_loan_app_pkg.approval_rejected(
                p_record_pk   => p_record_pk,
                p_approval_id => p_approval_id,
                p_reason      => p_comments
            );
        */
    elsif p_module_code = 'LOAN_TXN' then
    hr_loan_app_pkg.approval_rejected(
        p_record_pk   => p_record_pk,
        p_approval_id => p_approval_id,
        p_reason      => p_comments
    );
elsif p_module_code = 'LOAN_MASTER' then
    hr_loan_app_pkg.loan_approval_rejected(p_record_pk, p_comments);
        else
            raise_application_error(
                -20902,
                'No rejection handler defined for module: ' || p_module_code
            );
        end if;
    end final_reject_module;

end hr_approval_ui_pkg;
/

create or replace package body hr_approval_wf_pkg as

    ----------------------------------------------------------------------
    -- PRIVATE: Get APEX task ID linked with approval step
    ----------------------------------------------------------------------
    function get_task_id_by_step (
        p_approval_step_id in number
    ) return number
    is
        l_task_id number;
    begin
        select max(task_id)
          into l_task_id
          from apex_tasks
         where detail_pk = to_char(p_approval_step_id);

        return l_task_id;

    exception
        when others then
            return null;
    end get_task_id_by_step;


    ----------------------------------------------------------------------
    -- PRIVATE: Get active users by SEC role
    ----------------------------------------------------------------------
    function get_role_users (
        p_role_code in varchar2
    ) return varchar2
    is
        l_users varchar2(4000);
    begin
        select listagg(user_name, ',') within group (order by user_name)
          into l_users
          from vw_sec_role_users
         where upper(role_code) = upper(p_role_code);

        if l_users is null then
            raise_application_error(
                -20150,
                'No active SEC_USERS found for SEC_ROLE: ' || p_role_code
            );
        end if;

        return l_users;
    end get_role_users;


    ----------------------------------------------------------------------
    -- PRIVATE: Resolve approver users
    ----------------------------------------------------------------------
    function get_approver_users (
        p_approver_type      in varchar2,
        p_approver_user_name in varchar2,
        p_approver_role_code in varchar2
    ) return varchar2
    is
        l_dummy number;
    begin
        if upper(p_approver_type) = 'USER' then

            select count(*)
              into l_dummy
              from vw_sec_apex_users
             where upper(user_name) = upper(p_approver_user_name);

            if l_dummy = 0 then
                raise_application_error(
                    -20151,
                    'Approver user is not active in SEC_USERS: ' || p_approver_user_name
                );
            end if;

            return upper(p_approver_user_name);

        elsif upper(p_approver_type) = 'ROLE' then

            return get_role_users(p_approver_role_code);

        else
            raise_application_error(
                -20152,
                'Invalid approver type: ' || p_approver_type
            );
        end if;
    end get_approver_users;


    ----------------------------------------------------------------------
    -- PRIVATE: Find matching approval rule
    ----------------------------------------------------------------------
    function find_rule (
        p_module_code   in varchar2,
        p_txn_type_code in varchar2,
        p_org_id        in number,
        p_amount        in number
    ) return number
    is
        l_rule_id number;
    begin
        select rule_id
          into l_rule_id
          from (
                select r.rule_id,
                       case when r.org_id = p_org_id then 1 else 0 end org_match,
                       case when r.txn_type_code = p_txn_type_code then 1 else 0 end type_match,
                       nvl(r.seq_no, 9999) seq_no
                  from hr_approval_rules r
                 where r.module_code = p_module_code
                   and r.is_active = 'Y'
                   and (r.txn_type_code is null or r.txn_type_code = p_txn_type_code)
                   and (r.org_id is null or r.org_id = p_org_id)
                   and nvl(p_amount, 0) between nvl(r.min_amount, 0)
                                            and nvl(r.max_amount, 999999999)
               )
         order by org_match desc,
                  type_match desc,
                  seq_no
         fetch first 1 row only;

        return l_rule_id;

    exception
        when no_data_found then
            raise_application_error(
                -20101,
                'No approval rule found for module=' || p_module_code ||
                ', type=' || p_txn_type_code ||
                ', org=' || p_org_id ||
                ', amount=' || p_amount
            );
    end find_rule;


    ----------------------------------------------------------------------
    -- PUBLIC: Start approval request and APEX workflow
    ----------------------------------------------------------------------
    procedure start_approval (
        p_module_code   in varchar2,
        p_record_pk     in number,
        p_txn_type_code in varchar2,
        p_org_id        in number,
        p_amount        in number,
        p_subject       in varchar2,
        p_approval_id   out number
    )
    is
        l_rule_id        number;
        l_workflow_id    number;
        l_step_count     number;
        l_approver_users varchar2(4000);
    begin
        l_rule_id := find_rule(
            p_module_code   => p_module_code,
            p_txn_type_code => p_txn_type_code,
            p_org_id        => p_org_id,
            p_amount        => p_amount
        );

        insert into hr_approval_requests (
            module_code,
            record_pk,
            txn_type_code,
            org_id,
            approval_subject,
            approval_amount,
            rule_id,
            request_status,
            final_action_done,
            requested_by,
            requested_dt,
            created_by,
            created_dt
        )
        values (
            p_module_code,
            p_record_pk,
            p_txn_type_code,
            p_org_id,
            p_subject,
            p_amount,
            l_rule_id,
            'SUBMITTED',
            'N',
            nvl(sys_context('APEX$SESSION','APP_USER'), user),
            cast(systimestamp at time zone 'Asia/Dubai' as timestamp),
            nvl(sys_context('APEX$SESSION','APP_USER'), user),
            cast(systimestamp at time zone 'Asia/Dubai' as timestamp)
        )
        returning approval_id into p_approval_id;


        /*
          IMPORTANT:
          Do not use GET_APPROVER_USERS inside INSERT SELECT.
          Private package functions cannot be used in SQL.
          Therefore we insert steps using a PL/SQL loop.
        */
        for s in (
            select step_seq,
                   step_name,
                   approver_type,
                   approver_user_name,
                   approver_role_code
              from hr_approval_rule_steps
             where rule_id = l_rule_id
             order by step_seq
        )
        loop
            l_approver_users := get_approver_users(
                p_approver_type      => s.approver_type,
                p_approver_user_name => s.approver_user_name,
                p_approver_role_code => s.approver_role_code
            );

            insert into hr_approval_request_steps (
                approval_id,
                step_seq,
                step_name,
                approver_type,
                approver_user_name,
                approver_role_code,
                approver_users,
                step_status,
                created_by,
                created_dt
            )
            values (
                p_approval_id,
                s.step_seq,
                s.step_name,
                s.approver_type,
                s.approver_user_name,
                s.approver_role_code,
                l_approver_users,
                'PENDING',
                nvl(sys_context('APEX$SESSION','APP_USER'), user),
                cast(systimestamp at time zone 'Asia/Dubai' as timestamp)
            );
        end loop;


        select count(*)
          into l_step_count
          from hr_approval_request_steps
         where approval_id = p_approval_id;

        if l_step_count = 0 then
            raise_application_error(
                -20153,
                'Approval rule found, but no approval steps are defined. Rule ID: ' || l_rule_id
            );
        end if;


        insert into hr_approval_action_log (
            approval_id,
            action_code,
            action_by,
            action_dt,
            comments
        )
        values (
            p_approval_id,
            'SUBMITTED',
            nvl(sys_context('APEX$SESSION','APP_USER'), user),
            cast(systimestamp at time zone 'Asia/Dubai' as timestamp),
            'Approval submitted and workflow started.'
        );


        l_workflow_id := apex_workflow.start_workflow(
            p_application_id => apex_application.g_flow_id,
            p_static_id      => 'WF_UNIFIED_APPROVAL',
            p_parameters     => apex_workflow.t_workflow_parameters(
                1 => apex_workflow.t_workflow_parameter(
                        static_id    => 'APPROVAL_ID',
                        string_value => to_char(p_approval_id)
                     )
            ),
            p_initiator      => nvl(sys_context('APEX$SESSION','APP_USER'), user),
            p_detail_pk      => to_char(p_approval_id)
        );


        update hr_approval_requests
           set workflow_id = l_workflow_id,
               updated_by  = nvl(sys_context('APEX$SESSION','APP_USER'), user),
               updated_dt  = cast(systimestamp at time zone 'Asia/Dubai' as timestamp)
         where approval_id = p_approval_id;

    exception
        when others then
            raise;
    end start_approval;


    ----------------------------------------------------------------------
    -- PUBLIC: Get next pending approval step for workflow
    ----------------------------------------------------------------------
    procedure get_next_step (
        p_approval_id     in number,
        p_step_id         out number,
        p_approver_users  out varchar2,
        p_task_subject    out varchar2,
        p_module_code     out varchar2,
        p_record_pk       out number
    )
    is
    begin
        select s.approval_step_id,
               s.approver_users,
               r.approval_subject,
               r.module_code,
               r.record_pk
          into p_step_id,
               p_approver_users,
               p_task_subject,
               p_module_code,
               p_record_pk
          from hr_approval_request_steps s
          join hr_approval_requests r
            on r.approval_id = s.approval_id
         where s.approval_id = p_approval_id
           and s.step_status = 'PENDING'
         order by s.step_seq
         fetch first 1 row only;


        update hr_approval_request_steps
           set step_status = 'TASK_CREATED',
               updated_by  = nvl(sys_context('APEX$SESSION','APP_USER'), user),
               updated_dt  = cast(systimestamp at time zone 'Asia/Dubai' as timestamp)
         where approval_step_id = p_step_id;


        insert into hr_approval_action_log (
            approval_id,
            approval_step_id,
            action_code,
            action_by,
            action_dt,
            comments
        )
        values (
            p_approval_id,
            p_step_id,
            'TASK_CREATED',
            nvl(sys_context('APEX$SESSION','APP_USER'), user),
            cast(systimestamp at time zone 'Asia/Dubai' as timestamp),
            'Workflow created task for current approval step.'
        );

    exception
        when no_data_found then
            raise_application_error(
                -20154,
                'No pending approval step found for Approval ID: ' || p_approval_id
            );
    end get_next_step;


    ----------------------------------------------------------------------
    -- PUBLIC: Mark approval step approved
    ----------------------------------------------------------------------
    procedure mark_step_approved (
        p_step_id       in number,
        p_approver_user in varchar2,
        p_comments      in varchar2,
        p_has_next_step out varchar2
    )
    is
        l_approval_id number;
        l_count       number;
        l_task_id     number;
    begin
        l_task_id := get_task_id_by_step(p_step_id);

        update hr_approval_request_steps
           set step_status  = 'APPROVED',
               apex_task_id = l_task_id,
               action_by    = p_approver_user,
               action_dt    = cast(systimestamp at time zone 'Asia/Dubai' as timestamp),
               comments     = p_comments,
               updated_by   = nvl(sys_context('APEX$SESSION','APP_USER'), user),
               updated_dt   = cast(systimestamp at time zone 'Asia/Dubai' as timestamp)
         where approval_step_id = p_step_id
           and step_status = 'TASK_CREATED'
         returning approval_id into l_approval_id;


        insert into hr_approval_action_log (
            approval_id,
            approval_step_id,
            action_code,
            action_by,
            action_dt,
            comments
        )
        values (
            l_approval_id,
            p_step_id,
            'APPROVED',
            p_approver_user,
            cast(systimestamp at time zone 'Asia/Dubai' as timestamp),
            p_comments
        );


        select count(*)
          into l_count
          from hr_approval_request_steps
         where approval_id = l_approval_id
           and step_status = 'PENDING';

        p_has_next_step := case when l_count > 0 then 'Y' else 'N' end;

    exception
        when no_data_found then
            raise_application_error(
                -20155,
                'Approval step is not in TASK_CREATED status or does not exist. Step ID: ' || p_step_id
            );
    end mark_step_approved;


    ----------------------------------------------------------------------
    -- PUBLIC: Mark approval step rejected
    ----------------------------------------------------------------------
    procedure mark_step_rejected (
        p_step_id       in number,
        p_approver_user in varchar2,
        p_comments      in varchar2
    )
    is
        l_approval_id number;
        l_task_id     number;
    begin
        l_task_id := get_task_id_by_step(p_step_id);

        update hr_approval_request_steps
           set step_status  = 'REJECTED',
               apex_task_id = l_task_id,
               action_by    = p_approver_user,
               action_dt    = cast(systimestamp at time zone 'Asia/Dubai' as timestamp),
               comments     = p_comments,
               updated_by   = nvl(sys_context('APEX$SESSION','APP_USER'), user),
               updated_dt   = cast(systimestamp at time zone 'Asia/Dubai' as timestamp)
         where approval_step_id = p_step_id
           and step_status = 'TASK_CREATED'
         returning approval_id into l_approval_id;


        update hr_approval_request_steps
           set step_status = 'CANCELLED',
               updated_by  = nvl(sys_context('APEX$SESSION','APP_USER'), user),
               updated_dt  = cast(systimestamp at time zone 'Asia/Dubai' as timestamp)
         where approval_id = l_approval_id
           and step_status = 'PENDING';


        insert into hr_approval_action_log (
            approval_id,
            approval_step_id,
            action_code,
            action_by,
            action_dt,
            comments
        )
        values (
            l_approval_id,
            p_step_id,
            'REJECTED',
            p_approver_user,
            cast(systimestamp at time zone 'Asia/Dubai' as timestamp),
            p_comments
        );

    exception
        when no_data_found then
            raise_application_error(
                -20156,
                'Approval step is not in TASK_CREATED status or does not exist. Step ID: ' || p_step_id
            );
    end mark_step_rejected;


    ----------------------------------------------------------------------
    -- PUBLIC: Final approval after all steps are approved
    ----------------------------------------------------------------------
    procedure final_approve (
        p_approval_id in number
    )
    is
        l_module_code varchar2(50);
        l_record_pk   number;
    begin
        update hr_approval_requests
           set request_status    = 'APPROVED',
               final_action_done = 'Y',
               updated_by        = nvl(sys_context('APEX$SESSION','APP_USER'), user),
               updated_dt        = cast(systimestamp at time zone 'Asia/Dubai' as timestamp)
         where approval_id = p_approval_id
           and request_status = 'SUBMITTED'
           and nvl(final_action_done, 'N') = 'N';


        if sql%rowcount = 0 then
            raise_application_error(
                -20201,
                'Approval request is already completed or not in SUBMITTED status. Approval ID: ' || p_approval_id
            );
        end if;


        select module_code,
               record_pk
          into l_module_code,
               l_record_pk
          from hr_approval_requests
         where approval_id = p_approval_id;


        hr_approval_ui_pkg.final_approve_module(
            p_module_code => l_module_code,
            p_record_pk   => l_record_pk,
            p_approval_id => p_approval_id,
            p_comments    => null
        );


        insert into hr_approval_action_log (
            approval_id,
            action_code,
            action_by,
            action_dt,
            comments
        )
        values (
            p_approval_id,
            'FINAL_APPROVED',
            nvl(sys_context('APEX$SESSION','APP_USER'), user),
            cast(systimestamp at time zone 'Asia/Dubai' as timestamp),
            'Final approval completed.'
        );

    exception
        when no_data_found then
            raise_application_error(
                -20202,
                'Approval request not found. Approval ID: ' || p_approval_id
            );
    end final_approve;


    ----------------------------------------------------------------------
    -- PUBLIC: Final rejection after any step is rejected
    ----------------------------------------------------------------------
    procedure final_reject (
        p_approval_id in number,
        p_reason      in varchar2
    )
    is
        l_module_code varchar2(50);
        l_record_pk   number;
    begin
        update hr_approval_requests
           set request_status    = 'REJECTED',
               final_action_done = 'Y',
               updated_by        = nvl(sys_context('APEX$SESSION','APP_USER'), user),
               updated_dt        = cast(systimestamp at time zone 'Asia/Dubai' as timestamp)
         where approval_id = p_approval_id
           and request_status = 'SUBMITTED'
           and nvl(final_action_done, 'N') = 'N';


        if sql%rowcount = 0 then
            raise_application_error(
                -20203,
                'Approval request is already completed or not in SUBMITTED status. Approval ID: ' || p_approval_id
            );
        end if;


        select module_code,
               record_pk
          into l_module_code,
               l_record_pk
          from hr_approval_requests
         where approval_id = p_approval_id;


        hr_approval_ui_pkg.final_reject_module(
            p_module_code => l_module_code,
            p_record_pk   => l_record_pk,
            p_approval_id => p_approval_id,
            p_comments    => p_reason
        );


        insert into hr_approval_action_log (
            approval_id,
            action_code,
            action_by,
            action_dt,
            comments
        )
        values (
            p_approval_id,
            'FINAL_REJECTED',
            nvl(sys_context('APEX$SESSION','APP_USER'), user),
            cast(systimestamp at time zone 'Asia/Dubai' as timestamp),
            p_reason
        );

    exception
        when no_data_found then
            raise_application_error(
                -20204,
                'Approval request not found. Approval ID: ' || p_approval_id
            );
    end final_reject;

end hr_approval_wf_pkg;
/

create or replace package body hr_asg_pkg as

  procedure validate_assignment(
    p_asg_id    number,
    p_emp_id    number,
    p_start_dt  date,
    p_end_dt    date
  ) is
    l_cnt number;
  begin
    if p_start_dt is null then
      raise_application_error(-20020, 'Start date is required.');
    end if;

    if p_end_dt is not null and p_end_dt < p_start_dt then
      raise_application_error(-20021, 'End date cannot be less than start date.');
    end if;

    /*
      Overlap logic:
      New period overlaps old period if:
      new_start <= old_end_or_highdate
      and new_end_or_highdate >= old_start
    */
    select count(*)
      into l_cnt
      from hr_assignments a
     where a.emp_id = p_emp_id
       and nvl(a.asg_id, -1) <> nvl(p_asg_id, -1)
       and p_start_dt <= nvl(a.end_dt, date '4712-12-31')
       and nvl(p_end_dt, date '4712-12-31') >= a.start_dt;

    if l_cnt > 0 then
      raise_application_error(-20022, 'Assignment date range overlaps an existing assignment.');
    end if;
  end validate_assignment;


  procedure sync_emp_status(
    p_emp_id number
  ) is
    l_current_cnt number;
    l_current_status varchar2(30);
  begin
    select count(*)
      into l_current_cnt
      from hr_assignments
     where emp_id = p_emp_id
       and end_dt is null;

    begin
      select status_code
        into l_current_status
        from hr_emp_status_hist
       where emp_id = p_emp_id
         and effective_to is null;
    exception
      when no_data_found then
        l_current_status := null;
    end;

    if nvl(l_current_cnt,0) > 0 then
      if nvl(l_current_status,'A') <> 'ACTIVE' then
        hr_status_pkg.set_status(
          p_emp_id          => p_emp_id,
          p_status_code     => 'ACTIVE',
          p_effective_from  => trunc(sysdate),
          p_reason          => 'Assignment Update',
          p_remarks         => 'Employee has active assignment'
        );
      end if;
    else
      if nvl(l_current_status,'A') <> 'OFFBOARD' then
        hr_status_pkg.set_status(
          p_emp_id          => p_emp_id,
          p_status_code     => 'OFFBOARD',
          p_effective_from  => trunc(sysdate),
          p_reason          => 'Assignment Update',
          p_remarks         => 'Employee has no active assignment'
        );
      end if;
    end if;
  end sync_emp_status;

end;
/

create or replace package body hr_bike_req_pkg as

    function app_user return varchar2 is
    begin
        return nvl(sys_context('APEX$SESSION','APP_USER'), user);
    end app_user;


    function uae_now return date is
    begin
        return cast(systimestamp at time zone 'Asia/Dubai' as date);
    end uae_now;


    procedure add_log (
        p_request_id in number,
        p_action     in varchar2,
        p_old_status in varchar2,
        p_new_status in varchar2,
        p_remarks    in varchar2 default null
    ) is
        l_user varchar2(100);
        l_now  date;
    begin
        l_user := app_user;
        l_now  := uae_now;

        insert into hr_bike_request_log (
            request_id,
            action_code,
            old_status,
            new_status,
            remarks,
            action_by,
            action_dt
        )
        values (
            p_request_id,
            p_action,
            p_old_status,
            p_new_status,
            p_remarks,
            l_user,
            l_now
        );
    end add_log;


    function create_request (
    p_emp_id               in number,
    p_request_type         in varchar2,
    p_priority             in varchar2 default 'NORMAL',
    p_required_by_dt       in date default null,
    p_requested_project_id in number default null,
    p_requested_city_id    in number default null,
    p_reason_code          in varchar2 default null,
    p_remarks              in varchar2 default null
) return number is

    l_request_id      number;
    l_open_count      number;
    l_current_bike_id number;
    l_project_id      number;
    l_city_id         number;
begin
    if p_emp_id is null then
        raise_application_error(-20001, 'Employee is required.');
    end if;

    if p_request_type is null then
        raise_application_error(-20001, 'Bike request type is required.');
    end if;

    select count(*)
      into l_open_count
      from hr_bike_requests
     where emp_id = p_emp_id
       and request_status in ('OPEN','IN_PROGRESS');

    if l_open_count > 0 then
        raise_application_error(
            -20001,
            'There is already an open bike request for this employee.'
        );
    end if;

    begin
        select bike_id
          into l_current_bike_id
          from vw_hr_emp_current_bike
         where emp_id = p_emp_id;
    exception
        when no_data_found then
            l_current_bike_id := null;
    end;

    l_project_id := p_requested_project_id;
    l_city_id    := p_requested_city_id;

    if l_project_id is null or l_city_id is null then
        begin
            select project_id,
                   city_id
              into l_project_id,
                   l_city_id
              from (
                    select project_id,
                           city_id
                      from hr_emp_status_hist
                     where emp_id = p_emp_id
                       and effective_to is null
                     order by effective_from desc, status_id desc
                   )
             where rownum = 1;
        exception
            when no_data_found then
                null;
        end;
    end if;

    insert into hr_bike_requests (
        emp_id,
        request_type,
        request_status,
        priority,
        required_by_dt,
        current_bike_id,
        requested_project_id,
        requested_city_id,
        reason_code,
        request_remarks
    )
    values (
        p_emp_id,
        upper(p_request_type),
        'OPEN',
        upper(nvl(p_priority, 'NORMAL')),
        p_required_by_dt,
        l_current_bike_id,
        l_project_id,
        l_city_id,
        upper(p_reason_code),
        p_remarks
    )
    returning request_id into l_request_id;

    add_log(
        p_request_id => l_request_id,
        p_action     => 'CREATE',
        p_old_status => null,
        p_new_status => 'OPEN',
        p_remarks    => p_remarks
    );

    return l_request_id;
end create_request;


    procedure set_status (
        p_request_id in number,
        p_status     in varchar2,
        p_remarks    in varchar2 default null
    ) is
        l_old_status varchar2(30);
        l_new_status varchar2(30);
        l_user       varchar2(100);
        l_now        date;
    begin
        if p_request_id is null then
            raise_application_error(-20001, 'Request ID is required.');
        end if;

        if p_status is null then
            raise_application_error(-20001, 'Status is required.');
        end if;

        l_new_status := upper(p_status);
        l_user       := app_user;
        l_now        := uae_now;

        select request_status
          into l_old_status
          from hr_bike_requests
         where request_id = p_request_id
         for update;

        if l_old_status = l_new_status then
            return;
        end if;

        update hr_bike_requests
           set request_status   = l_new_status,
               rejection_reason = case
                                      when l_new_status = 'REJECTED'
                                      then p_remarks
                                      else rejection_reason
                                  end,
               closed_by        = case
                                      when l_new_status in ('REJECTED','CANCELLED','CLOSED')
                                      then l_user
                                      else closed_by
                                  end,
               closed_dt        = case
                                      when l_new_status in ('REJECTED','CANCELLED','CLOSED')
                                      then l_now
                                      else closed_dt
                                  end
         where request_id = p_request_id;

        add_log(
            p_request_id => p_request_id,
            p_action     => 'STATUS_CHANGE',
            p_old_status => l_old_status,
            p_new_status => l_new_status,
            p_remarks    => p_remarks
        );
    end set_status;


    procedure close_after_assignment (
        p_emp_id             in number,
        p_bike_id            in number default null,
        p_bike_assignment_id in number default null,
        p_request_id         in number default null
    ) is
        l_request_id number;
        l_old_status varchar2(30);
        l_bike_id    number;
        l_user       varchar2(100);
        l_now        date;
    begin
        if p_emp_id is null then
            return;
        end if;

        l_user := app_user;
        l_now  := uae_now;

        l_request_id := p_request_id;

        if l_request_id is null then
            begin
                select request_id
                  into l_request_id
                  from (
                        select request_id
                          from hr_bike_requests
                         where emp_id = p_emp_id
                           and request_status in ('OPEN','IN_PROGRESS')
                         order by requested_dt desc, request_id desc
                       )
                 where rownum = 1;
            exception
                when no_data_found then
                    return;
            end;
        end if;

        l_bike_id := p_bike_id;

        if l_bike_id is null then
            begin
                select bike_id
                  into l_bike_id
                  from vw_hr_emp_current_bike
                 where emp_id = p_emp_id;
            exception
                when no_data_found then
                    l_bike_id := null;
            end;
        end if;

        select request_status
          into l_old_status
          from hr_bike_requests
         where request_id = l_request_id
         for update;

        update hr_bike_requests
           set request_status     = 'ASSIGNED',
               assigned_bike_id   = l_bike_id,
               bike_assignment_id = p_bike_assignment_id,
               closed_by          = l_user,
               closed_dt          = l_now
         where request_id = l_request_id;

        add_log(
            p_request_id => l_request_id,
            p_action     => 'ASSIGNED',
            p_old_status => l_old_status,
            p_new_status => 'ASSIGNED',
            p_remarks    => 'Bike assigned and request closed'
        );
    end close_after_assignment;

end hr_bike_req_pkg;
/

create or replace package body hr_charges_pkg as

    procedure raise_err(p_msg in varchar2) is
    begin
        raise_application_error(-20001, p_msg);
    end;

    procedure append_remarks (
        p_old_remarks in out varchar2,
        p_new_remarks in varchar2
    ) is
    begin
        if p_new_remarks is not null then
            if p_old_remarks is null then
                p_old_remarks := p_new_remarks;
            else
                p_old_remarks := p_old_remarks || ' | ' || p_new_remarks;
            end if;
        end if;
    end append_remarks;

    procedure validate_charge (
        p_emp_charge_id           in hr_emp_charges.emp_charge_id%type default null,
        p_emp_id                  in hr_emp_charges.emp_id%type,
        p_charge_type             in hr_emp_charges.charge_type%type,
        p_recurrence_type         in hr_emp_charges.recurrence_type%type,
        p_charge_ts               in hr_emp_charges.charge_ts%type,
        p_amount                  in hr_emp_charges.amount%type,
        p_source_start_dt         in hr_emp_charges.source_start_dt%type,
        p_source_end_dt           in hr_emp_charges.source_end_dt%type,
        p_charge_to_employee_yn   in hr_emp_charges.charge_to_employee_yn%type,
        p_excluded_from_charge_yn in hr_emp_charges.excluded_from_charge_yn%type,
        p_approval_status         in hr_emp_charges.approval_status%type
    ) is
        l_cnt number;
    begin
        if p_emp_id is null then
            raise_err('Employee is required.');
        end if;

        if p_charge_type is null then
            raise_err('Charge type is required.');
        end if;

        if p_recurrence_type is null then
            raise_err('Recurrence type is required.');
        end if;

        if p_charge_ts is null then
            raise_err('Charge timestamp is required.');
        end if;

        if nvl(p_amount,0) <= 0 then
            raise_err('Charge amount must be greater than zero.');
        end if;

        if p_charge_to_employee_yn not in ('Y','N') then
            raise_err('Charge to employee must be Y or N.');
        end if;

        if p_excluded_from_charge_yn not in ('Y','N') then
            raise_err('Excluded from charge must be Y or N.');
        end if;

        if p_approval_status not in ('DRAFT','APPROVED','CANCELLED','CLOSED','BAD_DEBT') then
            raise_err('Invalid approval status.');
        end if;

        if p_recurrence_type in ('YEARLY','MONTHLY') then
            if p_source_start_dt is null or p_source_end_dt is null then
                raise_err('Source Start Date and Source End Date are required for recurring charges.');
            end if;

            if p_source_end_dt < p_source_start_dt then
                raise_err('Source End Date cannot be earlier than Source Start Date.');
            end if;

            select count(*)
              into l_cnt
              from hr_emp_charges c
             where c.emp_id = p_emp_id
               and c.charge_type = p_charge_type
               and c.recurrence_type = p_recurrence_type
               and c.approval_status <> 'CANCELLED'
               and nvl(c.emp_charge_id,-1) <> nvl(p_emp_charge_id,-1)
               and p_source_start_dt <= nvl(c.source_end_dt, p_source_start_dt)
               and p_source_end_dt   >= nvl(c.source_start_dt, p_source_end_dt);

            if l_cnt > 0 then
                raise_err('A recurring charge already exists for this employee within the selected charge period.');
            end if;
        end if;
    end validate_charge;

    procedure refresh_charge_header_status (
        p_emp_charge_id in hr_emp_charges.emp_charge_id%type
    ) is
        l_pending_cnt number;
        l_open_cnt    number;
        l_bad_debt_cnt number;
    begin
        select count(*)
          into l_open_cnt
          from hr_emp_charge_installments
         where emp_charge_id = p_emp_charge_id
           and status_code in ('PENDING','ON_HOLD');

        select count(*)
          into l_pending_cnt
          from hr_emp_charge_installments
         where emp_charge_id = p_emp_charge_id
           and status_code = 'PENDING';

        select count(*)
          into l_bad_debt_cnt
          from hr_emp_charge_installments
         where emp_charge_id = p_emp_charge_id
           and status_code = 'BAD_DEBT';

        if l_open_cnt = 0 then
            if l_bad_debt_cnt > 0 then
                update hr_emp_charges
                   set approval_status = 'CLOSED',
                       payroll_processed_yn = 'Y'
                 where emp_charge_id = p_emp_charge_id
                   and approval_status not in ('CANCELLED','BAD_DEBT');
            else
                update hr_emp_charges
                   set approval_status = 'CLOSED',
                       payroll_processed_yn = 'Y'
                 where emp_charge_id = p_emp_charge_id
                   and approval_status not in ('CANCELLED','BAD_DEBT');
            end if;
        else
            update hr_emp_charges
               set payroll_processed_yn = 'N'
             where emp_charge_id = p_emp_charge_id
               and approval_status = 'CLOSED';
        end if;
    end refresh_charge_header_status;

    procedure create_charge (
        p_emp_id                    in hr_emp_charges.emp_id%type,
        p_charge_type               in hr_emp_charges.charge_type%type,
        p_recurrence_type           in hr_emp_charges.recurrence_type%type default 'ONE_TIME',
        p_charge_ts                 in hr_emp_charges.charge_ts%type,
        p_amount                    in hr_emp_charges.amount%type,
        p_source_start_dt           in hr_emp_charges.source_start_dt%type default null,
        p_source_end_dt             in hr_emp_charges.source_end_dt%type default null,
        p_source_table_name         in hr_emp_charges.source_table_name%type default null,
        p_source_row_id             in hr_emp_charges.source_row_id%type default null,
        p_bike_id                   in hr_emp_charges.bike_id%type default null,
        p_charge_to_employee_yn     in hr_emp_charges.charge_to_employee_yn%type default 'Y',
        p_excluded_from_charge_yn   in hr_emp_charges.excluded_from_charge_yn%type default 'N',
        p_approval_status           in hr_emp_charges.approval_status%type default 'APPROVED',
        p_payroll_deduction_code    in hr_emp_charges.payroll_deduction_code%type default null,
        p_remarks                   in hr_emp_charges.remarks%type default null,
        p_emp_charge_id             out hr_emp_charges.emp_charge_id%type
    ) is
    begin
        validate_charge(
            p_emp_charge_id           => null,
            p_emp_id                  => p_emp_id,
            p_charge_type             => p_charge_type,
            p_recurrence_type         => p_recurrence_type,
            p_charge_ts               => p_charge_ts,
            p_amount                  => p_amount,
            p_source_start_dt         => p_source_start_dt,
            p_source_end_dt           => p_source_end_dt,
            p_charge_to_employee_yn   => p_charge_to_employee_yn,
            p_excluded_from_charge_yn => p_excluded_from_charge_yn,
            p_approval_status         => p_approval_status
        );

        insert into hr_emp_charges (
            emp_id,
            charge_type,
            recurrence_type,
            charge_ts,
            amount,
            source_start_dt,
            source_end_dt,
            source_table_name,
            source_row_id,
            bike_id,
            charge_to_employee_yn,
            excluded_from_charge_yn,
            approval_status,
            payroll_deduction_code,
            remarks
        ) values (
            p_emp_id,
            p_charge_type,
            p_recurrence_type,
            p_charge_ts,
            p_amount,
            p_source_start_dt,
            p_source_end_dt,
            p_source_table_name,
            p_source_row_id,
            p_bike_id,
            p_charge_to_employee_yn,
            p_excluded_from_charge_yn,
            p_approval_status,
            p_payroll_deduction_code,
            p_remarks
        )
        returning emp_charge_id into p_emp_charge_id;
    end create_charge;

    procedure update_charge (
        p_emp_charge_id             in hr_emp_charges.emp_charge_id%type,
        p_emp_id                    in hr_emp_charges.emp_id%type,
        p_charge_type               in hr_emp_charges.charge_type%type,
        p_recurrence_type           in hr_emp_charges.recurrence_type%type,
        p_charge_ts                 in hr_emp_charges.charge_ts%type,
        p_amount                    in hr_emp_charges.amount%type,
        p_source_start_dt           in hr_emp_charges.source_start_dt%type default null,
        p_source_end_dt             in hr_emp_charges.source_end_dt%type default null,
        p_source_table_name         in hr_emp_charges.source_table_name%type default null,
        p_source_row_id             in hr_emp_charges.source_row_id%type default null,
        p_bike_id                   in hr_emp_charges.bike_id%type default null,
        p_charge_to_employee_yn     in hr_emp_charges.charge_to_employee_yn%type default 'Y',
        p_excluded_from_charge_yn   in hr_emp_charges.excluded_from_charge_yn%type default 'N',
        p_approval_status           in hr_emp_charges.approval_status%type default 'APPROVED',
        p_payroll_deduction_code    in hr_emp_charges.payroll_deduction_code%type default null,
        p_remarks                   in hr_emp_charges.remarks%type default null
    ) is
    begin
        if p_emp_charge_id is null then
            raise_err('Charge ID is required.');
        end if;

        validate_charge(
            p_emp_charge_id           => p_emp_charge_id,
            p_emp_id                  => p_emp_id,
            p_charge_type             => p_charge_type,
            p_recurrence_type         => p_recurrence_type,
            p_charge_ts               => p_charge_ts,
            p_amount                  => p_amount,
            p_source_start_dt         => p_source_start_dt,
            p_source_end_dt           => p_source_end_dt,
            p_charge_to_employee_yn   => p_charge_to_employee_yn,
            p_excluded_from_charge_yn => p_excluded_from_charge_yn,
            p_approval_status         => p_approval_status
        );

        update hr_emp_charges
           set emp_id                  = p_emp_id,
               charge_type             = p_charge_type,
               recurrence_type         = p_recurrence_type,
               charge_ts               = p_charge_ts,
               amount                  = p_amount,
               source_start_dt         = p_source_start_dt,
               source_end_dt           = p_source_end_dt,
               source_table_name       = p_source_table_name,
               source_row_id           = p_source_row_id,
               bike_id                 = p_bike_id,
               charge_to_employee_yn   = p_charge_to_employee_yn,
               excluded_from_charge_yn = p_excluded_from_charge_yn,
               approval_status         = p_approval_status,
               payroll_deduction_code  = p_payroll_deduction_code,
               remarks                 = p_remarks
         where emp_charge_id = p_emp_charge_id;
    end update_charge;

    procedure create_single_installment (
        p_emp_charge_id             in hr_emp_charge_installments.emp_charge_id%type,
        p_due_dt                    in hr_emp_charge_installments.due_dt%type,
        p_amount                    in hr_emp_charge_installments.amount%type,
        p_remarks                   in hr_emp_charge_installments.remarks%type default null
    ) is
        l_cnt number;
    begin
        if p_emp_charge_id is null then
            raise_err('Charge is required.');
        end if;

        if p_due_dt is null then
            raise_err('Due date is required.');
        end if;

        if nvl(p_amount,0) <= 0 then
            raise_err('Installment amount must be greater than zero.');
        end if;

        select count(*)
          into l_cnt
          from hr_emp_charge_installments
         where emp_charge_id = p_emp_charge_id;

        insert into hr_emp_charge_installments (
            emp_charge_id,
            installment_no,
            due_dt,
            amount,
            status_code,
            remarks
        ) values (
            p_emp_charge_id,
            l_cnt + 1,
            p_due_dt,
            p_amount,
            'PENDING',
            p_remarks
        );
    end create_single_installment;

    procedure create_equal_installments (
        p_emp_charge_id             in hr_emp_charge_installments.emp_charge_id%type,
        p_first_due_dt              in date,
        p_no_of_installments        in number,
        p_remarks                   in varchar2 default null
    ) is
        l_amount       number;
        l_base_amt     number;
        l_last_amt     number;
        l_existing_cnt number;
    begin
        if p_emp_charge_id is null then
            raise_err('Charge is required.');
        end if;

        if p_first_due_dt is null then
            raise_err('First due date is required.');
        end if;

        if nvl(p_no_of_installments,0) <= 0 then
            raise_err('Number of installments must be greater than zero.');
        end if;

        select count(*)
          into l_existing_cnt
          from hr_emp_charge_installments
         where emp_charge_id = p_emp_charge_id
           and status_code <> 'CANCELLED';

        if l_existing_cnt > 0 then
            raise_err('Installments already exist. Cancel existing installments before regenerating.');
        end if;

        select amount
          into l_amount
          from hr_emp_charges
         where emp_charge_id = p_emp_charge_id;

        l_base_amt := round(l_amount / p_no_of_installments, 2);
        l_last_amt := l_amount - (l_base_amt * (p_no_of_installments - 1));

        for i in 1 .. p_no_of_installments loop
            insert into hr_emp_charge_installments (
                emp_charge_id,
                installment_no,
                due_dt,
                amount,
                status_code,
                remarks
            ) values (
                p_emp_charge_id,
                i,
                add_months(p_first_due_dt, i - 1),
                case when i = p_no_of_installments then l_last_amt else l_base_amt end,
                'PENDING',
                p_remarks
            );
        end loop;
    end create_equal_installments;

    procedure update_installment_status (
        p_installment_id in hr_emp_charge_installments.installment_id%type,
        p_new_status     in hr_emp_charge_installments.status_code%type,
        p_payroll_run_ref in hr_emp_charge_installments.payroll_run_ref%type default null,
        p_hold_from_dt   in hr_emp_charge_installments.hold_from_dt%type default null,
        p_hold_to_dt     in hr_emp_charge_installments.hold_to_dt%type default null,
        p_remarks        in varchar2 default null
    ) is
        l_emp_charge_id number;
        l_old_remarks   varchar2(500);
    begin
        if p_installment_id is null then
            raise_err('Installment is required.');
        end if;

        select emp_charge_id, remarks
          into l_emp_charge_id, l_old_remarks
          from hr_emp_charge_installments
         where installment_id = p_installment_id;

        append_remarks(l_old_remarks, p_remarks);

        update hr_emp_charge_installments
           set status_code     = p_new_status,
               payroll_run_ref = case when p_new_status = 'PROCESSED' then p_payroll_run_ref else payroll_run_ref end,
               processed_ts    = case when p_new_status = 'PROCESSED' then systimestamp else processed_ts end,
               hold_from_dt    = case when p_new_status = 'ON_HOLD' then p_hold_from_dt else hold_from_dt end,
               hold_to_dt      = case when p_new_status = 'ON_HOLD' then p_hold_to_dt else hold_to_dt end,
               remarks         = l_old_remarks
         where installment_id = p_installment_id;

        refresh_charge_header_status(l_emp_charge_id);
    end update_installment_status;

    procedure mark_installment_processed (
        p_installment_id            in hr_emp_charge_installments.installment_id%type,
        p_payroll_run_ref           in hr_emp_charge_installments.payroll_run_ref%type default null,
        p_remarks                   in varchar2 default null
    ) is
    begin
        update_installment_status(
            p_installment_id  => p_installment_id,
            p_new_status      => 'PROCESSED',
            p_payroll_run_ref => p_payroll_run_ref,
            p_remarks         => p_remarks
        );
    end mark_installment_processed;

    procedure mark_installment_hold (
        p_installment_id            in hr_emp_charge_installments.installment_id%type,
        p_hold_from_dt              in hr_emp_charge_installments.hold_from_dt%type default trunc(sysdate),
        p_hold_to_dt                in hr_emp_charge_installments.hold_to_dt%type default null,
        p_remarks                   in varchar2 default null
    ) is
    begin
        update_installment_status(
            p_installment_id => p_installment_id,
            p_new_status     => 'ON_HOLD',
            p_hold_from_dt   => p_hold_from_dt,
            p_hold_to_dt     => p_hold_to_dt,
            p_remarks        => p_remarks
        );
    end mark_installment_hold;

    procedure resume_installment (
        p_installment_id            in hr_emp_charge_installments.installment_id%type,
        p_remarks                   in varchar2 default null
    ) is
    begin
        update_installment_status(
            p_installment_id => p_installment_id,
            p_new_status     => 'PENDING',
            p_remarks        => p_remarks
        );

        update hr_emp_charge_installments
           set hold_from_dt = null,
               hold_to_dt   = null
         where installment_id = p_installment_id;
    end resume_installment;

    procedure mark_installment_waived (
        p_installment_id            in hr_emp_charge_installments.installment_id%type,
        p_remarks                   in varchar2 default null
    ) is
    begin
        update_installment_status(
            p_installment_id => p_installment_id,
            p_new_status     => 'WAIVED',
            p_remarks        => p_remarks
        );
    end mark_installment_waived;

    procedure mark_installment_bad_debt (
        p_installment_id            in hr_emp_charge_installments.installment_id%type,
        p_remarks                   in varchar2 default null
    ) is
    begin
        update_installment_status(
            p_installment_id => p_installment_id,
            p_new_status     => 'BAD_DEBT',
            p_remarks        => p_remarks
        );
    end mark_installment_bad_debt;

    procedure cancel_installment (
        p_installment_id            in hr_emp_charge_installments.installment_id%type,
        p_remarks                   in varchar2 default null
    ) is
    begin
        update_installment_status(
            p_installment_id => p_installment_id,
            p_new_status     => 'CANCELLED',
            p_remarks        => p_remarks
        );
    end cancel_installment;

    procedure cancel_charge (
        p_emp_charge_id             in hr_emp_charges.emp_charge_id%type,
        p_remarks                   in varchar2 default null
    ) is
        l_remarks varchar2(500);
    begin
        if p_emp_charge_id is null then
            raise_err('Charge is required.');
        end if;

        select remarks
          into l_remarks
          from hr_emp_charges
         where emp_charge_id = p_emp_charge_id;

        append_remarks(l_remarks, p_remarks);

        update hr_emp_charges
           set approval_status = 'CANCELLED',
               payroll_processed_yn = 'N',
               remarks = l_remarks
         where emp_charge_id = p_emp_charge_id;

        update hr_emp_charge_installments
           set status_code = 'CANCELLED'
         where emp_charge_id = p_emp_charge_id
           and status_code in ('PENDING','ON_HOLD');
    end cancel_charge;

    procedure mark_charge_bad_debt (
        p_emp_charge_id             in hr_emp_charges.emp_charge_id%type,
        p_remarks                   in varchar2 default null
    ) is
        l_remarks varchar2(500);
    begin
        if p_emp_charge_id is null then
            raise_err('Charge is required.');
        end if;

        select remarks
          into l_remarks
          from hr_emp_charges
         where emp_charge_id = p_emp_charge_id;

        append_remarks(l_remarks, p_remarks);

        update hr_emp_charges
           set approval_status = 'BAD_DEBT',
               payroll_processed_yn = 'Y',
               remarks = l_remarks
         where emp_charge_id = p_emp_charge_id;

        update hr_emp_charge_installments
           set status_code = 'BAD_DEBT'
         where emp_charge_id = p_emp_charge_id
           and status_code in ('PENDING','ON_HOLD');
    end mark_charge_bad_debt;

    function get_charge_balance (
        p_emp_charge_id             in hr_emp_charges.emp_charge_id%type
    ) return number is
        l_total     number;
        l_closed    number;
    begin
        select amount
          into l_total
          from hr_emp_charges
         where emp_charge_id = p_emp_charge_id;

        select nvl(sum(amount),0)
          into l_closed
          from hr_emp_charge_installments
         where emp_charge_id = p_emp_charge_id
           and status_code in ('PROCESSED','WAIVED','BAD_DEBT');

        return l_total - l_closed;
    exception
        when no_data_found then
            return 0;
    end get_charge_balance;

    procedure reschedule_remaining_installments (
    p_emp_charge_id      in hr_emp_charges.emp_charge_id%type,
    p_first_due_dt       in date,
    p_no_of_installments in number,
    p_remarks            in varchar2 default null
) is
    l_balance      number;
    l_base_amt     number;
    l_last_amt     number;
    l_max_inst_no  number;
begin
    if p_emp_charge_id is null then
        raise_err('Charge is required.');
    end if;

    if p_first_due_dt is null then
        raise_err('First due date is required.');
    end if;

    if nvl(p_no_of_installments,0) <= 0 then
        raise_err('Number of installments must be greater than zero.');
    end if;

    l_balance := get_charge_balance(p_emp_charge_id);

    if l_balance <= 0 then
        raise_err('No remaining balance is available for rescheduling.');
    end if;

    update hr_emp_charge_installments
       set status_code = 'CANCELLED',
           remarks = case
                       when remarks is null then p_remarks
                       when p_remarks is null then remarks
                       else remarks || ' | Rescheduled: ' || p_remarks
                     end
     where emp_charge_id = p_emp_charge_id
       and status_code in ('PENDING','ON_HOLD');

    select nvl(max(installment_no),0)
      into l_max_inst_no
      from hr_emp_charge_installments
     where emp_charge_id = p_emp_charge_id;

    l_base_amt := round(l_balance / p_no_of_installments, 2);
    l_last_amt := l_balance - (l_base_amt * (p_no_of_installments - 1));

    for i in 1 .. p_no_of_installments loop
        insert into hr_emp_charge_installments (
            emp_charge_id,
            installment_no,
            due_dt,
            amount,
            status_code,
            remarks
        ) values (
            p_emp_charge_id,
            l_max_inst_no + i,
            add_months(p_first_due_dt, i - 1),
            case when i = p_no_of_installments then l_last_amt else l_base_amt end,
            'PENDING',
            'Rescheduled remaining balance. ' || p_remarks
        );
    end loop;

    update hr_emp_charges
       set payroll_processed_yn = 'N',
           approval_status = case
                               when approval_status = 'CLOSED' then 'APPROVED'
                               else approval_status
                             end
     where emp_charge_id = p_emp_charge_id;
end;

end hr_charges_pkg;
/

create or replace package body hr_doc_pkg as

  procedure sync_identifier_from_doc(
    p_doc_id number
  ) is
    l_EMP_ID NUMBER;
    l_doc_type          hr_emp_docs.doc_type%type;
    l_doc_no            hr_emp_docs.doc_no%type;
    l_issue_dt          hr_emp_docs.issue_dt%type;
    l_expiry_dt         hr_emp_docs.expiry_dt%type;
    L_IDNT NUMBER;
  begin
    select EMP_ID,
           doc_type,
           doc_no,
           issue_dt,
           expiry_dt
      into l_EMP_ID,
           l_doc_type,
           l_doc_no,
           l_issue_dt,
           l_expiry_dt
      from hr_emp_docs
     where doc_id = p_doc_id;

    if  l_doc_type in ('PASSPORT','EID') then

    BEGIN
    SELECT COUNT(*)
    INTO L_IDNT
    FROM hr_emp_identifiers
    WHERE ID_TYPE= L_DOC_TYPE;
    END;

        IF NVL(L_IDNT,0) >0  THEN
                  update hr_emp_identifiers
                     set id_no      = nvl(l_doc_no, id_no),
                         issue_dt   = nvl(l_issue_dt, issue_dt),
                         expiry_dt  = nvl(l_expiry_dt, expiry_dt)
                         --updated_by = coalesce(sys_context('APEX$SESSION','APP_USER'), user),
                         --updated_dt = systimestamp
                   where EMP_ID = L_EMP_ID;
        ELSE
            INSERT INTO hr_emp_identifiers
       (
       EMP_ID,
       ID_TYPE,
       ID_NO,
       ISSUE_DT,
       EXPIRY_DT,
       IS_PRIMARY,
       STATUS
            )
            VALUES
            (
                L_EMP_ID,
                l_doc_type,
                l_doc_no,
                l_issue_dt,
                l_expiry_dt,
                'Y',
                'ACTIVE'
            );
      END IF;
    end if;
  exception
    when no_data_found then
      null;
  end sync_identifier_from_doc;

  procedure save_doc(
    p_doc_id            in out number,
    p_emp_id            in number,
    p_doc_type          in varchar2,
    p_doc_no            in varchar2,
    p_issue_dt          in date,
    p_expiry_dt         in date,
    p_is_current_record in varchar2,
    p_related_id_rec_id in number,
    p_file_ref          in varchar2,
    p_remarks           in varchar2
  ) is
  begin
    if p_doc_id is null then
      insert into hr_emp_docs (
        emp_id,
        doc_type,
        doc_no,
        issue_dt,
        expiry_dt,
        is_current_record,
        related_id_rec_id,
        file_ref,
        remarks,
        created_by,
        created_dt
      )
      values (
        p_emp_id,
        upper(trim(p_doc_type)),
        upper(trim(p_doc_no)),
        p_issue_dt,
        p_expiry_dt,
        nvl(p_is_current_record,'Y'),
        p_related_id_rec_id,
        p_file_ref,
        p_remarks,
        coalesce(sys_context('APEX$SESSION','APP_USER'), user),
        systimestamp
      )
      returning doc_id into p_doc_id;
    else
      update hr_emp_docs
         set doc_type          = upper(trim(p_doc_type)),
             doc_no            = upper(trim(p_doc_no)),
             issue_dt          = p_issue_dt,
             expiry_dt         = p_expiry_dt,
             is_current_record = nvl(p_is_current_record,'Y'),
             related_id_rec_id = p_related_id_rec_id,
             file_ref          = p_file_ref,
             remarks           = p_remarks,
             updated_by        = coalesce(sys_context('APEX$SESSION','APP_USER'), user),
             updated_dt        = systimestamp
       where doc_id = p_doc_id;
    end if;

    /*
      Make older same document inactive/current=N
      Rule = same employee + same doc type + same doc number
    */
    if p_doc_no is not null then
      update hr_emp_docs
         set 
             is_current_record = 'N',
             updated_by        = coalesce(sys_context('APEX$SESSION','APP_USER'), user),
             updated_dt        = systimestamp
       where emp_id   = p_emp_id
         and doc_type = upper(trim(p_doc_type))
         and upper(trim(nvl(doc_no,'~'))) = upper(trim(p_doc_no))
         and doc_id <> p_doc_id;
    end if;

    /*
      Force saved row as current if it is latest same doc
    */
    update hr_emp_docs
       set 
           is_current_record = 'Y',
           updated_by        = coalesce(sys_context('APEX$SESSION','APP_USER'), user),
           updated_dt        = systimestamp
     where doc_id = p_doc_id;

    sync_identifier_from_doc(p_doc_id);

  end save_doc;

end hr_doc_pkg;
/

create or replace package body              hr_emp_api as
  procedure change_status(
    p_emp_id         number,
    p_action_type    varchar2,
    p_target_status  varchar2,
    p_reason         varchar2,
    p_amount         number,
    p_effective_dt   date,
    p_attachment_ref varchar2
  ) is
    l_user varchar2(100) := coalesce(sys_context('APEX$SESSION','APP_USER'), user);
    l_ok   number;
  begin
    -- ACL check: user must have any role allowed for this status
    select count(*)
      into l_ok
      from hr_status_acl a
     where a.status_code = upper(trim(p_target_status))
       and a.can_set='Y'
       and a.is_active='Y'
       and exists (
         select 1
           from sec_user_roles ur
          where upper(ur.user_id)  = sec_ctx.user_id
            and (ur.role_id) = (a.role_code)
       );

    if l_ok = 0 then
      raise_application_error(-20010, 'Not allowed to set status '||upper(trim(p_target_status))||'.');
    end if;

    insert into hr_emp_actions(emp_id, action_type, target_status, action_dt, amount, remarks, attachment_ref, status)
    values (p_emp_id,
            upper(trim(p_action_type)),
            upper(trim(p_target_status)),
            p_effective_dt,
            p_amount,
            p_reason,
            p_attachment_ref,
            'DONE');

    hr_status_pkg.set_status(
      p_emp_id         => p_emp_id,
      p_status_code    => p_target_status,
      p_effective_from => p_effective_dt,
      p_reason         => p_action_type,
      p_remarks        => 'Manual (no approval) by '||l_user||case when p_reason is not null then ' | '||p_reason end
    );
  end;
end;
/

create or replace package body hr_emp_pkg as
----------No need for it
  function can_change_status(
    p_role_code   varchar2,
    p_status_code varchar2
  ) return varchar2
  is
    l_cnt number;
  begin
    select count(*)
      into l_cnt
      from hr_status_acl
     where upper(role_code)   = upper(p_role_code)
       and upper(status_code) = upper(p_status_code)
       and can_set = 'Y';

    return case when l_cnt > 0 then 'Y' else 'N' end;
  end;

  /*procedure change_status(
    p_emp_id number,
    p_status_code varchar2,
    p_effective_from date,
    p_reason varchar2,
    p_remarks varchar2,
    P_PROJECT_ID NUMBER,
    P_CITY_ID NUMBER,
    P_LEAVE_START DATE,
    P_LEAVE_END DATE,
    P_LEAVE_TYPE varchar2
  ) is
  begin
    update hr_emp_status_hist
       set effective_to = p_effective_from - 1
     where emp_id = p_emp_id
       and effective_to is null;

    insert into hr_emp_status_hist(emp_id, status_code, effective_from, effective_to, reason, remarks, project_id, city_id, leave_start_date, leave_end_date, leave_reason)
    values (p_emp_id, upper(trim(p_status_code)), p_effective_from, null, p_reason, p_remarks,P_PROJECT_ID,P_CITY_ID,P_LEAVE_START, P_LEAVE_END,P_LEAVE_TYPE);
  end;
*/

  procedure apply_status(
    p_emp_id          number,
    p_new_status_code varchar2,
    p_effective_from  date,
    p_reason          varchar2,
    p_remarks         varchar2,
    p_role_code       varchar2,
     P_PROJECT_ID NUMBER,
    P_CITY_ID NUMBER,
    P_LEAVE_START DATE,
    P_LEAVE_END DATE,
    P_LEAVE_TYPE varchar2
  )
  is
    l_user_changeable char(1);
  begin
    select user_changeable
      into l_user_changeable
      from hr_status_master
     where status_code = upper(trim(p_new_status_code));

    if l_user_changeable <> 'Y' then
      raise_application_error(-20011, 'This status can only be changed by system.');
    end if;

    if can_change_status(p_role_code, p_new_status_code) <> 'Y' then
      raise_application_error(-20010, 'You are not allowed to set this status.');
    end if;

  /*  hr_status_pkg.set_status(
      p_emp_id          => p_emp_id,
      p_new_status_code => p_new_status_code,
      p_effective_from  => p_effective_from,
      p_reason          => p_reason,
      p_remarks         => p_remarks
    );
    */
  end;

  procedure set_system_status(
    p_emp_id          number,
    p_new_status_code varchar2,
    p_effective_from  date,
    p_reason          varchar2,
    p_remarks         varchar2
  )
  is
    l_status_type varchar2(20);
  begin
    select status_type
      into l_status_type
      from hr_status_master
     where status_code = upper(trim(p_new_status_code));

    if l_status_type <> 'SYSTEM' then
      raise_application_error(-20012, 'Only system statuses are allowed in set_system_status.');
    end if;

   /* change_status(
      p_emp_id          => p_emp_id,
      p_new_status_code => p_new_status_code,
      p_effective_from  => p_effective_from,
      p_reason          => p_reason,
      p_remarks         => p_remarks
    );*/
  end;

--------- Legal Status 
procedure apply_legal_status(
    p_emp_id          number,
    p_new_status_code varchar2,
    p_effective_from  date,
    p_reason          varchar2,
    p_remarks         varchar2
  )
  is
  begin
    update hr_emp_legal_status_hist
       set effective_to = p_effective_from - 1
     where emp_id = p_emp_id
       and effective_to is null;

    insert into hr_emp_legal_status_hist (
      emp_id,
      status_code,
      effective_from,
      effective_to,
      reason,
      remarks
    )
    values (
      p_emp_id,
      upper(trim(p_new_status_code)),
      p_effective_from,
      null,
      p_reason,
      p_remarks
    );
  end;

  procedure change_legal_status(
    p_emp_id          number,
    p_new_status_code varchar2,
    p_effective_from  date,
    p_reason          varchar2,
    p_remarks         varchar2,
    p_role_code       varchar2
  )
  is
    l_user_changeable char(1);
  begin
    select user_changeable
      into l_user_changeable
      from hr_status_master
     where status_code = upper(trim(p_new_status_code));

    if l_user_changeable <> 'Y' then
      raise_application_error(-20011, 'This status can only be changed by system.');
    end if;

    if can_change_status(p_role_code, p_new_status_code) <> 'Y' then
      raise_application_error(-20010, 'You are not allowed to set this status.');
    end if;

    apply_legal_status(
      p_emp_id          => p_emp_id,
      p_new_status_code => p_new_status_code,
      p_effective_from  => p_effective_from,
      p_reason          => p_reason,
      p_remarks         => p_remarks
    );
  end;

  procedure set_system_legal_status(
    p_emp_id          number,
    p_new_status_code varchar2,
    p_effective_from  date,
    p_reason          varchar2,
    p_remarks         varchar2
  )
  is
    l_status_type varchar2(20);
  begin
    select status_type
      into l_status_type
      from hr_status_master
     where status_code = upper(trim(p_new_status_code));

    if l_status_type <> 'SYSTEM' then
      raise_application_error(-20012, 'Only system statuses are allowed in set_system_status.');
    end if;

    apply_legal_status(
      p_emp_id          => p_emp_id,
      p_new_status_code => p_new_status_code,
      p_effective_from  => p_effective_from,
      p_reason          => p_reason,
      p_remarks         => p_remarks
    );
  end;

end;
/

create or replace package body hr_legal_profile_pkg as

    procedure ensure_profile (
        p_emp_id in number
    ) is
    begin
        insert into hr_emp_legal_profile (
            emp_id,
            legal_worker_type,
            legal_org_id,
            legal_status,
            legal_status_reason,
            legal_status_dt,
            wps_required_yn,
            wps_status,
            default_wps_clearing_mode,
            wps_effective_from_dt,
            created_by,
            created_dt
        )
        select e.emp_id,
               case
                   when nvl(e.worker_type,'DIRECT') = 'SUBCONTRACT' then 'SUBCONTRACT'
                   else 'OWN_VISA'
               end as legal_worker_type,
               null as legal_org_id,
               'IN_PROCESS' as legal_status,
               'Initial legal profile created' as legal_status_reason,
               trunc(cast(systimestamp at time zone 'Asia/Dubai' as date)) as legal_status_dt,
               'Y' as wps_required_yn,
               'SETUP_PENDING' as wps_status,
               case
                   when nvl(e.worker_type,'DIRECT') = 'SUBCONTRACT' then 'SUPPLIER_WPS'
                   else 'INTERNAL_WPS'
               end as default_wps_clearing_mode,
               trunc(cast(systimestamp at time zone 'Asia/Dubai' as date)) as wps_effective_from_dt,
               nvl(v('APP_USER'), user) as created_by,
               cast(systimestamp at time zone 'Asia/Dubai' as timestamp) as created_dt
          from hr_employees e
         where e.emp_id = p_emp_id
           and not exists (
                select 1
                  from hr_emp_legal_profile lp
                 where lp.emp_id = e.emp_id
           );
    end ensure_profile;


    procedure ensure_all_profiles is
    begin
        for r in (
            select emp_id
              from hr_employees
        ) loop
            ensure_profile(r.emp_id);
        end loop;
    end ensure_all_profiles;

end hr_legal_profile_pkg;
/

create or replace package body hr_legal_status_sync_pkg as

    procedure sync_working_status (
        p_emp_id       in number,
        p_legal_status in varchar2,
        p_reason       in varchar2 default null
    ) is
        l_active_assignment number := 0;
        l_current_status    varchar2(30);
        l_new_status        varchar2(30);
        l_legal_norm        varchar2(50);
        l_now               date := cast(systimestamp at time zone 'Asia/Dubai' as date);
    begin
        ------------------------------------------------------------------
        -- Normalize legal status
        -- Supports both LEGAL_ABSCONDING and ABSCONDING
        ------------------------------------------------------------------
        l_legal_norm := p_legal_status;--replace(upper(nvl(p_legal_status, 'NOT_SET')), 'LEGAL_', '');

        ------------------------------------------------------------------
        -- Check active assignment
        ------------------------------------------------------------------
        BEGIN 
        select count(*)
          into l_active_assignment
          from hr_assignments
         where emp_id = p_emp_id
           and end_dt is null;
           EXCEPTION WHEN OTHERS THEN l_active_assignment:=0;
           END;

        ------------------------------------------------------------------
        -- Get current working status
        ------------------------------------------------------------------
        begin
            select status_code
              into l_current_status
              from (
                    select status_code
                      from hr_emp_status_hist
                     where emp_id = p_emp_id
                       and effective_to is null
                     order by effective_from desc, status_id desc
                   )
             where rownum = 1;
        exception
            when no_data_found then
                l_current_status := null;
        end;

        ------------------------------------------------------------------
        -- If employee still has active assignment, do not auto-change
        -- Legal status can still remain Absconding as risk badge.
        ------------------------------------------------------------------
        if l_active_assignment > 0 then
            return;
        end if;

        ------------------------------------------------------------------
        -- Decide new working status
        ------------------------------------------------------------------
        if l_legal_norm in ('ABSCONDING', 'ABSCONDER') then
            l_new_status := 'ABS';

        elsif l_legal_norm in ('CANCELLED', 'CANCELLED_MOHRE', 'CANCELLED_ICP') then
            l_new_status := 'INACTIVE';

        else
            return;
        end if;

        ------------------------------------------------------------------
        -- Avoid duplicate current status
        ------------------------------------------------------------------
        if upper(nvl(l_current_status, 'X')) = l_new_status then
            return;
        end if;

        ------------------------------------------------------------------
        -- Close current working status
        ------------------------------------------------------------------
        update hr_emp_status_hist
           set effective_to = l_now
         where emp_id = p_emp_id
           and effective_to is null;

        ------------------------------------------------------------------
        -- Insert new working status
        ------------------------------------------------------------------
        insert into hr_emp_status_hist (
            emp_id,
            status_code,
            effective_from,
            effective_to,
            remarks
        )
        values (
            p_emp_id,
            l_new_status,
            l_now,
            null,
            'Auto updated from legal status: ' || p_legal_status ||
            case
                when p_reason is not null then ' - ' || p_reason
                else null
            end
        );

    end sync_working_status;

end hr_legal_status_sync_pkg;
/

create or replace package body hr_loan_app_pkg as

    function esc (
        p_text in varchar2
    ) return varchar2
    is
    begin
        return apex_escape.html(nvl(p_text, '-'));
    end esc;


    function amount_text (
        p_amount in number
    ) return varchar2
    is
    begin
        return 'AED ' || trim(to_char(nvl(p_amount, 0), '999G999G999G990D00'));
    end amount_text;


    function txn_type_name (
        p_txn_type in varchar2
    ) return varchar2
    is
    begin
        return case p_txn_type
                 when 'MANUAL_PAYMENT'     then 'Manual Payment'
                 when 'WAIVER'             then 'Waiver'
                 when 'ADJUSTMENT'         then 'Adjustment'
                 when 'REVERSAL'           then 'Reversal'
                 when 'BAD_DEBT_WRITE_OFF' then 'Bad Debt Write-off'
                 when 'PAYROLL_DEDUCTION'  then 'Payroll Deduction'
                 else nvl(p_txn_type, '-')
               end;
    end txn_type_name;


    function get_subject (
        p_record_pk in number
    ) return varchar2
    is
        l_loan_no       hr_emp_loans.loan_no%type;
        l_employee_name varchar2(300);
        l_txn_type      varchar2(40);
        l_amount        number;
    begin
        select l.loan_no,
               e.emp_code || ' - ' || trim(e.first_name || ' ' || e.last_name),
               t.txn_type,
               t.amount
          into l_loan_no,
               l_employee_name,
               l_txn_type,
               l_amount
          from hr_emp_loan_txns t
          join hr_emp_loans l
            on l.loan_id = t.loan_id
          join hr_employees e
            on e.emp_id = t.emp_id
         where t.loan_txn_id = p_record_pk;

        return 'Loan ' || txn_type_name(l_txn_type) ||
               ' Approval - ' || l_loan_no ||
               ' - ' || l_employee_name ||
               ' - ' || amount_text(l_amount);

    exception
        when no_data_found then
            return 'Loan Transaction Approval';
    end get_subject;


    function get_full_detail_url (
        p_record_pk in number
    ) return varchar2
    is
        l_loan_id number;
    begin
        select loan_id
          into l_loan_id
          from hr_emp_loan_txns
         where loan_txn_id = p_record_pk;

        return apex_page.get_url(
            p_page        => 172,
            p_items       => 'P172_LOAN_TXN_ID',
            p_values      => p_record_pk,
            p_clear_cache => '172'
        );

    exception
        when no_data_found then
            return null;
    end get_full_detail_url;


    procedure submit_for_approval (
        p_loan_txn_id in number
    )
    is
        l_approval_id number;
        l_exists      number;
    begin
        for r in (
            select t.loan_txn_id,
                   t.loan_id,
                   t.txn_type,
                   t.amount,
                   t.approval_status,
                   l.loan_no
              from hr_emp_loan_txns t
              join hr_emp_loans l
                on l.loan_id = t.loan_id
             where t.loan_txn_id = p_loan_txn_id
        )
        loop
            if r.approval_status not in ('DRAFT', 'REJECTED', 'SUBMITTED') then
                raise_application_error(
                    -20851,
                    'Only Draft or Rejected loan transaction can be submitted for approval.'
                );
            end if;

            select count(*)
              into l_exists
              from hr_approval_requests
             where module_code = 'LOAN_TXN'
               and record_pk = p_loan_txn_id
               and request_status in ('SUBMITTED', 'PENDING', 'IN_PROGRESS');

            if l_exists > 0 then
                raise_application_error(
                    -20852,
                    'Approval request already exists for this loan transaction.'
                );
            end if;

            update hr_emp_loan_txns
               set approval_status = 'SUBMITTED',
                   updated_by      = nvl(sys_context('APEX$SESSION','APP_USER'), user),
                   updated_dt      = cast(systimestamp at time zone 'Asia/Dubai' as timestamp)
             where loan_txn_id = p_loan_txn_id;

            /*
              For loan approval, ORG_ID is null for now.
              So your approval rule for LOAN_TXN should have ORG_ID null.
            */
            hr_approval_wf_pkg.start_approval(
                p_module_code   => 'LOAN_TXN',
                p_record_pk     => p_loan_txn_id,
                p_txn_type_code => r.txn_type,
                p_org_id        => null,
                p_amount        => r.amount,
                p_subject       => get_subject(p_loan_txn_id),
                p_approval_id   => l_approval_id
            );

            return;
        end loop;

        raise_application_error(-20853, 'Loan transaction request not found.');
    end submit_for_approval;


    function render_summary (
        p_record_pk   in number,
        p_approval_id in number default null
    ) return clob
    is
        l_html clob;
        l_url  varchar2(4000);
    begin
        for r in (
            select t.loan_txn_id,
                   t.txn_type,
                   t.amount,
                   t.pay_mode,
                   t.reference_no,
                   t.approval_status,
                   t.remarks,
                   t.txn_date,
                   t.reversal_of_txn_id,
                   l.loan_no,
                   v.emp_code,
                   v.employee_name,
                   v.loan_type,
                   v.loan_amount,
                   v.emi_amount,
                   v.paid_amount,
                   v.waived_amount,
                   v.bad_debt_amount,
                   v.balance_amount
              from hr_emp_loan_txns t
              join hr_emp_loans l
                on l.loan_id = t.loan_id
              join hr_emp_loan_v v
                on v.loan_id = t.loan_id
             where t.loan_txn_id = p_record_pk
        )
        loop
            l_url := get_full_detail_url(p_record_pk);

            l_html :=
            '<div class="appr-summary-box">' ||

            '  <div class="appr-summary-title">' ||
            '    <div>' ||
            '      <span class="appr-summary-main">' || esc(r.loan_no) || '</span>' ||
            '      <span class="appr-summary-sub">Loan Transaction Approval</span>' ||
            '    </div>' ||
            '    <div class="appr-header-actions">' ||
            case
                when l_url is not null then
                    '      <a class="appr-open-detail" href="' || apex_escape.html_attribute(l_url) || '" target="_blank">' ||
                    '        <span class="fa fa-external-link"></span> Full Detail' ||
                    '      </a>'
                else null
            end ||
            '      <span class="appr-status-simple">' || esc(r.approval_status) || '</span>' ||
            '    </div>' ||
            '  </div>' ||

            '  <div class="appr-grid4">' ||

            '    <div class="appr-cell">' ||
            '      <div class="appr-cell-label">Employee</div>' ||
            '      <div class="appr-cell-value">' || esc(r.emp_code || ' - ' || r.employee_name) || '</div>' ||
            '    </div>' ||

            '    <div class="appr-cell">' ||
            '      <div class="appr-cell-label">Transaction Type</div>' ||
            '      <div class="appr-cell-value">' || esc(txn_type_name(r.txn_type)) || '</div>' ||
            '    </div>' ||

            '    <div class="appr-cell amount">' ||
            '      <div class="appr-cell-label">Request Amount</div>' ||
            '      <div class="appr-cell-value">' || amount_text(r.amount) || '</div>' ||
            '    </div>' ||

            '    <div class="appr-cell amount">' ||
            '      <div class="appr-cell-label">Current Balance</div>' ||
            '      <div class="appr-cell-value">' || amount_text(r.balance_amount) || '</div>' ||
            '    </div>' ||

            '    <div class="appr-cell amount">' ||
            '      <div class="appr-cell-label">Loan Amount</div>' ||
            '      <div class="appr-cell-value">' || amount_text(r.loan_amount) || '</div>' ||
            '    </div>' ||

            '    <div class="appr-cell amount">' ||
            '      <div class="appr-cell-label">Paid Amount</div>' ||
            '      <div class="appr-cell-value">' || amount_text(r.paid_amount) || '</div>' ||
            '    </div>' ||

            '    <div class="appr-cell amount">' ||
            '      <div class="appr-cell-label">Waived Amount</div>' ||
            '      <div class="appr-cell-value">' || amount_text(r.waived_amount) || '</div>' ||
            '    </div>' ||

            '    <div class="appr-cell amount">' ||
            '      <div class="appr-cell-label">Bad Debt</div>' ||
            '      <div class="appr-cell-value">' || amount_text(r.bad_debt_amount) || '</div>' ||
            '    </div>' ||

            '    <div class="appr-cell">' ||
            '      <div class="appr-cell-label">Pay Mode</div>' ||
            '      <div class="appr-cell-value">' || esc(r.pay_mode) || '</div>' ||
            '    </div>' ||

            '    <div class="appr-cell">' ||
            '      <div class="appr-cell-label">Reference No</div>' ||
            '      <div class="appr-cell-value">' || esc(r.reference_no) || '</div>' ||
            '    </div>' ||

            '    <div class="appr-cell">' ||
            '      <div class="appr-cell-label">Transaction Date</div>' ||
            '      <div class="appr-cell-value">' || esc(to_char(r.txn_date, 'DD-MON-YYYY')) || '</div>' ||
            '    </div>' ||

            '    <div class="appr-cell">' ||
            '      <div class="appr-cell-label">Loan Type</div>' ||
            '      <div class="appr-cell-value">' || esc(r.loan_type) || '</div>' ||
            '    </div>';

            if r.reversal_of_txn_id is not null then
                l_html := l_html ||
                '    <div class="appr-cell">' ||
                '      <div class="appr-cell-label">Reversal Of</div>' ||
                '      <div class="appr-cell-value">' || esc(to_char(r.reversal_of_txn_id)) || '</div>' ||
                '    </div>';
            end if;

            if r.remarks is not null then
                l_html := l_html ||
                '    <div class="appr-cell appr-cell-wide">' ||
                '      <div class="appr-cell-label">Reason / Remarks</div>' ||
                '      <div class="appr-cell-value">' || esc(r.remarks) || '</div>' ||
                '    </div>';
            end if;

            l_html := l_html ||
            '  </div>' ||
            '</div>';

            return l_html;
        end loop;

        return
            '<div class="appr-summary-box">' ||
            '  <div class="appr-summary-title">Loan transaction details not found</div>' ||
            '</div>';
    end render_summary;


    function render_extra_details (
        p_record_pk   in number,
        p_approval_id in number default null
    ) return clob
    is
    begin
        return null;
    end render_extra_details;


