/

ALTER TRIGGER "TRG_HR_EMPLOYEES_BIU" ENABLE;

CREATE OR REPLACE EDITIONABLE TRIGGER "TRG_HR_GROUPS_BIU" 
before insert or update
on hr_groups
for each row
begin

    -- INSERT
    if inserting then

        :new.created_by :=
            nvl(
                sys_context('APEX$SESSION','APP_USER'),
                user
            );

        :new.created_dt :=
            cast(systimestamp at time zone 'Asia/Dubai' as timestamp);

        -- default active
        if :new.is_active is null then
            :new.is_active := 'Y';
        end if;

    end if;


    -- UPDATE
    if updating then

        :new.updated_by :=
            nvl(
                sys_context('APEX$SESSION','APP_USER'),
                user
            );

        :new.updated_dt :=
            cast(systimestamp at time zone 'Asia/Dubai' as timestamp);

    end if;

end;
/

ALTER TRIGGER "TRG_HR_GROUPS_BIU" ENABLE;

CREATE OR REPLACE EDITIONABLE TRIGGER "TRG_HR_ORG_DOC_CURRENT" 
after insert or update of is_current on hr_org_docs
for each row
begin
  if :new.is_current = 'Y' then
    update hr_org_docs
       set is_current = 'N',
           updated_by = coalesce(sys_context('APEX$SESSION','APP_USER'), user),
           updated_dt = systimestamp
     where org_id = :new.org_id
       and doc_type_code = :new.doc_type_code
       and org_doc_id <> :new.org_doc_id
       and is_current = 'Y';
  end if;
end;
/

ALTER TRIGGER "TRG_HR_ORG_DOC_CURRENT" ENABLE;

CREATE OR REPLACE EDITIONABLE TRIGGER "TRG_HR_ORG_DOC_TYPE_BIU" 
before insert or update
on hr_org_doc_type_master
for each row
begin
    :new.doc_type_code := upper(trim(:new.doc_type_code));

    if inserting then
        :new.created_by := nvl(sys_context('APEX$SESSION','APP_USER'), user);
        :new.created_dt := cast(systimestamp at time zone 'Asia/Dubai' as timestamp);

        if :new.is_active is null then
            :new.is_active := 'Y';
        end if;

        if :new.is_expirable is null then
            :new.is_expirable := 'Y';
        end if;
    end if;

    if updating then
        :new.updated_by := nvl(sys_context('APEX$SESSION','APP_USER'), user);
        :new.updated_dt := cast(systimestamp at time zone 'Asia/Dubai' as timestamp);
    end if;
end;
/

ALTER TRIGGER "TRG_HR_ORG_DOC_TYPE_BIU" ENABLE;

CREATE OR REPLACE EDITIONABLE TRIGGER "TRG_HR_PRO_DEALS_BIU" 
before insert or update on hr_pro_deals
for each row
declare
    l_year varchar2(4);
begin
    l_year := to_char(cast(systimestamp at time zone 'Asia/Dubai' as timestamp), 'YYYY');

    if inserting then
        if :new.deal_no is null then
            :new.deal_no := 'DEAL-' || l_year || '-' || lpad(hr_pro_deal_seq.nextval, 6, '0');
        end if;

        :new.created_by := nvl(sys_context('APEX$SESSION','APP_USER'), user);
        :new.created_dt := cast(systimestamp at time zone 'Asia/Dubai' as timestamp);

        :new.approval_status    := nvl(:new.approval_status,'DRAFT');
        :new.agreement_required := nvl(:new.agreement_required,'Y');
        :new.agreement_printed  := nvl(:new.agreement_printed,'N');
        :new.agreement_signed   := nvl(:new.agreement_signed,'N');
        :new.loan_created       := nvl(:new.loan_created,'N');
        :new.pro_case_created   := nvl(:new.pro_case_created,'N');

        if :new.recoverable is null then
            select default_recoverable
              into :new.recoverable
              from hr_pro_deal_type_master
             where deal_type_code = :new.deal_type_code;
        end if;
    end if;

    if updating then
        :new.updated_by := nvl(sys_context('APEX$SESSION','APP_USER'), user);
        :new.updated_dt := cast(systimestamp at time zone 'Asia/Dubai' as timestamp);
    end if;
end;
/

ALTER TRIGGER "TRG_HR_PRO_DEALS_BIU" ENABLE;

CREATE OR REPLACE EDITIONABLE TRIGGER "TRG_HR_SIM_ASSIGN_CTL" 
for insert or update on hr_sim_assignments
compound trigger

    type t_emp_tab is table of number index by pls_integer;
    g_emp_ids t_emp_tab;
    g_idx     pls_integer := 0;

    function app_user return varchar2 is
    begin
        return nvl(sys_context('APEX$SESSION','APP_USER'), user);
    end;

    function uae_now return date is
    begin
        return cast(systimestamp at time zone 'Asia/Dubai' as date);
    end;

    procedure add_emp(p_emp_id number) is
    begin
        if p_emp_id is not null then
            g_idx := g_idx + 1;
            g_emp_ids(g_idx) := p_emp_id;
        end if;
    end;

before each row is
    l_sim_status varchar2(30);
begin
    if inserting then
        :new.created_by    := nvl(:new.created_by, app_user);
        :new.created_dt    := nvl(:new.created_dt, uae_now);
        :new.assigned_by   := nvl(:new.assigned_by, app_user);
        :new.assign_dt     := nvl(:new.assign_dt, uae_now);
        :new.assign_reason := nvl(:new.assign_reason, 'NEW_ISSUE');
    end if;

    if updating then
        if :old.return_dt is null
           and :new.return_dt is not null
           and :new.return_by is null then
            :new.return_by := app_user;
        end if;
    end if;

    :new.updated_by := app_user;
    :new.updated_dt := uae_now;

    :new.assign_reason    := upper(trim(:new.assign_reason));
    :new.return_reason    := upper(trim(:new.return_reason));
    :new.return_condition := upper(trim(:new.return_condition));

    ------------------------------------------------------------------
    -- Check SIM availability only when creating active assignment
    ------------------------------------------------------------------
    if :new.return_dt is null then

        if inserting then
            select sim_status_code
              into l_sim_status
              from fleet_sims
             where sim_id = :new.sim_id
             for update;

            if l_sim_status <> 'AVAILABLE' then
                raise_application_error(
                    -20001,
                    'SIM is not available for assignment.'
                );
            end if;
        end if;

        add_emp(:new.emp_id);
    end if;

    if updating then
        add_emp(:old.emp_id);
        add_emp(:new.emp_id);
    end if;
end before each row;

after statement is
    l_allowed_sims number;
    l_active_sims  number;
begin
    for i in 1 .. g_idx loop

        l_allowed_sims := 1;

        begin
            select max_active_sims
              into l_allowed_sims
              from (
                    select max_active_sims
                      from hr_emp_sim_allowances
                     where emp_id = g_emp_ids(i)
                       and is_active = 'Y'
                       and trunc(sysdate) between trunc(effective_from)
                                           and nvl(trunc(effective_to), date '4712-12-31')
                     order by effective_from desc, allowance_id desc
                   )
             where rownum = 1;
        exception
            when no_data_found then
                l_allowed_sims := 1;
        end;

        select count(*)
          into l_active_sims
          from hr_sim_assignments
         where emp_id = g_emp_ids(i)
           and return_dt is null;

        if l_active_sims > l_allowed_sims then
            raise_application_error(
                -20001,
                'Employee is allowed only ' || l_allowed_sims ||
                ' active SIM(s). Please add management SIM allowance before assigning additional SIM.'
            );
        end if;

    end loop;
end after statement;

end trg_hr_sim_assign_ctl;
/

ALTER TRIGGER "TRG_HR_SIM_ASSIGN_CTL" ENABLE;

CREATE OR REPLACE EDITIONABLE TRIGGER "TRG_HR_SIM_ASSIGN_STATUS_AIU" 
after insert or update of return_dt, return_reason, return_condition
on hr_sim_assignments
for each row
declare
    l_new_status varchar2(30);
begin
    if inserting then

        if :new.return_dt is null then
            update fleet_sims
               set sim_status_code = 'ASSIGNED',
                   updated_by      = nvl(sys_context('APEX$SESSION','APP_USER'), user),
                   updated_dt      = cast(systimestamp at time zone 'Asia/Dubai' as date)
             where sim_id = :new.sim_id;
        end if;

    elsif updating then

        if :old.return_dt is null
           and :new.return_dt is not null then

            l_new_status :=
                case
                    when :new.return_reason = 'LOST'
                      or :new.return_condition = 'LOST'
                    then 'LOST'

                    when :new.return_reason = 'DAMAGED'
                      or :new.return_condition = 'DAMAGED'
                    then 'DAMAGED'

                    when :new.return_reason = 'CANCELLED'
                      or :new.return_condition = 'CANCELLED'
                    then 'CANCELLED'

                    when :new.return_condition = 'BLOCKED'
                    then 'BLOCKED'

                    else 'AVAILABLE'
                end;

            update fleet_sims
               set sim_status_code = l_new_status,
                   updated_by      = nvl(sys_context('APEX$SESSION','APP_USER'), user),
                   updated_dt      = cast(systimestamp at time zone 'Asia/Dubai' as date)
             where sim_id = :new.sim_id;

        end if;

    end if;
end;
/

ALTER TRIGGER "TRG_HR_SIM_ASSIGN_STATUS_AIU" ENABLE;

CREATE OR REPLACE EDITIONABLE TRIGGER "TRG_HR_SIM_REQUESTS_BIU" 
before insert or update on hr_sim_requests
for each row
declare
    l_user varchar2(100);
    l_now  date;
begin
    l_user := nvl(sys_context('APEX$SESSION','APP_USER'), user);
    l_now  := cast(systimestamp at time zone 'Asia/Dubai' as date);

    if inserting then
        :new.created_by     := nvl(:new.created_by, l_user);
        :new.created_dt     := nvl(:new.created_dt, l_now);
        :new.requested_by   := nvl(:new.requested_by, l_user);
        :new.requested_dt   := nvl(:new.requested_dt, l_now);
        :new.request_status := nvl(:new.request_status, 'OPEN');
        :new.priority       := nvl(:new.priority, 'NORMAL');
    end if;

    :new.updated_by := l_user;
    :new.updated_dt := l_now;

    :new.request_type   := upper(trim(:new.request_type));
    :new.request_status := upper(trim(:new.request_status));
    :new.priority       := upper(trim(:new.priority));
    :new.reason_code    := upper(trim(:new.reason_code));
end;
/

ALTER TRIGGER "TRG_HR_SIM_REQUESTS_BIU" ENABLE;

CREATE OR REPLACE EDITIONABLE TRIGGER "TRG_LEGAL_PROFILE_SYNC_STATUS" 
after insert or update of legal_status
on hr_emp_legal_profile
for each row
begin
    if inserting
       or nvl(:old.legal_status, 'X') <> nvl(:new.legal_status, 'X')
    then
        hr_legal_status_sync_pkg.sync_working_status(
            p_emp_id       => :new.emp_id,
            p_legal_status => :new.legal_status,
            p_reason       => :new.legal_status_reason
        );
    end if;
end;
/

ALTER TRIGGER "TRG_LEGAL_PROFILE_SYNC_STATUS" ENABLE;
